INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C1','math',4,1,'u2',2,'각의 크기 — 꼭짓점에서 두 변이 벌어진 정도이며, 변의 길이나 각이 놓인 방향과는 상관없다',ARRAY['4수02-05']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C2','math',4,1,'u2',2,'각의 크기 비교 — 눈으로, 꼭짓점과 한 변을 맞춰 겹쳐서, 같은 크기의 단위 각이 몇 번 들어가는지 세어 각의 크기를 견준다',ARRAY['4수02-05']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C3','math',4,1,'u2',2,'1도와 직각·한 바퀴 — 한 바퀴를 똑같이 360으로 나눈 한 칸을 1도(1°)라 하고, 직각은 90°, 일직선(반 바퀴)은 180°, 한 바퀴는 360°이다',ARRAY['4수02-05']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C4','math',4,1,'u2',3,'각도기로 각 재기 — 각도기의 중심을 꼭짓점에, 밑금을 한 변에 맞추고, 그 변이 0인 쪽 눈금을 따라 다른 변이 가리키는 눈금을 읽는다(변이 짧으면 늘인다)',ARRAY['4수02-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C5','math',4,1,'u2',4,'예각과 둔각 — 직각(90°)을 기준으로 0°보다 크고 90°보다 작은 각은 예각, 90°보다 크고 180°보다 작은 각은 둔각이며, 직각과 일직선은 둘 다 아니다',ARRAY['4수02-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C6','math',4,1,'u2',5,'각도 어림하기 — 90°·45°(직각의 반)·135° 같은 기준 각과 견주어 약 몇 도인지 어림하고, 각도기로 재어 확인하며 잰 값과 가까울수록 잘 어림한 것이다',ARRAY['4수02-05']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C7','math',4,1,'u2',6,'각도의 합과 차 — 각도의 합과 차는 자연수의 덧셈·뺄셈처럼 계산하고 °를 붙이며, 일직선 180°·한 바퀴 360°를 이용해 모르는 각을 구한다',ARRAY['4수02-05']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C8','math',4,1,'u2',7,'삼각형의 세 각의 크기의 합 — 삼각형의 모양·크기와 상관없이 세 각의 크기의 합은 180°이고(세 각을 모으면 일직선), 두 각을 알면 나머지 한 각을 구한다',ARRAY['4수02-05']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C9','math',4,1,'u2',8,'사각형의 네 각의 크기의 합 — 사각형은 대각선으로 삼각형 2개로 나뉘므로 네 각의 크기의 합은 360°이고(네 각을 모으면 한 바퀴), 세 각을 알면 나머지 한 각을 구한다',ARRAY['4수02-05']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u2-C10','math',4,1,'u2',9,'삼각자로 각 만들기 — 삼각자의 각(45°·45°·90° / 30°·60°·90°)을 붙이면 두 각의 합, 겹치면 두 각의 차가 되며, 이렇게 만든 각은 모두 15°의 배수이다',ARRAY['4수02-05']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X01','math',4,'u2',ARRAY['M4-1-u2-C1','M4-1-u2-C2','M4-1-u2-C4']::text[],'변이 길수록(그림이 클수록) 큰 각이라고 생각한다 — 변을 늘이면 각도 커진다고 한다','변의 길이 말고 벌어진 정도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X02','math',4,'u2',ARRAY['M4-1-u2-C1','M4-1-u2-C2','M4-1-u2-C5']::text[],'각이 놓인 방향이 바뀌면 각의 크기나 종류도 바뀐다고 생각한다 — 비스듬히 놓인 직각은 직각이 아니라고 한다','돌려 놓아도 벌어진 정도는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X03','math',4,'u2',ARRAY['M4-1-u2-C2']::text[],'두 각을 겹쳐 견줄 때 꼭짓점과 한 변을 맞추지 않고 변의 끝을 맞추거나 아무렇게나 포갠다','꼭짓점과 한 변 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X04','math',4,'u2',ARRAY['M4-1-u2-C2']::text[],'단위 각의 크기가 다른데 들어간 칸 수만으로 견주거나, 칸을 빠뜨리고 센다','같은 크기의 단위 각으로 빠짐없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X05','math',4,'u2',ARRAY['M4-1-u2-C3','M4-1-u2-C7']::text[],'1°·직각·일직선·한 바퀴의 관계를 헷갈린다 — 직각을 100°, 한 바퀴를 180°, 반 바퀴를 90°라고 한다','한 바퀴 360° · 반 바퀴 180° · 직각 90°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X06','math',4,'u2',ARRAY['M4-1-u2-C4','M4-1-u2-C6']::text[],'각도기의 다른 줄 눈금을 읽는다 — 한 변이 놓인 쪽의 0에서 시작하지 않아 180°에서 뺀 값(65° ↔ 115°)을 읽는다','밑금 위 변이 있는 쪽 0에서 시작') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X07','math',4,'u2',ARRAY['M4-1-u2-C4']::text[],'각도기를 잘못 놓는다 — 각도기 맨 아래 끝을 변에 대거나, 중심을 꼭짓점이 아닌 곳(변의 가운데·끝)에 맞춘다','중심은 꼭짓점, 밑금은 한 변') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X08','math',4,'u2',ARRAY['M4-1-u2-C4','M4-1-u2-C6']::text[],'큰 눈금 사이의 작은 눈금을 잘못 세어 5°나 10°만큼 어긋나게 읽는다','큰 눈금 10° · 한 칸 1°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X09','math',4,'u2',ARRAY['M4-1-u2-C5']::text[],'예각과 둔각을 거꾸로 안다 — 직각보다 작은 각을 둔각, 큰 각을 예각이라고 한다','예각은 직각보다 작게, 둔각은 크게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X10','math',4,'u2',ARRAY['M4-1-u2-C5']::text[],'경계의 각을 넣는다 — 90°를 예각이나 둔각에, 180°(일직선)를 둔각에 넣는다','90°는 직각, 180°는 일직선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X11','math',4,'u2',ARRAY['M4-1-u2-C6']::text[],'어림할 때 직각(90°)·45° 기준과 견주지 않는다 — 둔각을 90°보다 작게, 예각을 90°보다 크게 어림한다','먼저 직각보다 큰지 작은지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X12','math',4,'u2',ARRAY['M4-1-u2-C6']::text[],'어림한 값과 잰 값의 차이를 구하지 못하거나, 차이가 큰 쪽을 더 잘 어림했다고 한다','잰 값에 가까울수록 잘한 어림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X13','math',4,'u2',ARRAY['M4-1-u2-C7','M4-1-u2-C10']::text[],'각도의 합과 차를 바꾸어 계산하거나(붙인 각에서 빼기·덜어 낸 각에 더하기), 받아올림·받아내림에서 틀린다','이어 붙이면 합, 덜어 내면 차') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X14','math',4,'u2',ARRAY['M4-1-u2-C7','M4-1-u2-C8','M4-1-u2-C9']::text[],'일직선(180°)과 한 바퀴(360°)를 섞는다 — 직선 위의 나머지 각을 360°에서 빼거나 한 점 둘레의 나머지 각을 180°에서 뺀다','일직선 180° · 한 바퀴 360°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X15','math',4,'u2',ARRAY['M4-1-u2-C8']::text[],'삼각형의 세 각의 크기의 합이 삼각형의 모양이나 크기에 따라 달라진다고 하거나 360°라고 한다','어떤 삼각형이든 180°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X16','math',4,'u2',ARRAY['M4-1-u2-C9']::text[],'사각형의 네 각의 크기의 합을 180°라고 하거나, 직사각형만 360°라고 생각한다','삼각형 2개 — 180° + 180°') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X17','math',4,'u2',ARRAY['M4-1-u2-C8','M4-1-u2-C9']::text[],'나머지 한 각을 구할 때 아는 각을 빠짐없이 빼지 않는다 — 한 각만 빼거나 각의 합을 그대로 답한다','아는 각을 모두 빼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X18','math',4,'u2',ARRAY['M4-1-u2-C10']::text[],'삼각자의 각을 잘못 기억한다 — 45°·45°·90°와 30°·60°·90°를 섞거나 두 삼각자 모두에 같은 각이 있다고 한다','㉮ 45·45·90 · ㉯ 30·60·90') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X19','math',4,'u2',ARRAY['M4-1-u2-C1','M4-1-u2-C2','M4-1-u2-C3','M4-1-u2-C4','M4-1-u2-C5','M4-1-u2-C6','M4-1-u2-C7','M4-1-u2-C8','M4-1-u2-C9','M4-1-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 큰↔작은, 아닌↔맞는, 잘못↔바르게','물음에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u2-X20','math',4,'u2',ARRAY['M4-1-u2-C10']::text[],'삼각자 두 개로 만든 각은 모두 15°의 배수임을 놓친다 — 40°·50° 같은 각도 만들 수 있다고 한다','15°의 배수인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_basic#1','math',4,1,'u2','L02','g4_1_math_u2_L02_basic','lesson_basic','M4-1-u2-C2',1,'mc','auto','두 각 중 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X01']::text[],true,'{"seq":1,"concept":"M4-1-u2-C2","difficulty":1,"kind":"mc","stem":"두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉯가 더 많이 벌어졌어요.","더 큰 각은 ㉯예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,112.418141453],[166.0,112.418141453]],[[16.0,112.418141453],[130.906666468,16.0]]],"arc":[[[166.0,112.418141453],[16.0,112.418141453],[130.906666468,16.0]]],"w":182,"h":128},{"seg":[[[28.155372437,84.936542711],[98.155372437,84.936542711]],[[28.155372437,84.936542711],[16.0,16.0]]],"arc":[[[98.155372437,84.936542711],[28.155372437,84.936542711],[16.0,16.0]]],"w":114,"h":101}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉮가 더 많이 벌어졌어요.","더 큰 각은 ㉮예요."],"asset":{"type":"geo","items":[{"seg":[[[56.0,85.282032303],[136.0,85.282032303]],[[56.0,85.282032303],[16.0,16.0]]],"arc":[[[136.0,85.282032303],[56.0,85.282032303],[16.0,16.0]]],"w":152,"h":101},{"seg":[[[16.0,145.903810568],[166.0,145.903810568]],[[16.0,145.903810568],[91.0,16.0]]],"arc":[[[166.0,145.903810568],[16.0,145.903810568],[91.0,16.0]]],"w":182,"h":162}]}},{"stem":"이번에는 다른 각이에요. 두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"