INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_basic#2','math',4,1,'u2','L02','g4_1_math_u2_L02_basic','lesson_basic','M4-1-u2-C3',1,'sa','auto','직각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u2-C3","difficulty":1,"kind":"sa","stem":"직각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["한 바퀴 360°를 똑같이 넷으로 나눈 각이에요.","360 ÷ 4 = 90.","답은 90°예요."],"variant_rule":{"alt":[{"stem":"한 바퀴를 돈 각은 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["1°는 한 바퀴를 360칸으로 나눈 한 칸이에요.","360칸이면 한 바퀴 — 360°.","답은 360°예요."],"asset":null},{"stem":"한 바퀴의 반만큼 돈 각(일직선)은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 바퀴 360°의 반이에요.","360 ÷ 2 = 180.","답은 180°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_basic#3','math',4,1,'u2','L02','g4_1_math_u2_L02_basic','lesson_basic','M4-1-u2-C2',1,'sa','auto','똑같은 작은 각(단위 각)으로 각을 나누었어요. 이 각에는 단위 각이 몇 개 들어가나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u2-C2","difficulty":1,"kind":"sa","stem":"똑같은 작은 각(단위 각)으로 각을 나누었어요. 이 각에는 단위 각이 몇 개 들어가나요? 숫자로 쓰세요.","answer":["4"],"explanation":["꼭짓점에서 뻗은 선 사이 칸을 하나씩 세어요.","칸을 빠짐없이 세면 4칸이에요.","단위 각이 4개 들어가요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,119.923048454],[136.0,119.923048454]],[[16.0,119.923048454],[76.0,16.0]],[[16.0,119.923048454],[87.864881476,100.666911499]],[[16.0,119.923048454],[80.432290042,82.723048454]],[[16.0,119.923048454],[68.60874452,67.314303934]]],"w":152,"h":136}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 똑같은 작은 각(단위 각)으로 각을 나누었어요. 이 각에는 단위 각이 몇 개 들어가나요? 숫자로 쓰세요.","answer":["5"],"explanation":["꼭짓점에서 뻗은 선 사이 칸을 하나씩 세어요.","칸을 빠짐없이 세면 5칸이에요.","단위 각이 5개 들어가요."],"asset":{"type":"geo","items":[{"seg":[[[36.83778132,134.176930361],[156.83778132,134.176930361]],[[36.83778132,134.176930361],[16.0,16.0]],[[36.83778132,134.176930361],[106.750912307,108.730631698]],[[36.83778132,134.176930361],[93.831487888,86.353532201]],[[36.83778132,134.176930361],[74.03778132,69.74464032]],[[36.83778132,134.176930361],[49.757205738,60.907233537]]],"w":173,"h":150}],"tag":false}},{"stem":"이번에는 다른 각이에요. 똑같은 작은 각(단위 각)으로 각을 나누었어요. 이 각에는 단위 각이 몇 개 들어가나요? 숫자로 쓰세요.","answer":["5"],"explanation":["꼭짓점에서 뻗은 선 사이 칸을 하나씩 세어요.","칸을 빠짐없이 세면 5칸이에요.","단위 각이 5개 들어가요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,136.0],[136.0,136.0]],[[16.0,136.0],[16.0,16.0]],[[16.0,136.0],[86.758604812,113.009135619]],[[16.0,136.0],[76.190864381,92.268777229]],[[16.0,136.0],[59.731222771,75.809135619]],[[16.0,136.0],[38.990864381,65.241395188]]],"w":152,"h":152}],"tag":false