INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_basic#4','math',4,1,'u2','L02','g4_1_math_u2_L02_basic','lesson_basic','M4-1-u2-C1',1,'mc','auto','축제장에서 천막 지붕의 각은 120°, 부채의 각은 75°였어요. 어느 각이 더 많이 벌어졌나요?',ARRAY['M4-1-u2-X19','M4-1-u2-X05','M4-1-u2-X01']::text[],true,'{"seq":4,"concept":"M4-1-u2-C1","difficulty":1,"kind":"mc","stem":"축제장에서 천막 지붕의 각은 120°, 부채의 각은 75°였어요. 어느 각이 더 많이 벌어졌나요?","options":[{"t":"천막 지붕","correct":true},{"t":"부채","mis":"M4-1-u2-X19"},{"t":"둘 다 같아요","mis":"M4-1-u2-X05"},{"t":"물건이 큰 쪽","mis":"M4-1-u2-X01"}],"explanation":["각도가 클수록 더 많이 벌어진 각이에요.","120°와 75°를 견주어요.","천막 지붕의 각이 더 많이 벌어졌어요."],"variant_rule":{"alt":[{"stem":"축제장에서 펼친 부채의 각은 140°, 벌린 가위의 각은 40°였어요. 어느 각이 더 많이 벌어졌나요?","options":[{"t":"펼친 부채","correct":true},{"t":"벌린 가위","mis":"M4-1-u2-X19"},{"t":"둘 다 같아요","mis":"M4-1-u2-X05"},{"t":"물건이 큰 쪽","mis":"M4-1-u2-X01"}],"explanation":["각도가 클수록 더 많이 벌어진 각이에요.","140°와 40°를 견주어요.","펼친 부채의 각이 더 많이 벌어졌어요."],"asset":null},{"stem":"축제장에서 시곗바늘의 각은 30°, 천막 지붕의 각은 100°였어요. 어느 각이 더 많이 벌어졌나요?","options":[{"t":"천막 지붕","correct":true},{"t":"시곗바늘","mis":"M4-1-u2-X19"},{"t":"둘 다 같아요","mis":"M4-1-u2-X05"},{"t":"물건이 큰 쪽","mis":"M4-1-u2-X01"}],"explanation":["각도가 클수록 더 많이 벌어진 각이에요.","30°와 100°를 견주어요.","천막 지붕의 각이 더 많이 벌어졌어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
