INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_basic#6','math',4,1,'u2','L02','g4_1_math_u2_L02_basic','lesson_basic','M4-1-u2-C2',2,'mc','auto','두 각을 겹쳐서 크기를 견주려고 해요. 무엇을 맞춰야 하나요?',ARRAY['M4-1-u2-X03','M4-1-u2-X02']::text[],true,'{"seq":6,"concept":"M4-1-u2-C2","difficulty":2,"kind":"mc","stem":"두 각을 겹쳐서 크기를 견주려고 해요. 무엇을 맞춰야 하나요?","options":[{"t":"꼭짓점과 한 변을 맞춰요","correct":true},{"t":"아무렇게나 포개어 봐요","mis":"M4-1-u2-X03"},{"t":"두 변의 끝을 맞춰요","mis":"M4-1-u2-X03"},{"t":"두 각을 같은 방향으로 세워 놓기만 해요","mis":"M4-1-u2-X02"}],"explanation":["두 각의 꼭짓점을 맞추고 한 변을 겹쳐요.","그러면 나머지 한 변이 더 바깥에 있는 각이 커요.","꼭짓점과 한 변을 맞춰요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 각을 겹쳐서 크기를 견주려고 해요. 무엇을 맞춰야 하나요?","options":[{"t":"꼭짓점과 한 변을 맞춰요","correct":true},{"t":"변의 길이를 똑같이 맞춰요","mis":"M4-1-u2-X01"},{"t":"두 각을 같은 방향으로 세워 놓기만 해요","mis":"M4-1-u2-X02"},{"t":"아무렇게나 포개어 봐요","mis":"M4-1-u2-X03"}],"explanation":["두 각의 꼭짓점을 맞추고 한 변을 겹쳐요.","그러면 나머지 한 변이 더 바깥에 있는 각이 커요.","꼭짓점과 한 변을 맞춰요."],"asset":null},{"stem":"이번에는 다른 각이에요. 두 각을 겹쳐서 크기를 견주려고 해요. 무엇을 맞춰야 하나요?","options":[{"t":"꼭짓점과 한 변을 맞춰요","correct":true},{"t":"아무렇게나 포개어 봐요","mis":"M4-1-u2-X03"},{"t":"두 변의 끝을 맞춰요","mis":"M4-1-u2-X03"},{"t":"두 각을 같은 방향으로 세워 놓기만 해요","mis":"M4-1-u2-X02"}],"explanation":["두 각의 꼭짓점을 맞추고 한 변을 겹쳐요.","그러면 나머지 한 변이 더 바깥에 있는 각이 커요.","꼭짓점과 한 변을 맞춰요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
