INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_basic#8','math',4,1,'u2','L02','g4_1_math_u2_L02_basic','lesson_basic','M4-1-u2-C3',2,'sa','auto','직각 2개를 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u2-C3","difficulty":2,"kind":"sa","stem":"직각 2개를 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["직각은 90°예요.","90 + 90 = 180 — 일직선이에요.","답은 180°예요."],"variant_rule":{"alt":[{"stem":"직각 4개를 한 점에 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["직각은 90°예요.","90 × 4 = 360 — 한 바퀴예요.","답은 360°예요."],"asset":null},{"stem":"1°짜리 각이 몇 개 모이면 직각이 되나요? 숫자로 쓰세요.","answer":["90"],"explanation":["직각은 90°예요.","1°가 90개면 90°.","답은 90°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_basic#9','math',4,1,'u2','L02','g4_1_math_u2_L02_basic','lesson_basic','M4-1-u2-C2',2,'mc','auto','같은 크기의 단위 각으로 재었더니 ㉮에는 3칸, ㉯에는 5칸 들어갔어요. 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X19','M4-1-u2-X04']::text[],true,'{"seq":9,"concept":"M4-1-u2-C2","difficulty":2,"kind":"mc","stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 3칸, ㉯에는 5칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","3칸과 5칸 — ㉯에 더 많이 들어갔어요.","더 큰 각은 ㉯예요."],"variant_rule":{"alt":[{"stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 7칸, ㉯에는 4칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","7칸과 4칸 — ㉮에 더 많이 들어갔어요.","더 큰 각은 ㉮예요."],"asset":null},{"stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 6칸, ㉯에는 8칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","6칸과 8칸 — ㉯에 더 많이 들어갔어요.","더 큰 각은 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_basic#10','math',4,1,'u2','L02','g4_1_math_u2_L02_basic','lesson_basic','M4-1-u2-C1',3,'error','auto','㉮는 40°, ㉯는 100°인 각이에요. ㉮의 변이 더 길게 그려져 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X01','M4-1-u2-X19']::text[],true,'{"seq":10,"concept":"M4-1-u2-C1","difficulty":3,"kind":"error","stem":"㉮는 40°, ㉯는 100°인 각이에요. ㉮의 변이 더 길게 그려져 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「변이 더 긴 ㉮가 더 큰 각이에요.」","correct":true,"mis_target":"M4-1-u2-X01"},{"t":"준서 — 「㉯가 더 많이 벌어졌으니 더 큰 각이에요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「변을 늘여도 각의 크기는 그대로예요.」","mis":"M4-1-u2-X19"}],"explanation":["각의 크기는 벌어진 정도예요.","40° < 100° — ㉯가 더 커요.","도윤이 잘못 말했어요 — 변의 길이 말고 벌어진 정도."],"asset":{"type":"geo","items":[{"seg":[[[16.0,112.418141453],[166.0,112.418141453]],[[16.0,112.418141453],[130.906666468,16.0]]],"arc":[[[166.0,112.418141453],[16.0,112.418141453],[130.906666468,16.0]]],"w":182,"h":128},{"seg":[[[28.155372437,84.936542711],[98.155372437,84.936542711]],[[28.155372437,84.936542711],[16.0,16.0]]],"arc":[[[98.155372437,84.936542711],[28.155372437,84.936542711],[16.0,16.0]]],"w":114,"h":101}]},"variant_rule":{"alt":[{"stem":"㉮는 30°, ㉯는 75°인 각이에요. ㉮의 변이 더 길게 그려져 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「변이 더 긴 ㉮가 더 큰 각이에요.」","correct":true,"mis_target":"M4-1-u2-X01"},{"t":"도윤 — 「㉯가 더 많이 벌어졌으니 더 큰 각이에요.」","mis":"M4-1-u2-X19"},{"t":"하람 — 「변을 늘여도 각의 크기는 그대로예요.」","mis":"M4-1-u2-X19"}],"explanation":["각의 크기는 벌어진 정도예요.","30° < 75° — ㉯가 더 커요.","예린이 잘못 말했어요 — 변의 길이 말고 벌어진 정도."],"asset":{"type":"geo","items":[{"seg":[[[16.0,91.0],[166.0,91.0]],[[16.0,91.0],[145.903810568,16.0]]],"arc":[[[166.0,91.0],[16.0,91.0],[145.903810568,16.0]]],"w":182,"h":107},{"seg":[[[16.0,83.61480784],[86.0,83.61480784]],[[16.0,83.61480784],[34.117333157,16.0]]],"arc":[[[86.0,83.61480784],[16.0,83.61480784],[34.117333157,16.0]]],"w