INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_challenge#1','math',4,1,'u2','L02','g4_1_math_u2_L02_challenge','lesson_challenge','M4-1-u2-C3',2,'match','auto','각과 그 크기를 알맞게 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C3","difficulty":2,"kind":"match","stem":"각과 그 크기를 알맞게 이으세요.","pairs":[{"l":"직각","r":"90°"},{"l":"일직선","r":"180°"},{"l":"한 바퀴","r":"360°"}],"mis":"M4-1-u2-X05","explanation":["한 바퀴 360° · 반 바퀴 180° · 직각 90°.","직각 → 90°, 일직선 → 180°, 한 바퀴 → 360°.","360 ÷ 2 = 180, 360 ÷ 4 = 90."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각과 그 크기를 알맞게 이으세요.","pairs":[{"l":"직각 2개","r":"180°"},{"l":"직각 4개","r":"360°"},{"l":"직각 1개","r":"90°"}],"explanation":["한 바퀴 360° · 반 바퀴 180° · 직각 90°.","직각 2개 → 180°, 직각 4개 → 360°, 직각 1개 → 90°.","360 ÷ 2 = 180, 360 ÷ 4 = 90."],"asset":null},{"stem":"이번에는 다른 각이에요. 각과 그 크기를 알맞게 이으세요.","pairs":[{"l":"한 바퀴의 반","r":"180°"},{"l":"직각의 반","r":"45°"},{"l":"한 바퀴","r":"360°"}],"explanation":["한 바퀴 360° · 반 바퀴 180° · 직각 90°.","한 바퀴의 반 → 180°, 직각의 반 → 45°, 한 바퀴 → 360°.","360 ÷ 2 = 180, 360 ÷ 4 = 90."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
