INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_challenge#3','math',4,1,'u2','L02','g4_1_math_u2_L02_challenge','lesson_challenge','M4-1-u2-C2',3,'mc','auto','㉮는 작은 단위 각으로 10칸, ㉯는 그보다 2배 큰 단위 각으로 4칸이에요. 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X04']::text[],true,'{"seq":3,"concept":"M4-1-u2-C2","difficulty":3,"kind":"mc","stem":"㉮는 작은 단위 각으로 10칸, ㉯는 그보다 2배 큰 단위 각으로 4칸이에요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u2-X04"},{"t":"칸 수가 다르니 견줄 수 없어요","mis":"M4-1-u2-X04"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 다르면 칸 수만으로 견줄 수 없어요 — 같은 단위로 바꿔요.","㉯의 큰 단위 각 하나는 작은 단위 각 2칸 — 4칸 × 2 = 8칸.","작은 단위 각으로 ㉮ 10칸, ㉯ 8칸 — ㉮예요."],"variant_rule":{"alt":[{"stem":"㉮는 작은 단위 각으로 9칸, ㉯는 그보다 2배 큰 단위 각으로 5칸이에요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"칸 수가 다르니 견줄 수 없어요","mis":"M4-1-u2-X04"},{"t":"㉮","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 다르면 칸 수만으로 견줄 수 없어요 — 같은 단위로 바꿔요.","㉯의 큰 단위 각 하나는 작은 단위 각 2칸 — 5칸 × 2 = 10칸.","작은 단위 각으로 ㉮ 9칸, ㉯ 10칸 — ㉯예요."],"asset":null},{"stem":"㉮는 작은 단위 각으로 12칸, ㉯는 그보다 2배 큰 단위 각으로 7칸이에요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"칸 수가 다르니 견줄 수 없어요","mis":"M4-1-u2-X04"},{"t":"㉮","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 다르면 칸 수만으로 견줄 수 없어요 — 같은 단위로 바꿔요.","㉯의 큰 단위 각 하나는 작은 단위 각 2칸 — 7칸 × 2 = 14칸.","작은 단위 각으로 ㉮ 12칸, ㉯ 14칸 — ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
