INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_challenge#5','math',4,1,'u2','L02','g4_1_math_u2_L02_challenge','lesson_challenge','M4-1-u2-C3',3,'ox','auto','직각은 1°짜리 각 100개가 모인 각이에요.',ARRAY['M4-1-u2-X05']::text[],true,'{"seq":5,"concept":"M4-1-u2-C3","difficulty":3,"kind":"ox","stem":"직각은 1°짜리 각 100개가 모인 각이에요.","answer":"X","reason_options":[{"t":"직각은 90°라서 1°가 90개라서","correct":true},{"t":"직각은 100칸으로 나누어서","mis":"M4-1-u2-X05"}],"mis":"M4-1-u2-X05","explanation":["1°는 한 바퀴를 360으로 나눈 한 칸이에요.","직각은 90°예요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"한 바퀴의 반만큼 돈 각은 180°예요.","answer":"O","reason_options":[{"t":"360°의 반이 180°라서","correct":true},{"t":"한 바퀴의 반은 90°라서","mis":"M4-1-u2-X05"}],"explanation":["한 바퀴는 360°예요.","360 ÷ 2 = 180.","그래서 맞아요."],"asset":null},{"stem":"한 바퀴는 직각 4개를 모은 것과 같아요.","answer":"O","reason_options":[{"t":"90° × 4 = 360°라서","correct":true},{"t":"직각 2개가 한 바퀴라서","mis":"M4-1-u2-X05"}],"explanation":["직각은 90°예요.","90 × 4 = 360.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_challenge#6','math',4,1,'u2','L02','g4_1_math_u2_L02_challenge','lesson_challenge','M4-1-u2-C2',3,'mc','auto','두 각 가와 나를 꼭짓점과 한 변을 맞추어 겹쳤어요. 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X01','M4-1-u2-X03']::text[],true,'{"seq":6,"concept":"M4-1-u2-C2","difficulty":3,"kind":"mc","stem":"두 각 가와 나를 꼭짓점과 한 변을 맞추어 겹쳤어요. 더 큰 각은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X03"},{"t":"변이 더 긴 각이 커요","mis":"M4-1-u2-X01"}],"explanation":["꼭짓점과 한 변을 맞추면 나머지 변의 자리만 보면 돼요.","나의 변이 바깥쪽(더 벌어진 쪽)에 있어요.","더 큰 각은 나예요."],"asset":{"type":"geo","items":[{"seg":[[[37.761443188,161.48247894],[167.761443188,161.48247894]],[[37.761443188,161.48247894],[48.220132317,41.939115169]],[[37.761443188,161.48247894],[29.394491884,65.847787924]]],"lab":[[[49.614624201,26.0],"가"],[[28.0,49.908672754],"나"]],"w":184,"h":177}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 각 가와 나를 꼭짓점과 한 변을 맞추어 겹쳤어요. 더 큰 각은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X03"},{"t":"변이 더 긴 각이 커요","mis":"M4-1-u2-X01"}],"explanation":["꼭짓점과 한 변을 맞추면 나머지 변의 자리만 보면 돼요.","가의 변이 바깥쪽(더 벌어진 쪽)에 있어요.","더 큰 각은 가예요."],"asset":{"type":"geo","items":[{"seg":[[[51.616152163,159.93385441],[181.616152163,159.93385441]],[[51.616152163,159.93385441],[30.778370843,41.756924048]],[[51.616152163,159.93385441],[48.265800479,63.992335016]]],"lab":[[[28.0,26.0],"가"],[[47.707408532,48.002081784],"나"]],"w":198,"h":176}],"tag":false}},{"stem":"이번에는 다른 각이에요. 두 각 가와 나를 꼭짓점과 한 변을 맞추어 겹쳤어요. 더 큰 각은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X03"},{"t":"변이 더 긴 각이 커요","mis":"M4-1-u2-X01"}],"explanation":["꼭짓점과 한 변을 맞추면 나머지 변의 자리만 보면 돼요.","나의 변이 바깥쪽(더 벌어진 쪽)에 있어요.","더 큰 각은 나예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,143.779454915],[146.0,143.779454915]],[[16.0,143.779454915],[76.0,39.856406461]],[[16.0,143.779454915],[45.66563146,52.47802935]]],"lab":[[[84.0,26.0],"가"],[[50.60990337,37.26112509],"나"]],"w":162,"h":160}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_challenge#7','math',4,1,'u2','L02','g4_1_math_u2_L02_challenge','lesson_challenge','M4-1-u2-C1',3,'error','auto','㉮는 25°, ㉯는 60°인 각이에요. ㉮의 변이 더 길게 그려져 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X01','M4-1-u2-X19']::text[],true,'{"seq":7,"concept":"M4-1-u2-C1","difficulty":3,"kind":"error","stem":"㉮는 25°, ㉯는 60°인 각이에요. ㉮의 변이 더 길게 그려져 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「변이 더 긴 ㉮가 더 큰 각이에요.」","correct":true,"mis_target":"M4-1-u2-X01"},{"t":"준서 — 「㉯가 더 많이 벌어졌으니 더 큰 각이에요.」","mis":"M4-1-u2-X19"},{"t":"예린 — 「변을 늘여도 각의 크기는 그대로예요.」","mis":"M4-1-u2-X19"}],"explanation":["각의 크기는 벌어진 정도예요.","25° < 60° — ㉯가 더 커요.","지호가 잘못 말했어요 — 변의 길이 말고 벌어진 정도."],"asset":{"type":"geo","items":[{"seg":[[[16.0,79.392739261],[166.0,79.392739261]],[[16.0,79.392739261],[151.946168055,16.0]]],"arc":[[[166.0,79.392739261],[16.0,79.392739261],[151.946168055,16.0]]],"w":182,"h":95},{"seg":[[[16.0,76.621778265],[86.0,76.621778265]],[[16.0,76.621778265],[51.0,16.0]]],"arc":[[[86.0,76.621778265],[16.0,76.621778265],[51.0,16.0]]],"w":102,"h":93}]},"variant_rule":{"alt":[{"stem":"㉮는 80°, ㉯는 130°인 각이에요. ㉮의 변이 더 길게 그려져 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「변이 더 긴 ㉮가 더 큰 각이에요.」","correct":true,"mis_target":"M4-1-u2-X01"},{"t":"도윤 — 「㉯가 더 많이 벌어졌으니 더 큰 각이에요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「변을 늘여도 각의 크기는 그대로예요.」","mis":"M4-1-u2-X19"}],"explanation":["각의 크기는 벌어진 정도예요.","80° < 130° — ㉯가 더 커요.","준서가 잘못 말했어요 — 변의 길이 말고 벌어진 정도."],"asset":{"type":"geo","items":[{"seg":[[[16.0,163.721162952],[166.0,163.721162952]],[[16.0,163.721162952],[42.04722665,16.0]]],"arc":[[[166.0,163.721162952],[16.0,163.721162952],[42.04722665,16.0]]],"w":182,"h":180},{"seg":[[[60.995132678,69.623111018],[130.995132678,69.623111018]],[[60.995132678,69.623111018],[16.0,16.0]]],"arc":[[[130.995132678,69.623111018],[60.995132