INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_challenge#8','math',4,1,'u2','L02','g4_1_math_u2_L02_challenge','lesson_challenge','M4-1-u2-C1',4,'essay','teacher','축제장에서 부채를 펼친 각을 그린 뒤, 두 변을 두 배로 길게 늘여 다시 그렸어요. 각의 크기는 어떻게 되는지 쓰고 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u2-C1","difficulty":4,"kind":"essay","stem":"축제장에서 부채를 펼친 각을 그린 뒤, 두 변을 두 배로 길게 늘여 다시 그렸어요. 각의 크기는 어떻게 되는지 쓰고 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 각의 크기는 그대로이다. 각의 크기는 두 변이 벌어진 정도인데, 변을 늘여도 벌어진 정도는 바뀌지 않기 때문이다.","scoring_points":["각의 크기가 그대로라고 답했는가","각의 크기는 벌어진 정도라고 설명했는가","변의 길이와 상관없다고 했는가"]},"explanation":["변을 늘여도 꼭짓점과 방향은 같아요.","벌어진 정도가 그대로예요.","각의 크기는 변하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L02_challenge#9','math',4,1,'u2','L02','g4_1_math_u2_L02_challenge','lesson_challenge','M4-1-u2-C2',4,'essay','teacher','㉮는 작은 단위 각 6칸, ㉯는 그 단위 각보다 2배 큰 단위 각 4칸이에요. 칸이 더 많은 ㉮가 크다고 말해도 되는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u2-C2","difficulty":4,"kind":"essay","stem":"㉮는 작은 단위 각 6칸, ㉯는 그 단위 각보다 2배 큰 단위 각 4칸이에요. 칸이 더 많은 ㉮가 크다고 말해도 되는지 설명해 보세요.","answer_guide":{"answer":"예: 안 된다. 단위 각의 크기가 다르기 때문이다. ㉯의 큰 단위 각 하나는 작은 단위 각 2칸이므로 ㉯는 작은 단위 각 8칸이고, 6칸인 ㉮보다 크다.","scoring_points":["안 된다고 답했는가","단위 각의 크기가 달라서라고 했는가","같은 단위로 바꾸어 ㉯가 크다고 했는가"]},"explanation":["단위가 다르면 칸 수만으로 견줄 수 없어요.","㉯ = 4 × 2 = 8칸.","6칸 < 8칸 — ㉯가 커요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
