INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_basic#1','math',4,1,'u2','L03','g4_1_math_u2_L03_basic','lesson_basic','M4-1-u2-C4',1,'sa','auto','각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C4","difficulty":1,"kind":"sa","stem":"각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["밑금 위의 변이 오른쪽에 있으니 오른쪽 0에서 시작하는 안쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 60°.","각의 크기는 60°예요 (다른 줄 120°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":60,"from":"right"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["밑금 위의 변이 오른쪽에 있으니 오른쪽 0에서 시작하는 안쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 40°.","각의 크기는 40°예요 (다른 줄 140°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":40,"from":"right"}},{"stem":"이번에는 다른 각이에요. 각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["밑금 위의 변이 오른쪽에 있으니 오른쪽 0에서 시작하는 안쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 70°.","각의 크기는 70°예요 (다른 줄 110°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":70,"from":"right"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
