INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_basic#3','math',4,1,'u2','L03','g4_1_math_u2_L03_basic','lesson_basic','M4-1-u2-C4',1,'mc','auto','각도기의 중심은 각의 어디에 맞추나요?',ARRAY['M4-1-u2-X07']::text[],true,'{"seq":3,"concept":"M4-1-u2-C4","difficulty":1,"kind":"mc","stem":"각도기의 중심은 각의 어디에 맞추나요?","options":[{"t":"꼭짓점","correct":true},{"t":"변의 끝","mis":"M4-1-u2-X07"},{"t":"변의 가운데","mis":"M4-1-u2-X07"},{"t":"각도기 맨 아래 끝","mis":"M4-1-u2-X07"}],"explanation":["그림에서 각도기의 중심과 밑금을 찾아요.","중심 → 꼭짓점, 밑금 → 한 변, 그 변 쪽 0에서 시작.","답은 「꼭짓점」이에요."],"asset":{"type":"prot","deg":null,"from":"right","parts":true},"variant_rule":{"alt":[{"stem":"각도기의 밑금은 무엇에 맞추나요?","options":[{"t":"각의 한 변","correct":true},{"t":"각의 꼭짓점","mis":"M4-1-u2-X07"},{"t":"각도기 맨 아래 끝","mis":"M4-1-u2-X07"},{"t":"가장 큰 눈금","mis":"M4-1-u2-X06"}],"explanation":["그림에서 각도기의 중심과 밑금을 찾아요.","중심 → 꼭짓점, 밑금 → 한 변, 그 변 쪽 0에서 시작.","답은 「각의 한 변」이에요."],"asset":{"type":"prot","deg":null,"from":"right","parts":true}},{"stem":"밑금 위의 변이 왼쪽에 있으면 어느 눈금을 읽어야 하나요?","options":[{"t":"왼쪽이 0인 바깥쪽 눈금","correct":true},{"t":"오른쪽이 0인 안쪽 눈금","mis":"M4-1-u2-X06"},{"t":"더 큰 수가 적힌 눈금","mis":"M4-1-u2-X06"},{"t":"아무 눈금이나 같아요","mis":"M4-1-u2-X06"}],"explanation":["그림에서 각도기의 중심과 밑금을 찾아요.","중심 → 꼭짓점, 밑금 → 한 변, 그 변 쪽 0에서 시작.","답은 「왼쪽이 0인 바깥쪽 눈금」이에요."],"asset":{"type":"prot","deg":null,"from":"right","parts":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_basic#4','math',4,1,'u2','L03','g4_1_math_u2_L03_basic','lesson_basic','M4-1-u2-C4',1,'mc','auto','각도기를 바르게 놓는 방법은 어느 것인가요?',ARRAY['M4-1-u2-X06','M4-1-u2-X07']::text[],true,'{"seq":4,"concept":"M4-1-u2-C4","difficulty":1,"kind":"mc","stem":"각도기를 바르게 놓는 방법은 어느 것인가요?","options":[{"t":"각도기의 중심을 각의 꼭짓점에, 밑금을 각의 한 변에 맞춰요","correct":true},{"t":"눈금이 가장 큰 쪽부터 읽어요","mis":"M4-1-u2-X06"},{"t":"각도기의 맨 아래 끝을 각의 한 변에 맞춰요","mis":"M4-1-u2-X07"},{"t":"각도기의 중심을 변의 끝에 맞춰요","mis":"M4-1-u2-X07"}],"explanation":["각도기 가운데 아래의 점이 중심, 중심을 지나는 곧은 선이 밑금이에요.","중심을 꼭짓점에, 밑금을 한 변에 맞춰야 해요.","맨 아래 끝(모서리)에 맞추면 안 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각도기를 바르게 놓는 방법은 어느 것인가요?","options":[{"t":"각도기의 중심을 각의 꼭짓점에, 밑금을 각의 한 변에 맞춰요","correct":true},{"t":"각도기의 중심을 변의 가운데에 맞춰요","mis":"M4-1-u2-X07"},{"t":"각도기의 중심을 변의 끝에 맞춰요","mis":"M4-1-u2-X07"},{"t":"눈금이 가장 큰 쪽부터 읽어요","mis":"M4-1-u2-X06"}],"explanation":["각도기 가운데 아래의 점이 중심, 중심을 지나는 곧은 선이 밑금이에요.","중심을 꼭짓점에, 밑금을 한 변에 맞춰야 해요.","맨 아래 끝(모서리)에 맞추면 안 돼요."],"asset":null},{"stem":"이번에는 다른 각이에요. 각도기를 바르게 놓는 방법은 어느 것인가요?","options":[{"t":"각도기의 중심을 각의 꼭짓점에, 밑금을 각의 한 변에 맞춰요","correct":true},{"t":"눈금이 가장 큰 쪽부터 읽어요","mis":"M4-1-u2-X06"},{"t":"각도기의 맨 아래 끝을 각의 한 변에 맞춰요","mis":"M4-1-u2-X07"},{"t":"각도기의 중심을 변의 끝에 맞춰요","mis":"M4-1-u2-X07"}],"explanation":["각도기 가운데 아래의 점이 중심, 중심을 지나는 곧은 선이 밑금이에요.","중심을 꼭짓점에, 밑금을 한 변에 맞춰야 해요.","맨 아래 끝(모서리)에 맞추면 안 돼요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
