INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_basic#6','math',4,1,'u2','L03','g4_1_math_u2_L03_basic','lesson_basic','M4-1-u2-C4',2,'mc','auto','각도기로 잰 각의 크기는 몇 도인가요?',ARRAY['M4-1-u2-X06','M4-1-u2-X08']::text[],true,'{"seq":6,"concept":"M4-1-u2-C4","difficulty":2,"kind":"mc","stem":"각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"65°","correct":true},{"t":"115°","mis":"M4-1-u2-X06"},{"t":"75°","mis":"M4-1-u2-X08"},{"t":"55°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 오른쪽에 있어요 — 오른쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 65°.","115°는 다른 줄을 읽은 값이에요. 답은 65°예요."],"asset":{"type":"prot","deg":65,"from":"right"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"115°","correct":true},{"t":"65°","mis":"M4-1-u2-X06"},{"t":"125°","mis":"M4-1-u2-X08"},{"t":"105°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 왼쪽에 있어요 — 왼쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 115°.","65°는 다른 줄을 읽은 값이에요. 답은 115°예요."],"asset":{"type":"prot","deg":115,"from":"left"}},{"stem":"이번에는 다른 각이에요. 각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"35°","correct":true},{"t":"145°","mis":"M4-1-u2-X06"},{"t":"45°","mis":"M4-1-u2-X08"},{"t":"25°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 오른쪽에 있어요 — 오른쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 35°.","145°는 다른 줄을 읽은 값이에요. 답은 35°예요."],"asset":{"type":"prot","deg":35,"from":"right"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_basic#7','math',4,1,'u2','L03','g4_1_math_u2_L03_basic','lesson_basic','M4-1-u2-C4',2,'ox','auto','각의 변이 짧아 눈금에 닿지 않으면 각의 크기를 잴 수 없어요.',ARRAY['M4-1-u2-X01']::text[],true,'{"seq":7,"concept":"M4-1-u2-C4","difficulty":2,"kind":"ox","stem":"각의 변이 짧아 눈금에 닿지 않으면 각의 크기를 잴 수 없어요.","answer":"X","reason_options":[{"t":"변을 늘여 그어도 각의 크기는 그대로라 늘여서 재면 돼서","correct":true},{"t":"변이 짧으면 각도 작아서","mis":"M4-1-u2-X01"}],"mis":"M4-1-u2-X01","explanation":["변을 길게 늘여 그어요.","늘여도 벌어진 정도는 같아요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"각도기로 잴 때는 밑금 위 변 쪽의 0에서부터 눈금을 읽어요.","answer":"O","reason_options":[{"t":"0에서 시작해야 벌어진 만큼을 셀 수 있어서","correct":true},{"t":"더 큰 수가 적힌 줄을 읽어야 해서","mis":"M4-1-u2-X06"}],"explanation":["시작하는 0이 어느 쪽인지 먼저 찾아요.","그 0에서 다른 변까지 읽어요.","그래서 맞아요."],"asset":null},{"stem":"각도기의 맨 아래 끝을 각의 한 변에 맞추어 재요.","answer":"X","reason_options":[{"t":"맞추는 것은 맨 아래 끝이 아니라 밑금이라서","correct":true},{"t":"맨 아래 끝이 가장 반듯해서","mis":"M4-1-u2-X07"}],"explanation":["밑금은 중심을 지나는 선이에요.","맨 아래 끝에 맞추면 꼭짓점이 중심에서 벗어나요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_basic#8','math',4,1,'u2','L03','g4_1_math_u2_L03_basic','lesson_basic','M4-1-u2-C4',2,'sa','auto','각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u2-C4","difficulty":2,"kind":"sa","stem":"각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["밑금 위의 변이 왼쪽에 있으니 왼쪽 0에서 시작하는 바깥쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 105°.","각의 크기는 105°예요 (다른 줄 75°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":105,"from":"left"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["145"],"explanation":["밑금 위의 변이 왼쪽에 있으니 왼쪽 0에서 시작하는 바깥쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 145°.","각의 크기는 145°예요 (다른 줄 35°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":145,"from":"left"}},{"stem":"이번에는 다른 각이에요. 각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["밑금 위의 변이 오른쪽에 있으니 오른쪽 0에서 시작하는 안쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 95°.","각의 크기는 95°예요 (다른 줄 85°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":95,"from":"right"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
