INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_challenge#3','math',4,1,'u2','L03','g4_1_math_u2_L03_challenge','lesson_challenge','M4-1-u2-C4',3,'error','auto','같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X06','M4-1-u2-X19']::text[],true,'{"seq":3,"concept":"M4-1-u2-C4","difficulty":3,"kind":"error","stem":"같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「이 각은 155°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"준서 — 「이 각은 25°예요」","mis":"M4-1-u2-X19"},{"t":"예린 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 오른쪽에 있어요.","그쪽 0에서 시작하는 눈금은 25°.","지호는 다른 줄 눈금(155°)을 읽었어요."],"asset":{"type":"prot","deg":25,"from":"right"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「이 각은 25°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"도윤 — 「이 각은 155°예요」","mis":"M4-1-u2-X19"},{"t":"지호 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 왼쪽에 있어요.","그쪽 0에서 시작하는 눈금은 155°.","준서는 다른 줄 눈금(25°)을 읽었어요."],"asset":{"type":"prot","deg":155,"from":"left"}},{"stem":"이번에는 다른 각이에요. 같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「이 각은 110°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"나래 — 「이 각은 70°예요」","mis":"M4-1-u2-X19"},{"t":"준서 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 오른쪽에 있어요.","그쪽 0에서 시작하는 눈금은 70°.","예린은 다른 줄 눈금(110°)을 읽었어요."],"asset":{"type":"prot","deg":70,"from":"right"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
