INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_challenge#5','math',4,1,'u2','L03','g4_1_math_u2_L03_challenge','lesson_challenge','M4-1-u2-C4',3,'mc','auto','밑금 위의 변이 왼쪽에 있으면 어느 눈금을 읽어야 하나요?',ARRAY['M4-1-u2-X06']::text[],true,'{"seq":5,"concept":"M4-1-u2-C4","difficulty":3,"kind":"mc","stem":"밑금 위의 변이 왼쪽에 있으면 어느 눈금을 읽어야 하나요?","options":[{"t":"왼쪽이 0인 바깥쪽 눈금","correct":true},{"t":"오른쪽이 0인 안쪽 눈금","mis":"M4-1-u2-X06"},{"t":"더 큰 수가 적힌 눈금","mis":"M4-1-u2-X06"},{"t":"아무 눈금이나 같아요","mis":"M4-1-u2-X06"}],"explanation":["그림에서 각도기의 중심과 밑금을 찾아요.","중심 → 꼭짓점, 밑금 → 한 변, 그 변 쪽 0에서 시작.","답은 「왼쪽이 0인 바깥쪽 눈금」이에요."],"asset":{"type":"prot","deg":null,"from":"right","parts":true},"variant_rule":{"alt":[{"stem":"각도기의 밑금은 무엇에 맞추나요?","options":[{"t":"각의 한 변","correct":true},{"t":"각의 꼭짓점","mis":"M4-1-u2-X07"},{"t":"각도기 맨 아래 끝","mis":"M4-1-u2-X07"},{"t":"가장 큰 눈금","mis":"M4-1-u2-X06"}],"explanation":["그림에서 각도기의 중심과 밑금을 찾아요.","중심 → 꼭짓점, 밑금 → 한 변, 그 변 쪽 0에서 시작.","답은 「각의 한 변」이에요."],"asset":{"type":"prot","deg":null,"from":"right","parts":true}},{"stem":"각도기의 중심은 각의 어디에 맞추나요?","options":[{"t":"꼭짓점","correct":true},{"t":"변의 끝","mis":"M4-1-u2-X07"},{"t":"변의 가운데","mis":"M4-1-u2-X07"},{"t":"각도기 맨 아래 끝","mis":"M4-1-u2-X07"}],"explanation":["그림에서 각도기의 중심과 밑금을 찾아요.","중심 → 꼭짓점, 밑금 → 한 변, 그 변 쪽 0에서 시작.","답은 「꼭짓점」이에요."],"asset":{"type":"prot","deg":null,"from":"right","parts":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_challenge#6','math',4,1,'u2','L03','g4_1_math_u2_L03_challenge','lesson_challenge','M4-1-u2-C4',3,'mc','auto','각도기로 잰 각의 크기는 몇 도인가요?',ARRAY['M4-1-u2-X06','M4-1-u2-X08']::text[],true,'{"seq":6,"concept":"M4-1-u2-C4","difficulty":3,"kind":"mc","stem":"각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"87°","correct":true},{"t":"93°","mis":"M4-1-u2-X06"},{"t":"97°","mis":"M4-1-u2-X08"},{"t":"77°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 왼쪽에 있어요 — 왼쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 87°.","93°는 다른 줄을 읽은 값이에요. 답은 87°예요."],"asset":{"type":"prot","deg":87,"from":"left"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"93°","correct":true},{"t":"87°","mis":"M4-1-u2-X06"},{"t":"103°","mis":"M4-1-u2-X08"},{"t":"83°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 오른쪽에 있어요 — 오른쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 93°.","87°는 다른 줄을 읽은 값이에요. 답은 93°예요."],"asset":{"type":"prot","deg":93,"from":"right"}},{"stem":"이번에는 다른 각이에요. 각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"133°","correct":true},{"t":"47°","mis":"M4-1-u2-X06"},{"t":"143°","mis":"M4-1-u2-X08"},{"t":"123°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 왼쪽에 있어요 — 왼쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 133°.","47°는 다른 줄을 읽은 값이에요. 답은 133°예요."],"asset":{"type":"prot","deg":133,"from":"left"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_challenge#7','math',4,1,'u2','L03','g4_1_math_u2_L03_challenge','lesson_challenge','M4-1-u2-C4',3,'sa','auto','꼭짓점을 각도기의 중심에 맞추었지만 한 변을 밑금에 맞추지 않았어요. 바깥쪽 눈금으로 한 변은 20, 다른 변은 85를 가리켜요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u2-C4","difficulty":3,"kind":"sa","stem":"꼭짓점을 각도기의 중심에 맞추었지만 한 변을 밑금에 맞추지 않았어요. 바깥쪽 눈금으로 한 변은 20, 다른 변은 85를 가리켜요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["0에서 시작하지 않았으니 두 눈금 사이가 각의 크기예요.","85 − 20 = 65.","각의 크기는 65°예요 (눈금 85만 읽으면 틀려요)."],"variant_rule":{"alt":[{"stem":"꼭짓점을 각도기의 중심에 맞추었지만 한 변을 밑금에 맞추지 않았어요. 바깥쪽 눈금으로 한 변은 30, 다른 변은 120을 가리켜요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["0에서 시작하지 않았으니 두 눈금 사이가 각의 크기예요.","120 − 30 = 90.","각의 크기는 90°예요 (눈금 120만 읽으면 틀려요)."],"asset":null},{"stem":"꼭짓점을 각도기의 중심에 맞추었지만 한 변을 밑금에 맞추지 않았어요. 바깥쪽 눈금으로 한 변은 15, 다른 변은 70을 가리켜요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["0에서 시작하지 않았으니 두 눈금 사이가 각의 크기예요.","70 − 15 = 55.","각의 크기는 55°예요 (눈금 70만 읽으면 틀려요)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_challenge#8','math',4,1,'u2','L03','g4_1_math_u2_L03_challenge','lesson_challenge','M4-1-u2-C4',4,'essay','teacher','각도기로 각의 크기를 재는 순서를 차례대로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u2-C4","difficulty":4,"kind":"essay","stem":"각도기로 각의 크기를 재는 순서를 차례대로 설명해 보세요.","answer_guide":{"answer":"예: ① 각도기의 중심을 각의 꼭짓점에 맞춘다. ② 밑금을 각의 한 변에 맞춘다. ③ 그 변이 0인 쪽 눈금에서 시작해 다른 변이 가리키는 눈금을 읽는다(변이 짧으면 늘인다).","scoring_points":["중심을 꼭짓점에 맞춘다고 했는가","밑금을 한 변에 맞춘다고 했는가","0에서 시작하는 눈금을 읽는다고 했는가"]},"explanation":["중심 → 꼭짓점.","밑금 → 한 변.","0에서 시작하는 눈금 읽기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_challenge#9','math',4,1,'u2','L03','g4_1_math_u2_L03_challenge','lesson_challenge','M4-1-u2-C4',4,'essay','teacher','지호는 각도기로 65°인 각을 115°라고 읽었어요. 지호가 무엇을 잘못했는지 쓰고, 바르게 읽는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u2-C4","difficulty":4,"kind":"essay","stem":"지호는 각도기로 65°인 각을 115°라고 읽었어요. 지호가 무엇을 잘못했는지 쓰고, 바르게 읽는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 다른 줄 눈금을 읽었다. 밑금 위의 변이 놓인 쪽에서 0으로 시작하는 눈금을 따라 읽어야 하고, 그러면 65°이다. 65°는 예각이니 115°(둔각)는 맞지 않는다.","scoring_points":["다른 줄 눈금을 읽었다고 했는가","변이 놓인 쪽 0에서 시작해 읽는다고 했는가","65°(예각인지 확인)라고 했는가"]},"explanation":["180 − 65 = 115 — 다른 줄 값이에요.","0에서 시작하는 줄을 찾아요.","직각보다 작은지 먼저 보면 실수를 막아요."],"asset":{"type":"prot","deg":65,"from":"right"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L03_challenge#10','math',4,1,'u2','L03','g4_1_math_u2_L03_challenge','lesson_challenge','M4-1-u2-C4',4,'sa','auto','꼭짓점을 각도기의 중심에 맞추었지만 한 변을 밑금에 맞추지 않았어요. 바깥쪽 눈금으로 한 변은 35, 다른 변은 110을 가리켜요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u2-C4","difficulty":4,"kind":"sa","stem":"꼭짓점을 각도기의 중심에 맞추었지만 한 변을 밑금에 맞추지 않았어요. 바깥쪽 눈금으로 한 변은 35, 다른 변은 110을 가리켜요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["0에서 시작하지 않았으니 두 눈금 사이가 각의 크기예요.","110 − 35 = 75.","각의 크기는 75°예요 (눈금 110만 읽으면 틀려요)."],"variant_rule":{"alt":[{"stem":"꼭짓점을 각도기의 중심에 맞추었지만 한 변을 밑금에 맞추지 않았어요. 바깥쪽 눈금으로 한 변은 25, 다른 변은 140을 가리켜요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["0에서 시작하지 않았으니 두 눈금 사이가 각의 크기예요.","140 − 25 = 115.","각의 크기는 115°예요 (눈금 140만 읽으면 틀려요)."],"asset":null},{"stem":"꼭짓점을 각도기의 중심에 맞추었지만 한 변을 밑금에 맞추지 않았어요. 바깥쪽 눈금으로 한 변은 40, 다른 변은 95를 가리켜요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["0에서 시작하지 않았으니 두 눈금 사이가 각의 크기예요.","95 − 40 = 55.","각의 크기는 55°예요 (눈금 95만 읽으면 틀려요)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_basic#1','math',4,1,'u2','L04','g4_1_math_u2_L04_basic','lesson_basic','M4-1-u2-C5',1,'mc','auto','이 각은 어떤 각인가요?',ARRAY['M4-1-u2-X09','M4-1-u2-X02','M4-1-u2-X10']::text[],true,'{"seq":1,"concept":"M4-1-u2-C5","difficulty":1,"kind":"mc","stem":"이 각은 어떤 각인가요?","options":[{"t":"예각","correct":true},{"t":"둔각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 작아요.","답은 예각이에요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,86.706637066],[126.0,86.706637066]],[[16.0,86.706637066],[100.264888743,16.0]]],"arc":[[[126.0,86.706637066],[16.0,86.706637066],[100.264888743,16.0]]],"w":142,"h":103}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 이 각은 어떤 각인가요?","options":[{"t":"둔각","correct":true},{"t":"예각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 커요.","답은 둔각이에요."],"asset":{"type":"geo","items":[{"seg":[[[86.706637066,100.264888743],[196.706637066,100.264888743]],[[86.706637066,100.264888743],[16.0,16.0]]],"arc":[[[196.706637066,100.264888743],[86.706637066,100.264888743],[16.0,16.0]]],"w":213,"h":116}],"tag":false}},{"stem":"이번에는 다른 각이에요. 이 각은 어떤 각인가요?","options":[{"t":"직각","correct":true},{"t":"예각","mis":"M4-1-u2-X02"},{"t":"둔각","mis":"M4-1-u2-X10"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 작지도 크지도 않아요.","답은 직각이에요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,126.0],[126.0,126.0]],[[16.0,126.0],[16.0,16.0]]],"right":[[[126.0,126.0],[16.0,126.0],[16.0,16.0]]],"w":142,"h":142}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qki