INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_basic#3','math',4,1,'u2','L04','g4_1_math_u2_L04_basic','lesson_basic','M4-1-u2-C5',1,'sa','auto','예각은 0°보다 크고 몇 도보다 작은 각인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u2-C5","difficulty":1,"kind":"sa","stem":"예각은 0°보다 크고 몇 도보다 작은 각인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["직각(90°)을 기준으로 나눠요.","예각 0°~90° 사이 · 둔각 90°~180° 사이(끝은 넣지 않음).","답은 90°예요."],"variant_rule":{"alt":[{"stem":"둔각은 90°보다 크고 몇 도보다 작은 각인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["직각(90°)을 기준으로 나눠요.","예각 0°~90° 사이 · 둔각 90°~180° 사이(끝은 넣지 않음).","답은 180°예요."],"asset":null},{"stem":"둔각은 몇 도보다 크고 180°보다 작은 각인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["직각(90°)을 기준으로 나눠요.","예각 0°~90° 사이 · 둔각 90°~180° 사이(끝은 넣지 않음).","답은 90°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_basic#4','math',4,1,'u2','L04','g4_1_math_u2_L04_basic','lesson_basic','M4-1-u2-C5',1,'mc','auto','둔각은 어느 것인가요?',ARRAY['M4-1-u2-X09','M4-1-u2-X10']::text[],true,'{"seq":4,"concept":"M4-1-u2-C5","difficulty":1,"kind":"mc","stem":"둔각은 어느 것인가요?","options":[{"t":"110°","correct":true},{"t":"25°","mis":"M4-1-u2-X09"},{"t":"90°","mis":"M4-1-u2-X10"},{"t":"180°","mis":"M4-1-u2-X10"}],"explanation":["둔각은 직각보다 크고 일직선보다 작은 각.","90°는 직각, 180°는 일직선이에요.","답은 110°예요."],"variant_rule":{"alt":[{"stem":"예각은 어느 것인가요?","options":[{"t":"15°","correct":true},{"t":"100°","mis":"M4-1-u2-X09"},{"t":"90°","mis":"M4-1-u2-X10"},{"t":"180°","mis":"M4-1-u2-X10"}],"explanation":["예각은 직각보다 작은 각.","90°는 직각, 180°는 일직선이에요.","답은 15°예요."],"asset":null},{"stem":"이번에는 다른 각이에요. 둔각은 어느 것인가요?","options":[{"t":"125°","correct":true},{"t":"85°","mis":"M4-1-u2-X09"},{"t":"90°","mis":"M4-1-u2-X10"},{"t":"180°","mis":"M4-1-u2-X10"}],"explanation":["둔각은 직각보다 크고 일직선보다 작은 각.","90°는 직각, 180°는 일직선이에요.","답은 125°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_basic#5','math',4,1,'u2','L04','g4_1_math_u2_L04_basic','lesson_basic','M4-1-u2-C5',2,'ox','auto','90°는 예각이에요.',ARRAY['M4-1-u2-X10']::text[],true,'{"seq":5,"concept":"M4-1-u2-C5","difficulty":2,"kind":"ox","stem":"90°는 예각이에요.","answer":"X","reason_options":[{"t":"90°는 직각이라서 예각도 둔각도 아니라서","correct":true},{"t":"90°는 작은 편이라 예각이라서","mis":"M4-1-u2-X10"}],"mis":"M4-1-u2-X10","explanation":["예각은 90°보다 작은 각이에요.","90°는 직각이에요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"180°는 둔각이에요.","answer":"X","reason_options":[{"t":"180°는 일직선이라 둔각이 아니라서","correct":true},{"t":"90°보다 크니 둔각이라서","mis":"M4-1-u2-X10"}],"explanation":["둔각은 180°보다 작아야 해요.","180°는 일직선이에요.","그래서 틀렸어요."],"asset":null},{"stem":"예각은 직각보다 작은 각이에요.","answer":"O","reason_options":[{"t":"0°보다 크고 90°보다 작은 각이라서","correct":true},{"t":"직각보다 큰 각이 예각이라서","mis":"M4-1-u2-X09"}],"explanation":["예각은 직각보다 작아요.","둔각이 직각보다 커요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_basic#6','math',4,1,'u2','L04','g4_1_math_u2_L04_basic','lesson_basic','M4-1-u2-C5',2,'mc','auto','2시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각은 어떤 각인가요?',ARRAY['M4-1-u2-X09','M4-1-u2-X02','M4-1-u2-X10']::text[],true,'{"seq":6,"concept":"M4-1-u2-C5","difficulty":2,"kind":"mc","stem":"2시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각은 어떤 각인가요?","options":[{"t":"예각","correct":true},{"t":"둔각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["숫자 한 칸 사이의 각은 360 ÷ 12 = 30°예요.","2칸 — 30 × 2 = 60°.","60°는 예각이에요."],"asset":{"type":"clock2","h":2,"m":0},"variant_rule":{"alt":[{"stem":"5시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각은 어떤 각인가요?","options":[{"t":"둔각","correct":true},{"t":"예각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["숫자 한 칸 사이의 각은 360 ÷ 12 = 30°예요.","5칸 — 30 × 5 = 150°.","150°는 둔각이에요."],"asset":{"type":"clock2","h":5,"m":0}},{"stem":"3시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각은 어떤 각인가요?","options":[{"t":"직각","correct":true},{"t":"예각","mis":"M4-1-u2-X02"},{"t":"둔각","mis":"M4-1-u2-X10"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["숫자 한 칸 사이의 각은 360 ÷ 12 = 30°예요.","3칸 — 30 × 3 = 90°.","90°는 직각이에요."],"asset":{"type":"clock2","h":3,"m":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_basic#7','math',4,1,'u2','L04','g4_1_math_u2_L04_basic','lesson_basic','M4-1-u2-C5',2,'sa','auto','30°, 90°, 120°, 75°, 180° 가운데 예각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u2-C5","difficulty":2,"kind":"sa","stem":"30°, 90°, 120°, 75°, 180° 가운데 예각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["예각은 0°보다 크고 90°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","예각은 30°, 75°. — 2개."],"variant_rule":{"alt":[{"stem":"100°, 90°, 45°, 170°, 135° 가운데 둔각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["둔각은 90°보다 크고 180°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","둔각은 100°, 170°, 135°. — 3개."],"asset":null},{"stem":"85°, 95°, 15°, 90°, 60° 가운데 예각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["예각은 0°보다 크고 90°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","예각은 85°, 15°, 60°. — 3개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_basic#8','math',4,1,'u2','L04','g4_1_math_u2_L04_basic','lesson_basic','M4-1-u2-C5',2,'match','auto','각의 크기와 각의 이름을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u2-C5","difficulty":2,"kind":"match","stem":"각의 크기와 각의 이름을 알맞게 이으세요.","pairs":[{"l":"35°","r":"예각"},{"l":"90°","r":"직각"},{"l":"125°","r":"둔각"}],"mis":"M4-1-u2-X09","explanation":["직각 90°가 기준이에요.","35° → 예각, 90° → 직각, 125° → 둔각.","90°보다 작으면 예각, 크면 둔각."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각의 크기와 각의 이름을 알맞게 이으세요.","pairs":[{"l":"160°","r":"둔각"},{"l":"80°","r":"예각"},{"l":"90°","r":"직각"}],"explanation":["직각 90°가 기준이에요.","160° → 둔각, 80° → 예각, 90° → 직각.","90°보다 작으면 예각, 크면 둔각."],"asset":null},{"stem":"이번에는 다른 각이에요. 각의 크기와 각의 이름을 알맞게 이으세요.","pairs":[{"l":"5°","r":"예각"},{"l":"95°","r":"둔각"},{"l":"180°","r":"일직선"}],"explanation":["직각 90°가 기준이에요.","5° → 예각, 95° → 둔각, 180° → 일직선.","90°보다 작으면 예각, 크면 둔각."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_basic#9','math',4,1,'u2','L04','g4_1_math_u2_L04_basic','lesson_basic','M4-1-u2-C5',2,'mc','auto','이 각은 어떤 각인가요?',ARRAY['M4-1-u2-X09','M4-1-u2-X02','M4-1-u2-X10']::text[],true,'{"seq":9,"concept":"M4-1-u2-C5","difficulty":2,"kind":"mc","stem":"이 각은 어떤 각인가요?","options":[{"t":"둔각","correct":true},{"t":"예각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 커요.","답은 둔각이에요."],"asset":{"type":"geo","items":[{"seg":[[[93.781745931,93.781745931],[178.046634674,23.075108865]],[[93.781745931,93.781745931],[16.0,16.0]]],"arc":[[[178.046634674,23.075108865],[93.781745931,93.781745931],[16.0,16.0]]],"w":194,"h":110}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 이 각은 어떤 각인가요?","options":[{"t":"예각","correct":true},{"t":"둔각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 작아요.","답은 예각이에요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,115.693856574],[119.366188286,153.31607234]],[[16.0,115.693856574],[62.488008791,16.0]]],"arc":[[[119.366188286,153.31607234],[16.0,115.693856574],[62.488008791,16.0]]],"w":135,"h":169}],"tag":false}},{"stem":"이번에는 다른 각이에요. 이 각은 어떤 각인가요?","options":[{"t":"직각","correct":true},{"t":"예각","mis":"M4-1-u2-X02"},{"t":"둔각","mis":"M4-1-u2-X10"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 작지도 크지도 않아요.","답은 직각이에요."],"asset":{"type":"geo","items":[{"seg":[[[79.093407999,106.106724872],[169.20013287,43.013316873]],[[79.093407999,106.106724872],[16.0,16.0]]],"right":[[[169.20013287,43.013316873],[79.093407999,106.106724872],[16.0,16.0]]],"w":185,"h":122}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SE