,16.0]]],"arc":[[[316.0,16.0],[16.0,189.205080757],[216.0,189.205080757]],[[16.0,189.205080757],[216.0,189.205080757],[316.0,16.0]],[[216.0,189.205080757],[316.0,16.0],[16.0,189.205080757]]],"lab":[[[77.819252883,172.64066187],"30°"],[[196.0,154.564064606],"120°"],[[270.745166004,61.254833996],"30°"]],"w":332,"h":205}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#1','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',2,'ox','auto','둔각을 돌려 세워 놓으면 예각이 될 수 있어요.',ARRAY['M4-1-u2-X02']::text[],true,'{"seq":1,"concept":"M4-1-u2-C5","difficulty":2,"kind":"ox","stem":"둔각을 돌려 세워 놓으면 예각이 될 수 있어요.","answer":"X","reason_options":[{"t":"돌려도 벌어진 정도가 그대로라 둔각이라서","correct":true},{"t":"세워 놓으면 좁아 보여서","mis":"M4-1-u2-X02"}],"mis":"M4-1-u2-X02","explanation":["각의 종류는 크기로 정해요.","돌려 놓아도 크기는 그대로예요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"직각보다 큰 각은 모두 둔각이에요.","answer":"X","reason_options":[{"t":"180°보다 작아야 둔각이라서","correct":true},{"t":"90°보다 크기만 하면 둔각이라서","mis":"M4-1-u2-X10"}],"explanation":["둔각은 90°보다 크고 180°보다 작은 각이에요.","200°처럼 180°를 넘는 각은 둔각이 아니에요.","그래서 틀렸어요."],"asset":null},{"stem":"90°는 예각이에요.","answer":"X","reason_options":[{"t":"90°는 직각이라서 예각도 둔각도 아니라서","correct":true},{"t":"90°는 작은 편이라 예각이라서","mis":"M4-1-u2-X10"}],"explanation":["예각은 90°보다 작은 각이에요.","90°는 직각이에요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#2','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',2,'mc','auto','4시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각은 어떤 각인가요?',ARRAY['M4-1-u2-X09','M4-1-u2-X02','M4-1-u2-X10']::text[],true,'{"seq":2,"concept":"M4-1-u2-C5","difficulty":2,"kind":"mc","stem":"4시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각은 어떤 각인가요?","options":[{"t":"둔각","correct":true},{"t":"예각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["숫자 한 칸 사이의 각은 360 ÷ 12 = 30°예요.","4칸 — 30 × 4 = 120°.","120°는 둔각이에요."],"asset":{"type":"clock2","h":4,"m":0},"variant_rule":{"alt":[{"stem":"1시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각은 어떤 각인가요?","options":[{"t":"예각","correct":true},{"t":"둔각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["숫자 한 칸 사이의 각은 360 ÷ 12 = 30°예요.","1칸 — 30 × 1 = 30°.","30°는 예각이에요."],"asset":{"type":"clock2","h":1,"m":0}},{"stem":"9시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각은 어떤 각인가요?","options":[{"t":"직각","correct":true},{"t":"예각","mis":"M4-1-u2-X02"},{"t":"둔각","mis":"M4-1-u2-X10"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["숫자 한 칸 사이의 각은 360 ÷ 12 = 30°예요.","3칸 — 30 × 3 = 90°.","90°는 직각이에요."],"asset":{"type":"clock2","h":9,"m":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
