2"],"explanation":["각을 하나씩 직각과 견주어요.","90° 직각, 45° 예각, 45° 예각.","예각은 2개."],"asset":{"type":"geo","items":[{"poly":[[[16.0,216.0],[216.0,216.0],[16.0,16.0]]],"arc":[[[16.0,216.0],[216.0,216.0],[16.0,16.0]],[[216.0,216.0],[16.0,16.0],[16.0,216.0]]],"lab":[[[52.769552622,179.230447378],"90°"],[[156.871709919,191.508260329],"45°"],[[40.491739671,75.128290081],"45°"]],"right":[[[16.0,16.0],[16.0,216.0],[216.0,216.0]]],"w":232,"h":232}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#4','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',3,'sa','auto','89°, 91°, 90°, 179°, 180°, 1° 가운데 둔각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u2-C5","difficulty":3,"kind":"sa","stem":"89°, 91°, 90°, 179°, 180°, 1° 가운데 둔각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["둔각은 90°보다 크고 180°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","둔각은 91°, 179°. — 2개."],"variant_rule":{"alt":[{"stem":"5°, 90°, 45°, 180°, 120°, 88° 가운데 예각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["예각은 0°보다 크고 90°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","예각은 5°, 45°, 88°. — 3개."],"asset":null},{"stem":"92°, 180°, 150°, 90°, 60°, 135° 가운데 둔각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["둔각은 90°보다 크고 180°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","둔각은 92°, 150°, 135°. — 3개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#5','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',3,'sa','auto','1시부터 6시까지 정각마다 시계를 보았어요. 긴바늘과 짧은바늘이 이루는 작은 쪽의 각이 둔각인 시각은 몇 번인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u2-C5","difficulty":3,"kind":"sa","stem":"1시부터 6시까지 정각마다 시계를 보았어요. 긴바늘과 짧은바늘이 이루는 작은 쪽의 각이 둔각인 시각은 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["숫자 한 칸은 30°예요.","1시 30°, 2시 60°, 3시 90°, 4시 120°, 5시 150°, 6시 180°.","둔각은 4시, 5시 — 2번."],"variant_rule":{"alt":[{"stem":"1시부터 6시까지 정각마다 시계를 보았어요. 긴바늘과 짧은바늘이 이루는 작은 쪽의 각이 예각인 시각은 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["숫자 한 칸은 30°예요.","1시 30°, 2시 60°, 3시 90°, 4시 120°, 5시 150°, 6시 180°.","예각은 1시, 2시 — 2번."],"asset":null},{"stem":"7시부터 12시까지 정각마다 시계를 보았어요. 긴바늘과 짧은바늘이 이루는 작은 쪽의 각이 둔각인 시각은 몇 번인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["숫자 한 칸은 30°예요.","7시 150°, 8시 120°, 9시 90°, 10시 60°, 11시 30°, 12시 0°.","둔각은 7시, 8시 — 2번."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#6','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',3,'error','auto','각을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X10','M4-1-u2-X19']::text[],true,'{"seq":6,"concept":"M4-1-u2-C5","difficulty":3,"kind":"error","stem":"각을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「90°는 예각이에요.」","correct":true,"mis_target":"M4-1-u2-X10"},{"t":"준서 — 「35°는 예각이에요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「140°는 둔각이에요.」","mis":"M4-1-u2-X19"}],"explanation":["예각은 0°~90° 사이, 둔각은 90°~180° 사이 — 끝은 넣지 않아요.","90°는 직각, 180°는 일직선이에요.","도윤이 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「180°는 둔각이에요.」","correct":true,"mis_target":"M4-1-u2-X10"},{"t":"도윤 — 「150°는 둔각이에요.」","mis":"M4-1-u2-X19"},{"t":"하람 — 「70°는 예각이에요.」","mis":"M4-1-u2-X19"}],"explanation":["예각은 0°~90° 사이, 둔각은 90°~180° 사이 — 끝은 넣지 않아요.","90°는 직각, 180°는 일직선이에요.","예린이 잘못 말했어요."],"asset":null},{"stem":"이번에는 다른 각이에요. 각을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「90°는 예각이에요.」","correct":true,"mis_target":"M4-1-u2-X10"},{"t":"예린 — 「20°는 예각이에요.」","mis":"M4-1-u2-X19"},{"t":"나래 — 「100°는 둔각이에요.」","mis":"M4-1-u2-X19"}],"explanation":["예각은 0°~90° 사이, 둔각은 90°~180° 사이 — 끝은 넣지 않아요.","90°는 직각, 180°는 일직선이에요.","은비가 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#7','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',3,'mc','auto','예각은 어느 것인가요?',ARRAY['M4-1-u2-X09','M4-1-u2-X10']::text[],true,'{"seq":7,"concept":"M4-1-u2-C5","difficulty":3,"kind":"mc","stem":"예각은 어느 것인가요?","options":[{"t":"40°","correct":true},{"t":"130°","mis":"M4-1-u2-X09"},{"t":"90°","mis":"M4-1-u2-X10"},{"t":"180°","mis":"M4-1-u2-X10"}],"explanation":["예각은 직각보다 작은 각.","90°는 직각, 180°는 일직선이에요.","답은 40°예요."],"variant_rule":{"alt":[{"stem":"둔각은 어느 것인가요?","options":[{"t":"130°","correct":true},{"t":"65°","mis":"M4-1-u2-X09"},{"t":"90°","mis":"M4-1-u2-X10"},{"t":"180°","mis":"M4-1-u2-X10"}],"explanation":["둔각은 직각보다 크고 일직선보다 작은 각.","90°는 직각, 180°는 일직선이에요.","답은 130°예요."],"asset":null},{"stem":"이번에는 다른 각이에요. 예각은 어느 것인가요?","options":[{"t":"25°","correct":true},{"t":"165°","mis":"M4-1-u2-X09"},{"t":"90°","mis":"M4-1-u2-X10"},{"t":"180°","mis":"M4-1-u2-X10"}],"explanation":["예각은 직각보다 작은 각.","90°는 직각, 180°는 일직선이에요.","답은 25°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#8','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',4,'essay','teacher','4시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각이 예각인지 둔각인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u2-C5","difficulty":4,"kind":"essay","stem":"4시에 시계의 긴바늘과 짧은바늘이 이루는 작은 쪽의 각이 예각인지 둔각인지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 둔각이다. 숫자 한 칸 사이의 각은 30°이고 4시는 4칸이므로 120°이다. 120°는 90°보다 크고 180°보다 작으므로 둔각이다.","scoring_points":["둔각이라고 답했는가","30° × 4 = 120°를 구했는가","직각(90°)과 견주어 설명했는가"]},"explanation":["360 ÷ 12 = 30.","30 × 4 = 120.","90° < 120° < 180° — 둔각."],"asset":{"type":"clock2","h":4,"m":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#9','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',4,'essay','teacher','「직각보다 큰 각은 모두 둔각이에요.」라는 말이 맞는지 쓰고 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u2-C5","difficulty":4,"kind":"essay","stem":"「직각보다 큰 각은 모두 둔각이에요.」라는 말이 맞는지 쓰고 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 틀리다. 둔각은 90°보다 크고 180°보다 작은 각이다. 180°는 일직선이고, 180°보다 큰 각도 둔각이 아니다.","scoring_points":["틀리다고 답했는가","둔각의 범위(90°~180°)를 썼는가","180°나 그보다 큰 각을 예로 들었는가"]},"explanation":["둔각은 180°보다 작아야 해요.","180°는 일직선이에요.","그래서 「모두」는 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L04_challenge#10','math',4,1,'u2','L04','g4_1_math_u2_L04_challenge','lesson_challenge','M4-1-u2-C5',4,'sa','auto','45°짜리 각을 한 개씩 이어 붙이고 있어요. 몇 개를 붙였을 때 처음으로 둔각이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u2-C5","difficulty":4,"kind":"sa","stem":"45°짜리 각을 한 개씩 이어 붙이고 있어요. 몇 개를 붙였을 때 처음으로 둔각이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["둔각은 90°보다 커야 해요.","1개 45°, 2개 90°, 3개 135°.","3개일 때 135°로 처음 둔각이에요."],"variant_rule":{"alt":[{"stem":"30°짜리 각을 한 개씩 이어 붙이고 있어요. 몇 개를 붙였을 때 처음으로 둔각이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["둔각은 90°보다 커야 해요.","1개 30°, 2개 60°, 3개 90°, 4개 120°.","4개일 때 120°로 처음 둔각이에요."],"asset":null},{"stem":"20°짜리 각을 한 개씩 이어 붙이고 있어요. 몇 개를 붙였을 때 처음으로 둔각이 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["둔각은 90°보다 커야 해요.","1개 20°, 2개 40°, 3개 60°, 4개 80°, 5개 100°.","5개일 때 100°로 처음 둔각이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_basic#1','math',4,1,'u2','L05','g4_1_math_u2_L05_basic','lesson_basic','M4-1-u2-C6',1,'mc','auto','이 각은 둔각이에요. 어떻게 어림해야 하나요?',ARRAY['M4-1-u2-X11','M4-1-u2-X01']::text[],true,'{"seq":1,"concept":"M4-1-u2-C6","difficulty":1,"kind":"mc","stem":"이 각은 둔각이에요. 어떻게 어림해야 하나요?","options":[{"t":"90°보다 크게 어림해요","correct":true},{"t":"90°보다 작게 어림해요","mis":"M4-1-u2-X11"},{"t":"꼭 90°로 어림해요","mis":"M4-1-u2-X11"},{"t":"변이 길면 크게 어림해요","mis":"M4-1-u2-X01"}],"explanation":["둔각은 직각보다 커요.","직각 90°가 첫 번째 기준이에요.","90°보다 크게 어림해요."],"variant_rule":{"alt":[{"stem":"이 각은 예각이에요. 어떻게 어림해야 하나요?","options":[{"t":"90°보다 작게 어림해요","correct":true},{"t":"90°보다 크게 어림해요","mis":"M4-1-u2-X11"},{"t":"꼭 90°로 어림해요","mis":"M4-1-u2-X11"},{"t":"변이 길면 크게 어림해요","mis":"M4-1-u2-X01"}],"explanation":["예각은 직각보다 작아요.","직각 90°가 첫 번째 기준이에요.","90°보다 작게 어림해요."],"asset":null},{"stem":"이번에는 다른 각이에요. 이 각은 둔각이에요. 어떻게 어림해야 하나요?","options":[{"t":"90°보다 크게 어림해요","correct":true},{"t":"90°보다 작게 어림해요","mis":"M4-1-u2-X11"},{"t":"꼭 90°로 어림해요","mis":"M4-1-u2-X11"},{"t":"변이 길면 크게 어림해요","mis":"M4-1-u2-X01"}],"explanation":["둔각은 직각보다 커요.","직각 90°가 첫 번째 기준이에요.","90°보다 크게 어림해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_basic#2','math',4,1,'u2','L05','g4_1_math_u2_L05_basic','lesson_basic','M4-1-u2-C6',1,'sa','auto','직각을 똑같이 둘로 나눈 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u2-C6","difficulty":1,"kind":"sa","stem":"직각을 똑같이 둘로 나눈 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["직각은 90°, 일직선은 180°예요.","90 ÷ 2 = 45.","45°예요 — 어림할 때 기준으로 써요."],"variant_rule":{"alt":[{"stem":"직각과 직각의 반을 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["직각은 90°, 일직선은 180°예요.","90 + 45 = 135.","135°예요 — 어림할 때 기준으로 써요."],"asset":null},{"stem":"일직선(180°)을 똑같이 넷으로 나눈 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["직각은 90°, 일직선은 180°예요.","180 ÷ 4 = 45.","45°예요 — 어림할 때 기준으로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_basic#3','math',4,1,'u2','L05','g4_1_math_u2_L05_basic','lesson_basic','M4-1-u2-C6',1,'mc','auto','기준선을 보고 이 각의 크기를 어림하면 약 몇 도인가요?',ARRAY['M4-1-u2-X11']::text[],true,'{"seq":3,"concept":"M4-1-u2-C6","difficulty":1,"kind":"mc","stem":"기준선을 보고 이 각의 크기를 어림하면 약 몇 도인가요?","options":[{"t":"약 60°","correct":true},{"t":"약 120°","mis":"M4-1-u2-X11"},{"t":"약 20°","mis":"M4-1-u2-X11"},{"t":"약 100°","mis":"M4-1-u2-X11"}],"explanation":["먼저 직각(90°)보다 작은지 큰지 봐요.","45°·90°·135° 기준선 사이 어디쯤인지 견주어요.","약 60°쯤이에요."],"asset":{"type":"geo","items":[{"seg":[[[120.792510704,154.4],[240.792510704,154.4]],[[120.792510704,154.4],[177.129098239,48.446288857]]],"arc":[[[240.792510704,154.4],[120.792510704,154.4],[177.129098239,48.446288857]]],"dash":[[[120.792510704,154.4],[198.857099347,76.335411357]],[[120.792510704,154.4],[120.792510704,44.0]],[[120.792510704,154.4],[42.727922061,76.335411357]]],"lab":[[[211.585021409,63.607489296],"45°"],[[120.792510704,26.0],"90°"],[[30.0,63.607489296],"135°"]],"w":257,"h":170}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 기준선을 보고 이 각의 크기를 어림하면 약 몇 도인가요?","options":[{"t":"약 120°","correct":true},{"t":"약 60°","mis":"M4-1-u2-X11"},{"t":"약 80°","mis":"M4-1-u2-X11"},{"t":"약 160°","mis":"M4-1-u2-X11"}],"explanation":["먼저 직각(90°)보다 작은지 큰지 봐요.","45°·90°·135° 기준선 사이 어디쯤인지 견주어요.","약 120°쯤이에요."],"asset":{"type":"geo","items":[{"seg":[[[120.792510704,154.4],[240.792510704,154.4]],[[120.792510704,154.4],[64.45592317,48.446288857]]],"arc":[[[240.792510704,154.4],[120.792510704,154.4],[64.45592317,48.446288857]]],"dash":[[[120.792510704,154.4],[198.857099347,76.335411357]],[[120.792510704,154.4],[120.792510704,44.0]],[[120.792510704,154.4],[42.727922061,76.335411357]]],"lab":[[[211.585021409,63.607489296],"45°"],[[120.792510704,26.0],"90°"],[[30.0,63