INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_basic#6','math',4,1,'u2','L05','g4_1_math_u2_L05_basic','lesson_basic','M4-1-u2-C6',2,'sa','auto','약 120°로 어림했는데 각도기로 재어 보니 115°였어요. 어림한 값과 잰 값의 차는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u2-C6","difficulty":2,"kind":"sa","stem":"약 120°로 어림했는데 각도기로 재어 보니 115°였어요. 어림한 값과 잰 값의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["큰 각도에서 작은 각도를 빼요.","120 − 115 = 5.","차는 5°예요."],"variant_rule":{"alt":[{"stem":"약 60°로 어림했는데 각도기로 재어 보니 68°였어요. 어림한 값과 잰 값의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["큰 각도에서 작은 각도를 빼요.","68 − 60 = 8.","차는 8°예요."],"asset":null},{"stem":"약 45°로 어림했는데 각도기로 재어 보니 52°였어요. 어림한 값과 잰 값의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["큰 각도에서 작은 각도를 빼요.","52 − 45 = 7.","차는 7°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_basic#7','math',4,1,'u2','L05','g4_1_math_u2_L05_basic','lesson_basic','M4-1-u2-C6',2,'mc','auto','각도기로 재니 70°인 각을 도윤는 약 60°, 준서는 약 90°, 지호는 약 75°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?',ARRAY['M4-1-u2-X12']::text[],true,'{"seq":7,"concept":"M4-1-u2-C6","difficulty":2,"kind":"mc","stem":"각도기로 재니 70°인 각을 도윤는 약 60°, 준서는 약 90°, 지호는 약 75°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"지호","correct":true},{"t":"준서","mis":"M4-1-u2-X12"},{"t":"도윤","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","도윤 10°, 준서 20°, 지호 5° 차이.","차가 가장 작은 지호가 가장 잘 어림했어요."],"variant_rule":{"alt":[{"stem":"각도기로 재니 125°인 각을 예린는 약 120°, 도윤는 약 140°, 하람는 약 90°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"예린","correct":true},{"t":"하람","mis":"M4-1-u2-X12"},{"t":"도윤","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","예린 5°, 도윤 15°, 하람 35° 차이.","차가 가장 작은 예린이 가장 잘 어림했어요."],"asset":null},{"stem":"각도기로 재니 40°인 각을 은비는 약 60°, 예린는 약 45°, 나래는 약 20°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"예린","correct":true},{"t":"은비","mis":"M4-1-u2-X12"},{"t":"나래","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","은비 20°, 예린 5°, 나래 20° 차이.","차가 가장 작은 예린이 가장 잘 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_basic#8','math',4,1,'u2','L05','g4_1_math_u2_L05_basic','lesson_basic','M4-1-u2-C6',2,'error','auto','축제장 놀이기구가 기울어진 각을 각도기로 재니 35°였어요. 어림을 잘못한 친구는 누구인가요?',ARRAY['M4-1-u2-X11','M4-1-u2-X19']::text[],true,'{"seq":8,"concept":"M4-1-u2-C6","difficulty":2,"kind":"error","stem":"축제장 놀이기구가 기울어진 각을 각도기로 재니 35°였어요. 어림을 잘못한 친구는 누구인가요?","options":[{"t":"도윤 — 「약 140°쯤일 거야.」","correct":true,"mis_target":"M4-1-u2-X11"},{"t":"준서 — 「약 40°쯤일 거야.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「직각보다 작게 어림했어.」","mis":"M4-1-u2-X19"}],"explanation":["35°는 직각보다 작아요.","약 40°처럼 가깝게 어림해야 해요.","도윤은 직각과 견주지 않고 크게 어림했어요."],"variant_rule":{"alt":[{"stem":"축제장 놀이기구가 기울어진 각을 각도기로 재니 125°였어요. 어림을 잘못한 친구는 누구인가요?","options":[{"t":"예린 — 「약 60°쯤일 거야.」","correct":true,"mis_target":"M4-1-u2-X11"},{"t":"도윤 — 「약 120°쯤일 거야.」","mis":"M4-1-u2-X19"},{"t":"하람 — 「직각보다 크게 어림했어.」","mis":"M4-1-u2-X19"}],"explanation":["125°는 직각보다 커요.","약 120°처럼 가깝게 어림해야 해요.","예린은 직각과 견주지 않고 작게 어림했어요."],"asset":null},{"stem":"축제장 놀이기구가 기울어진 각을 각도기로 재니 70°였어요. 어림을 잘못한 친구는 누구인가요?","options":[{"t":"은비 — 「약 110°쯤일 거야.」","correct":true,"mis_target":"M4-1-u2-X11"},{"t":"예린 — 「약 70°쯤일 거야.」","mis":"M4-1-u2-X19"},{"t":"나래 — 「직각보다 작게 어림했어.」","mis":"M4-1-u2-X19"}],"explanation":["70°는 직각보다 작아요.","약 70°처럼 가깝게 어림해야 해요.","은비는 직각과 견주지 않고 크게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_basic#9','math',4,1,'u2','L05','g4_1_math_u2_L05_basic','lesson_basic','M4-1-u2-C6',2,'mc','auto',' 이 각의 크기를 어림하면 약 몇 도인가요?',ARRAY['M4-1-u2-X11']::text[],true,'{"seq":9,"concept":"M4-1-u2-C6","difficulty":2,"kind":"mc","stem":" 이 각의 크기를 어림하면 약 몇 도인가요?","options":[{"t":"약 80°","correct":true},{"t":"약 100°","mis":"M4-1-u2-X11"},{"t":"약 40°","mis":"M4-1-u2-X11"},{"t":"약 120°","mis":"M4-1-u2-X11"}],"explanation":["먼저 직각(90°)보다 작은지 큰지 봐요.","직각의 반(45°)과도 견주어요.","약 80°쯤이에요."],"asset":{"type":"geo","items":[{"seg":[[[51.084604567,130.756570716],[155.007653021,70.756570716]],[[51.084604567,130.756570716],[16.0,16.0]]],"arc":[[[155.007653021,70.756570716],[51.084604567,130.756570716],[16.0,16.0]]],"w":171,"h":147}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요.  이 각의 크기를 어림하면 약 몇 도인가요?","options":[{"t":"약 130°","correct":true},{"t":"약 50°","mis":"M4-1-u2-X11"},{"t":"약 90°","mis":"M4-1-u2-X11"},{"t":"약 170°","mis":"M4-1-u2-X11"}],"explanation":["먼저 직각(90°)보다 작은지 큰지 봐요.","직각의 반(45°)과도 견주어요.","약 130°쯤이에요."],"asset":{"type":"geo","items":[{"seg":[[[97.839803207,103.762444194],[217.839803207,103.762444194]],[[97.839803207,103.762444194],[16.0,16.0]]],"arc":[[[217.839803207,103.762444194],[97.839803207,103.762444194],[16.0,16.0]]],"w":234,"h":120}],"tag":false}},{"stem":"이번에는 다른 각이에요.  이 각의 크기를 어림하면 약 몇 도인가요?","options":[{"t":"약 50°","correct":true},{"t":"약 130°","mis":"M4-1-u2-X11"},{"t":"약 10°","mis":"M4-1-u2-X11"},{"t":"약 90°","mis":"M4-1-u2-X11"}],"explanation":["먼저 직각(90°)보다 작은지 큰지 봐요.","직각의 반(45°)과도 견주어요.","약 50°쯤이에요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,126.460582414],[131.911099155,95.402297002]],[[16.0,126.460582414],[62.887735419,16.0]]],"arc":[[[131.911099155,95.402297002],[16.0,126.460582414],[62.887735419,16.0]]],"w":148,"h":142}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_basic#10','math',4,1,'u2','L05','g4_1_math_u2_L05_basic','lesson_basic','M4-1-u2-C6',3,'sa','auto','약 100°로 어림했는데 각도기로 재어 보니 87°였어요. 어림한 값과 잰 값의 차는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u2-C6","difficulty":3,"kind":"sa","stem":"약 100°로 어림했는데 각도기로 재어 보니 87°였어요. 어림한 값과 잰 값의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["큰 각도에서 작은 각도를 빼요.","100 − 87 = 13.","차는 13°예요."],"variant_rule":{"alt":[{"stem":"약 30°로 어림했는데 각도기로 재어 보니 41°였어요. 어림한 값과 잰 값의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["큰 각도에서 작은 각도를 빼요.","41 − 30 = 11.","차는 11°예요."],"asset":null},{"stem":"약 150°로 어림했는데 각도기로 재어 보니 138°였어요. 어림한 값과 잰 값의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["큰 각도에서 작은 각도를 빼요.","150 − 138 = 12.","차는 12°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#1','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',2,'sa','auto','어림한 뒤 각도기로 재어 확인하려고 해요. 각도기로 잰 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C6","difficulty":2,"kind":"sa","stem":"어림한 뒤 각도기로 재어 확인하려고 해요. 각도기로 잰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["112"],"explanation":["밑금 위 변 쪽 0에서 시작하는 눈금을 읽어요.","다른 변은 112°를 가리켜요.","잰 각은 112°예요."],"asset":{"type":"prot","deg":112,"from":"left"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 어림한 뒤 각도기로 재어 확인하려고 해요. 각도기로 잰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["밑금 위 변 쪽 0에서 시작하는 눈금을 읽어요.","다른 변은 58°를 가리켜요.","잰 각은 58°예요."],"asset":{"type":"prot","deg":58,"from":"right"}},{"stem":"이번에는 다른 각이에요. 어림한 뒤 각도기로 재어 확인하려고 해요. 각도기로 잰 각은 몇 도인가요? 숫자로 쓰세요.","answer":["167"],"explanation":["밑금 위 변 쪽 0에서 시작하는 눈금을 읽어요.","다른 변은 167°를 가리켜요.","잰 각은 167°예요."],"asset":{"type":"prot","deg":167,"from":"left"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#2','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',2,'ox','auto','어림한 값을 말할 때는 「약」을 붙여요.',ARRAY['M4-1-u2-X12']::text[],true,'{"seq":2,"concept":"M4-1-u2-C6","difficulty":2,"kind":"ox","stem":"어림한 값을 말할 때는 「약」을 붙여요.","answer":"O","reason_options":[{"t":"정확히 잰 값이 아니라서","correct":true},{"t":"각도기로 잰 값이라서","mis":"M4-1-u2-X12"}],"mis":"M4-1-u2-X12","explanation":["어림은 짐작한 값이에요.","약 60°처럼 말해요.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"각도는 아무 수나 마음대로 말해도 어림이에요.","answer":"X","reason_options":[{"t":"직각·45° 같은 기준과 견주어 짐작해야 해서","correct":true},{"t":"어림은 정답이 없어서","mis":"M4-1-u2-X11"}],"explanation":["기준 각과 견주어야 해요.","그래야 잰 값에 가까워져요.","그래서 틀렸어요."],"asset":null},{"stem":"어림한 값과 잰 값의 차가 클수록 잘 어림한 거예요.","answer":"X","reason_options":[{"t":"차가 작을수록 잰 값에 가까워 잘한 어림이라서","correct":true},{"t":"많이 다를수록 용감한 어림이라서","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","차가 작을수록 좋은 어림이에요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#3','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',3,'mc','auto','기준선을 보고 이 각의 크기를 어림하면 약 몇 도인가요?',ARRAY['M4-1-u2-X11']::text[],true,'{"seq":3,"concept":"M4-1-u2-C6","difficulty":3,"kind":"mc","stem":"기준선을 보고 이 각의 크기를 어림하면 약 몇 도인가요?","options":[{"t":"약 20°","correct":true},{"t":"약 160°","mis":"M4-1-u2-X11"},{"t":"약 10°","mis":"M4-1-u2-X11"},{"t":"약 60°","mis":"M4-1-u2-X11"}],"explanation":["먼저 직각(90°)보다 작은지 큰지 봐요.","45°·90°·135° 기준선 사이 어디쯤인지 견주어요.","약 20°쯤이에요."],"asset":{"type":"geo","items":[{"seg":[[[120.792510704,154.4],[240.792510704,154.4]],[[120.792510704,154.4],[232.054573252,109.44720879]]],"arc":[[[240.792510704,154.4],[120.792510704,154.4],[232.054573252,109.44720879]]],"dash":[[[120.792510704,154.4],[198.857099347,76.335411357]],[[120.792510704,154.4],[120.792510704,44.0]],[[120.792510704,154.4],[42.727922061,76.335411357]]],"lab":[[[211.585021409,63.607489296],"45°"],[[120.792510704,26.0],"90°"],[[30.0,63.607489296],"135°"]],"w":257,"h":170}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 기준선을 보고 이 각의 크기를 어림하면 약 몇 도인가요?","options":[{"t":"약 170°","correct":true},{"t":"약 10°","mis":"M4-1-u2-X11"},{"t":"약 130°","mis":"M4-1-u2-X11"},{"t":"약 90°","mis":"M4-1-u2-X11"}],"explanation":["먼저 직각(90°)보다 작은지 큰지 봐요.","45°·90°·135° 기준선 사이 어디쯤인지 견주어요.","약 170°쯤이에요."],"asset":{"type":"geo","items":[{"seg":[[[133.377712088,154.4],[253.377712088,154.4]],[[133.377712088,154.4],[16.0,129.450597102]]],"arc":[[[253.377712088,154.4],[133.377712088,154.4],[16.0,129.450597102]]],"dash":[[[133.377712088,154.4],[211.442300731,76.335411357]],[[133.377712088,154.4],[133.377712088,44.0]],[[133.377712088,154.4],[55.313123445,76.335411357]]],"lab":[[[224.170222792,63.607489296],"45°"],[[133.377712088,26.0],"90°"],[[42.585201384,63.607489296],"135°"]],"w":269,"h":170}],"tag":false}},{"stem":"이번에는 다른 각이에요. 기준선을 보고 이 각의 크기를 어림하면 약 몇 도인가요?","options":[{"t":"약 140°","correct":true},{"t":"약 40°","mis":"M4-1-u2-X11"},{"t":"약 100°","mis":"M4-1-u2-X11"},{"t":"약 170°","mis":"M4-1-u2-X11"}],"explanation":["먼저 직각(90°)보다 작은지 큰지 봐요.","45°·90°·135° 기준선 사이 어디쯤인지 견주어요.","약 140°쯤이에요."],"asset":{"type":"geo","items":[{"seg":[[[150.656532509,146.656532509],[259.413466953,95.9423411]],[[150.656532509,146.656532509],[36.529750553,109.574493184]]],"arc":[[[259.413466953,95.9423411],[150.656532509,146.656532509],[36.529750553,109.574493184]]],"dash":[[[150.656532509,146.656532509],[188.415556332,42.914467174]],[[150.656532509,146.656532509],[103.999476413,46.60015282]],[[150.656532509,146.656532509],[46.914467174,108.897508686]]],"lab":[[[194.571918912,26.0],"45°"],[[96.392347701,30.286612653],"90°"],[[30.0,102.741146106],"135°"]],"w":275,"h":163}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#4','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',3,'mc','auto','각도기로 재니 105°인 각을 지호는 약 110°, 준서는 약 90°, 예린는 약 130°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?',ARRAY['M4-1-u2-X12']::text[],true,'{"seq":4,"concept":"M4-1-u2-C6","difficulty":3,"kind":"mc","stem":"각도기로 재니 105°인 각을 지호는 약 110°, 준서는 약 90°, 예린는 약 130°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"지호","correct":true},{"t":"예린","mis":"M4-1-u2-X12"},{"t":"준서","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","지호 5°, 준서 15°, 예린 25° 차이.","차가 가장 작은 지호가 가장 잘 어림했어요."],"variant_rule":{"alt":[{"stem":"각도기로 재니 55°인 각을 준서는 약 40°, 도윤는 약 70°, 지호는 약 50°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"지호","correct":true},{"t":"준서","mis":"M4-1-u2-X12"},{"t":"도윤","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","준서 15°, 도윤 15°, 지호 5° 차이.","차가 가장 작은 지호가 가장 잘 어림했어요."],"asset":null},{"stem":"각도기로 재니 160°인 각을 예린는 약 150°, 나래는 약 175°, 준서는 약 120°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"예린","correct":true},{"t":"준서","mis":"M4-1-u2-X12"},{"t":"나래","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","예린 10°, 나래 15°, 준서 40° 차이.","차가 가장 작은 예린이 가장 잘 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#5','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',3,'error','auto','축제장 놀이기구가 기울어진 각을 각도기로 재니 150°였어요. 어림을 잘못한 친구는 누구인가요?',ARRAY['M4-1-u2-X11','M4-1-u2-X19']::text[],true,'{"seq":5,"concept":"M4-1-u2-C6","difficulty":3,"kind":"error","stem":"축제장 놀이기구가 기울어진 각을 각도기로 재니 150°였어요. 어림을 잘못한 친구는 누구인가요?","options":[{"t":"지호 — 「약 30°쯤일 거야.」","correct":true,"mis_target":"M4-1-u2-X11"},{"t":"준서 — 「약 150°쯤일 거야.」","mis":"M4-1-u2-X19"},{"t":"예린 — 「직각보다 크게 어림했어.」","mis":"M4-1-u2-X19"}],"explanation":["150°는 직각보다 커요.","약 150°처럼 가깝게 어림해야 해요.","지호는 직각과 견주지 않고 작게 어림했어요."],"variant_rule":{"alt":[{"stem":"축제장 놀이기구가 기울어진 각을 각도기로 재니 20°였어요. 어림을 잘못한 친구는 누구인가요?","options":[{"t":"준서 — 「약 160°쯤일 거야.」","correct":true,"mis_target":"M4-1-u2-X11"},{"t":"도윤 — 「약 20°쯤일 거야.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「직각보다 작게 어림했어.」","mis":"M4-1-u2-X19"}],"explanation":["20°는 직각보다 작아요.","약 20°처럼 가깝게 어림해야 해요.","준서는 직각과 견주지 않고 크게 어림했어요."],"asset":null},{"stem":"축제장 놀이기구가 기울어진 각을 각도기로 재니 105°였어요. 어림을 잘못한 친구는 누구인가요?","options":[{"t":"예린 — 「약 80°쯤일 거야.」","correct":true,"mis_target":"M4-1-u2-X11"},{"t":"나래 — 「약 100°쯤일 거야.」","mis":"M4-1-u2-X19"},{"t":"준서 — 「직각보다 크게 어림했어.」","mis":"M4-1-u2-X19"}],"explanation":["105°는 직각보다 커요.","약 100°처럼 가깝게 어림해야 해요.","예린은 직각과 견주지 않고 작게 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#6','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',3,'mc','auto','45°보다 크고 90°보다 작은 각이에요. 어림한 값으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u2-X11']::text[],true,'{"seq":6,"concept":"M4-1-u2-C6","difficulty":3,"kind":"mc","stem":"45°보다 크고 90°보다 작은 각이에요. 어림한 값으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"약 70°","correct":true},{"t":"약 25°","mis":"M4-1-u2-X11"},{"t":"약 110°","mis":"M4-1-u2-X11"},{"t":"약 120°","mis":"M4-1-u2-X11"}],"explanation":["두 기준 사이에 있는 값을 골라요.","45°와 90° 사이 — 약 70°.","답은 약 70°예요."],"variant_rule":{"alt":[{"stem":"90°보다 크고 135°보다 작은 각이에요. 어림한 값으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"약 110°","correct":true},{"t":"약 70°","mis":"M4-1-u2-X11"},{"t":"약 155°","mis":"M4-1-u2-X11"},{"t":"약 175°","mis":"M4-1-u2-X11"}],"explanation":["두 기준 사이에 있는 값을 골라요.","90°와 135° 사이 — 약 110°.","답은 약 110°예요."],"asset":null},{"stem":"135°보다 크고 180°보다 작은 각이에요. 어림한 값으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"약 160°","correct":true},{"t":"약 115°","mis":"M4-1-u2-X11"},{"t":"약 170°","mis":"M4-1-u2-X11"},{"t":"약 30°","mis":"M4-1-u2-X11"}],"explanation":["두 기준 사이에 있는 값을 골라요.","135°와 180° 사이 — 약 160°.","답은 약 160°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#7','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',3,'ox','auto','어림한 값과 잰 값의 차가 클수록 잘 어림한 거예요.',ARRAY['M4-1-u2-X12']::text[],true,'{"seq":7,"concept":"M4-1-u2-C6","difficulty":3,"kind":"ox","stem":"어림한 값과 잰 값의 차가 클수록 잘 어림한 거예요.","answer":"X","reason_options":[{"t":"차가 작을수록 잰 값에 가까워 잘한 어림이라서","correct":true},{"t":"많이 다를수록 용감한 어림이라서","mis":"M4-1-u2-X12"}],"mis":"M4-1-u2-X12","explanation":["잰 값과의 차를 구해요.","차가 작을수록 좋은 어림이에요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"어림한 값을 말할 때는 「약」을 붙여요.","answer":"O","reason_options":[{"t":"정확히 잰 값이 아니라서","correct":true},{"t":"각도기로 잰 값이라서","mis":"M4-1-u2-X12"}],"explanation":["어림은 짐작한 값이에요.","약 60°처럼 말해요.","그래서 맞아요."],"asset":null},{"stem":"각도는 아무 수나 마음대로 말해도 어림이에요.","answer":"X","reason_options":[{"t":"직각·45° 같은 기준과 견주어 짐작해야 해서","correct":true},{"t":"어림은 정답이 없어서","mis":"M4-1-u2-X11"}],"explanation":["기준 각과 견주어야 해요.","그래야 잰 값에 가까워져요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#8','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',4,'essay','teacher','각도기 없이 어떤 각을 약 몇 도인지 어림하려고 해요. 잘 어림하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u2-C6","difficulty":4,"kind":"essay","stem":"각도기 없이 어떤 각을 약 몇 도인지 어림하려고 해요. 잘 어림하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 먼저 삼각자의 직각을 대어 90°보다 큰지 작은지 본다. 그다음 45°(직각의 반)나 135° 같은 기준 각과 견주어 어디쯤인지 짐작하고 「약」을 붙여 말한다. 마지막에 각도기로 재어 확인한다.","scoring_points":["직각(90°)과 먼저 견준다고 했는가","45° 같은 다른 기준 각을 썼는가","「약」을 붙이거나 재어서 확인한다고 했는가"]},"explanation":["직각이 첫 기준이에요.","45°·135°로 더 촘촘히.","재어서 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#9','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',4,'essay','teacher','잰 값이 75°인 각을 서아는 약 70°, 준서는 약 90°로 어림했어요. 누가 더 잘 어림했는지 쓰고 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u2-C6","difficulty":4,"kind":"essay","stem":"잰 값이 75°인 각을 서아는 약 70°, 준서는 약 90°로 어림했어요. 누가 더 잘 어림했는지 쓰고 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 서아이다. 서아의 어림은 잰 값과 5° 차이, 준서는 15° 차이이므로 잰 값에 더 가까운 서아가 더 잘 어림했다.","scoring_points":["서아라고 답했는가","두 차이(5°·15°)를 구했는가","차가 작을수록 잘한 어림이라고 했는가"]},"explanation":["75 − 70 = 5.","90 − 75 = 15.","5 < 15 — 서아."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L05_challenge#10','math',4,1,'u2','L05','g4_1_math_u2_L05_challenge','lesson_challenge','M4-1-u2-C6',4,'sa','auto','어떤 각을 어림한 값이 잰 값보다 15° 작았어요. 잰 값이 125°라면 어림한 값은 약 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u2-C6","difficulty":4,"kind":"sa","stem":"어떤 각을 어림한 값이 잰 값보다 15° 작았어요. 잰 값이 125°라면 어림한 값은 약 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["어림한 값이 더 작으면 잰 값에서 빼요 — 125 − 15.","125 − 15 = 110.","어림한 값은 약 110°예요."],"variant_rule":{"alt":[{"stem":"어떤 각을 어림한 값이 잰 값보다 20° 컸어요. 잰 값이 80°라면 어림한 값은 약 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["어림한 값이 더 크면 잰 값에 더해요 — 80 + 20.","80 + 20 = 100.","어림한 값은 약 100°예요."],"asset":null},{"stem":"어떤 각을 어림한 값이 잰 값보다 25° 작았어요. 잰 값이 140°라면 어림한 값은 약 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["어림한 값이 더 작으면 잰 값에서 빼요 — 140 − 25.","140 − 25 = 115.","어림한 값은 약 115°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_basic#1','math',4,1,'u2','L06','g4_1_math_u2_L06_basic','lesson_basic','M4-1-u2-C7',1,'sa','auto','두 각도의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C7","difficulty":1,"kind":"sa","stem":"두 각도의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["각도의 합은 자연수의 덧셈처럼 계산해요.","60 + 30 = 90.","합은 90°예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,131.0],[131.0,131.0]],[[16.0,131.0],[73.5,31.407078565]],[[16.0,131.0],[16.0,16.0]]],"arc":[[[131.0,131.0],[16.0,131.0],[73.5,31.407078565]],[[73.5,31.407078565],[16.0,131.0],[16.0,16.0]]],"lab":[[[45.444863729,114.0],"60°"],[[31.0,75.019237886],"30°"]],"w":147,"h":147}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 각도의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["각도의 합은 자연수의 덧셈처럼 계산해요.","45 + 40 = 85.","합은 85°예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,130.562390281],[131.0,130.562390281]],[[16.0,130.562390281],[97.317279836,49.245110444]],[[16.0,130.562390281],[26.022910416,16.0]]],"arc":[[[131.0,130.562390281],[16.0,130.562390281],[97.317279836,49.245110444]],[[97.317279836,49.245110444],[16.0,130.562390281],[26.022910416,16.0]]],"lab":[[[52.213203436,115.562390281],"45°"],[[34.534796999,90.814389846],"40°"]],"w":147,"h":147}],"tag":false}},{"stem":"이번에는 다른 각이에요. 두 각도의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["각도의 합은 자연수의 덧셈처럼 계산해요.","70 + 50 = 120.","합은 120°예요."],"asset":{"type":"geo","items":[{"seg":[[[73.5,124.06465139],[188.5,124.06465139]],[[73.5,124.06465139],[112.832316482,16.0]],[[73.5,124.06465139],[16.0,24.471729955]]],"arc":[[[188.5,124.06465139],[73.5,124.06465139],[112.832316482,16.0]],[[112.832316482,16.0],[73.5,124.06465139],[16.0,24.471729955]]],"lab":[[[101.351169506,104.563052554],"70°"],[[70.406579153,88.706689314],"50°"]],"w":204,"