INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_basic#3','math',4,1,'u2','L06','g4_1_math_u2_L06_basic','lesson_basic','M4-1-u2-C7',1,'sa','auto','35° + 40°는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u2-C7","difficulty":1,"kind":"sa","stem":"35° + 40°는 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["각도의 합은 자연수의 덧셈처럼 계산해요.","35 + 40 = 75.","합은 75°예요."],"variant_rule":{"alt":[{"stem":"125° + 30°는 몇 도인가요? 숫자로 쓰세요.","answer":["155"],"explanation":["각도의 합은 자연수의 덧셈처럼 계산해요.","125 + 30 = 155.","합은 155°예요."],"asset":null},{"stem":"80° + 95°는 몇 도인가요? 숫자로 쓰세요.","answer":["175"],"explanation":["각도의 합은 자연수의 덧셈처럼 계산해요.","80 + 95 = 175.","합은 175°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_basic#4','math',4,1,'u2','L06','g4_1_math_u2_L06_basic','lesson_basic','M4-1-u2-C7',1,'sa','auto','160° − 75°는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u2-C7","difficulty":1,"kind":"sa","stem":"160° − 75°는 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["각도의 차는 자연수의 뺄셈처럼 계산해요.","160 − 75 = 85.","차는 85°예요."],"variant_rule":{"alt":[{"stem":"145° − 60°는 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["각도의 차는 자연수의 뺄셈처럼 계산해요.","145 − 60 = 85.","차는 85°예요."],"asset":null},{"stem":"110° − 25°는 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["각도의 차는 자연수의 뺄셈처럼 계산해요.","110 − 25 = 85.","차는 85°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
