INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_basic#6','math',4,1,'u2','L06','g4_1_math_u2_L06_basic','lesson_basic','M4-1-u2-C7',2,'sa','auto','태권도 공연단 이야기예요. 은비의 팔 각도는 60°예요. 여기서 30°만큼 더 벌리면 몇 도가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u2-C7","difficulty":2,"kind":"sa","stem":"태권도 공연단 이야기예요. 은비의 팔 각도는 60°예요. 여기서 30°만큼 더 벌리면 몇 도가 되나요? 숫자로 쓰세요.","answer":["90"],"explanation":["더 벌리면 합, 오므리거나 견주면 차예요.","60 + 30 = 90.","답은 90°예요."],"variant_rule":{"alt":[{"stem":"태권도 공연단 이야기예요. 사범님의 팔 각도는 145°, 은비는 100°예요. 은비는 몇 도만큼 더 벌려야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["더 벌리면 합, 오므리거나 견주면 차예요.","145 − 100 = 45.","답은 45°예요."],"asset":null},{"stem":"태권도 공연단 이야기예요. 은비가 팔을 130° 벌렸다가 45°만큼 오므렸어요. 지금 팔 각도는 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["더 벌리면 합, 오므리거나 견주면 차예요.","130 − 45 = 85.","답은 85°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_basic#7','math',4,1,'u2','L06','g4_1_math_u2_L06_basic','lesson_basic','M4-1-u2-C7',2,'mc','auto','85° + 45°를 바르게 계산한 것은 어느 것인가요?',ARRAY['M4-1-u2-X13']::text[],true,'{"seq":7,"concept":"M4-1-u2-C7","difficulty":2,"kind":"mc","stem":"85° + 45°를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"130°","correct":true},{"t":"40°","mis":"M4-1-u2-X13"},{"t":"140°","mis":"M4-1-u2-X13"},{"t":"120°","mis":"M4-1-u2-X13"}],"explanation":["합은 자연수처럼 계산하고 °를 붙여요.","85 + 45 = 130.","답은 130°예요."],"variant_rule":{"alt":[{"stem":"150° − 65°를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"85°","correct":true},{"t":"215°","mis":"M4-1-u2-X13"},{"t":"95°","mis":"M4-1-u2-X13"},{"t":"75°","mis":"M4-1-u2-X13"}],"explanation":["차는 자연수처럼 계산하고 °를 붙여요.","150 − 65 = 85.","답은 85°예요."],"asset":null},{"stem":"75° + 95°를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"170°","correct":true},{"t":"-20°","mis":"M4-1-u2-X13"},{"t":"180°","mis":"M4-1-u2-X13"},{"t":"160°","mis":"M4-1-u2-X13"}],"explanation":["합은 자연수처럼 계산하고 °를 붙여요.","75 + 95 = 170.","답은 170°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
