INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_basic#9','math',4,1,'u2','L06','g4_1_math_u2_L06_basic','lesson_basic','M4-1-u2-C7',2,'mc','auto','더해서 360°가 되는 것은 어느 것인가요?',ARRAY['M4-1-u2-X13']::text[],true,'{"seq":9,"concept":"M4-1-u2-C7","difficulty":2,"kind":"mc","stem":"더해서 360°가 되는 것은 어느 것인가요?","options":[{"t":"90° + 90° + 90° + 90°","correct":true},{"t":"120° + 120° + 100°","mis":"M4-1-u2-X13"},{"t":"180° + 90° + 45°","mis":"M4-1-u2-X13"},{"t":"90° + 90° + 90°","mis":"M4-1-u2-X13"}],"explanation":["하나씩 더해 360이 되는지 봐요.","90 + 90 + 90 + 90 = 360.","한 바퀴(360°)가 되는 것은 90° + 90° + 90° + 90°."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 더해서 360°가 되는 것은 어느 것인가요?","options":[{"t":"120° + 120° + 120°","correct":true},{"t":"90° + 90° + 90°","mis":"M4-1-u2-X13"},{"t":"60° + 60° + 60°","mis":"M4-1-u2-X14"},{"t":"180° + 90° + 45°","mis":"M4-1-u2-X13"}],"explanation":["하나씩 더해 360이 되는지 봐요.","120 + 120 + 120 = 360.","한 바퀴(360°)가 되는 것은 120° + 120° + 120°."],"asset":null},{"stem":"이번에는 다른 각이에요. 더해서 360°가 되는 것은 어느 것인가요?","options":[{"t":"100° + 80° + 180°","correct":true},{"t":"120° + 120° + 100°","mis":"M4-1-u2-X13"},{"t":"180° + 90° + 45°","mis":"M4-1-u2-X13"},{"t":"60° + 60° + 60°","mis":"M4-1-u2-X14"}],"explanation":["하나씩 더해 360이 되는지 봐요.","100 + 80 + 180 = 360.","한 바퀴(360°)가 되는 것은 100° + 80° + 180°."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
