INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_challenge#2','math',4,1,'u2','L06','g4_1_math_u2_L06_challenge','lesson_challenge','M4-1-u2-C7',2,'sa','auto','태권도 공연단 이야기예요. 사범님의 팔 각도는 75°예요. 은비는 사범님보다 35° 더 벌렸어요. 은비의 팔 각도는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u2-C7","difficulty":2,"kind":"sa","stem":"태권도 공연단 이야기예요. 사범님의 팔 각도는 75°예요. 은비는 사범님보다 35° 더 벌렸어요. 은비의 팔 각도는 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["더 벌리면 합, 오므리거나 견주면 차예요.","75 + 35 = 110.","답은 110°예요."],"variant_rule":{"alt":[{"stem":"태권도 공연단 이야기예요. 사범님은 팔을 120°, 은비는 95° 벌렸어요. 누가 몇 도 더 벌렸는지 구할 때 두 각도의 차는 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["더 벌리면 합, 오므리거나 견주면 차예요.","120 − 95 = 25.","답은 25°예요."],"asset":null},{"stem":"태권도 공연단 이야기예요. 사범님의 팔 각도는 145°, 은비는 100°예요. 은비는 몇 도만큼 더 벌려야 하나요? 숫자로 쓰세요.","answer":["45"],"explanation":["더 벌리면 합, 오므리거나 견주면 차예요.","145 − 100 = 45.","답은 45°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
