INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_challenge#5','math',4,1,'u2','L06','g4_1_math_u2_L06_challenge','lesson_challenge','M4-1-u2-C7',3,'mc','auto','더해서 360°가 되는 것은 어느 것인가요?',ARRAY['M4-1-u2-X13','M4-1-u2-X14']::text[],true,'{"seq":5,"concept":"M4-1-u2-C7","difficulty":3,"kind":"mc","stem":"더해서 360°가 되는 것은 어느 것인가요?","options":[{"t":"150° + 150° + 60°","correct":true},{"t":"120° + 120° + 100°","mis":"M4-1-u2-X13"},{"t":"100° + 80°","mis":"M4-1-u2-X14"},{"t":"90° + 90° + 90°","mis":"M4-1-u2-X13"}],"explanation":["하나씩 더해 360이 되는지 봐요.","150 + 150 + 60 = 360.","한 바퀴(360°)가 되는 것은 150° + 150° + 60°."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 더해서 360°가 되는 것은 어느 것인가요?","options":[{"t":"200° + 160°","correct":true},{"t":"180° + 90° + 45°","mis":"M4-1-u2-X13"},{"t":"100° + 80°","mis":"M4-1-u2-X14"},{"t":"60° + 60° + 60°","mis":"M4-1-u2-X14"}],"explanation":["하나씩 더해 360이 되는지 봐요.","200 + 160 = 360.","한 바퀴(360°)가 되는 것은 200° + 160°."],"asset":null},{"stem":"이번에는 다른 각이에요. 더해서 360°가 되는 것은 어느 것인가요?","options":[{"t":"45° + 135° + 180°","correct":true},{"t":"180° + 90° + 45°","mis":"M4-1-u2-X13"},{"t":"90° + 90° + 90°","mis":"M4-1-u2-X13"},{"t":"150° + 150° + 90°","mis":"M4-1-u2-X13"}],"explanation":["하나씩 더해 360이 되는지 봐요.","45 + 135 + 180 = 360.","한 바퀴(360°)가 되는 것은 45° + 135° + 180°."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_challenge#6','math',4,1,'u2','L06','g4_1_math_u2_L06_challenge','lesson_challenge','M4-1-u2-C7',3,'mc','auto','175° − 85°를 바르게 계산한 것은 어느 것인가요?',ARRAY['M4-1-u2-X13']::text[],true,'{"seq":6,"concept":"M4-1-u2-C7","difficulty":3,"kind":"mc","stem":"175° − 85°를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"90°","correct":true},{"t":"260°","mis":"M4-1-u2-X13"},{"t":"100°","mis":"M4-1-u2-X13"},{"t":"80°","mis":"M4-1-u2-X13"}],"explanation":["차는 자연수처럼 계산하고 °를 붙여요.","175 − 85 = 90.","답은 90°예요."],"variant_rule":{"alt":[{"stem":"65° + 85°를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"150°","correct":true},{"t":"-20°","mis":"M4-1-u2-X13"},{"t":"160°","mis":"M4-1-u2-X13"},{"t":"140°","mis":"M4-1-u2-X13"}],"explanation":["합은 자연수처럼 계산하고 °를 붙여요.","65 + 85 = 150.","답은 150°예요."],"asset":null},{"stem":"132° − 57°를 바르게 계산한 것은 어느 것인가요?","options":[{"t":"75°","correct":true},{"t":"189°","mis":"M4-1-u2-X13"},{"t":"85°","mis":"M4-1-u2-X13"},{"t":"65°","mis":"M4-1-u2-X13"}],"explanation":["차는 자연수처럼 계산하고 °를 붙여요.","132 − 57 = 75.","답은 75°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
