124.06465139]],[[131.0,124.06465139],[170.332316482,16.0]],[[131.0,124.06465139],[49.682720164,42.747371554]],[[131.0,124.06465139],[16.0,124.06465139]]],"arc":[[[246.0,124.06465139],[131.0,124.06465139],[170.332316482,16.0]],[[170.332316482,16.0],[131.0,124.06465139],[49.682720164,42.747371554]],[[49.682720164,42.747371554],[131.0,124.06465139],[16.0,124.06465139]]],"lab":[[[158.851169506,104.563052554],"70°"],[[123.641053126,90.870587148],"?"],[[94.786796564,109.06465139],"45°"]],"w":262,"h":140}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_challenge#8','math',4,1,'u2','L06','g4_1_math_u2_L06_challenge','lesson_challenge','M4-1-u2-C7',4,'essay','teacher','은비는 팔을 70° 벌렸다가 45°만큼 더 벌리고, 다시 30°만큼 오므렸어요. 지금 팔 각도는 몇 도인지 풀이 과정과 함께 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u2-C7","difficulty":4,"kind":"essay","stem":"은비는 팔을 70° 벌렸다가 45°만큼 더 벌리고, 다시 30°만큼 오므렸어요. 지금 팔 각도는 몇 도인지 풀이 과정과 함께 써 보세요.","answer_guide":{"answer":"예: 더 벌리면 합이므로 70° + 45° = 115°, 오므리면 차이므로 115° − 30° = 85°이다. 지금 팔 각도는 85°이다.","scoring_points":["70 + 45 = 115를 구했는가","115 − 30 = 85를 구했는가","85°라고 답했는가"]},"explanation":["벌리면 더해요.","오므리면 빼요.","85°."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_challenge#9','math',4,1,'u2','L06','g4_1_math_u2_L06_challenge','lesson_challenge','M4-1-u2-C7',4,'essay','teacher','한 점을 둘러싸 한 바퀴(360°)가 되도록 각을 이어 붙이는 방법을 두 가지 써 보세요(각은 세 개 이상).','{}'::text[],false,'{"seq":9,"concept":"M4-1-u2-C7","difficulty":4,"kind":"essay","stem":"한 점을 둘러싸 한 바퀴(360°)가 되도록 각을 이어 붙이는 방법을 두 가지 써 보세요(각은 세 개 이상).","answer_guide":{"answer":"예: ① 90° + 90° + 90° + 90° = 360° ② 120° + 120° + 120° = 360° (100° + 80° + 180°처럼 합이 360°면 된다)","scoring_points":["각을 세 개 이상 썼는가","두 방법 모두 합이 360°인가","덧셈식으로 확인했는가"]},"explanation":["한 바퀴는 360°예요.","각들을 더해 360이 되는지 확인해요.","여러 방법이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L06_challenge#10','math',4,1,'u2','L06','g4_1_math_u2_L06_challenge','lesson_challenge','M4-1-u2-C7',4,'sa','auto','한 점을 둘러싼 네 각 중 두 각이 100°, 80°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u2-C7","difficulty":4,"kind":"sa","stem":"한 점을 둘러싼 네 각 중 두 각이 100°, 80°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 100 − 80 = 180, 180 ÷ 2 = 90.","한 각은 90°예요."],"variant_rule":{"alt":[{"stem":"한 점을 둘러싼 네 각 중 두 각이 150°, 70°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 150 − 70 = 140, 140 ÷ 2 = 70.","한 각은 70°예요."],"asset":null},{"stem":"한 점을 둘러싼 네 각 중 두 각이 120°, 40°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 120 − 40 = 200, 200 ÷ 2 = 100.","한 각은 100°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_basic#1','math',4,1,'u2','L07','g4_1_math_u2_L07_basic','lesson_basic','M4-1-u2-C8',1,'sa','auto','삼각형의 세 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C8","difficulty":1,"kind":"sa","stem":"삼각형의 세 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["세 각을 모으면 일직선이에요.","어떤 모양이든 같아요.","답은 180°예요."],"variant_rule":{"alt":[{"stem":"삼각형의 세 각을 오려 한 점에 모으면 일직선이 돼요. 일직선은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["일직선은 한 바퀴의 반이에요.","어떤 모양이든 같아요.","답은 180°예요."],"asset":null},{"stem":"직각 2개의 합과 삼각형의 세 각의 크기의 합은 같아요. 그 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["90 + 90 = 180.","어떤 모양이든 같아요.","답은 180°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
