INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_basic#4','math',4,1,'u2','L07','g4_1_math_u2_L07_basic','lesson_basic','M4-1-u2-C8',1,'ox','auto','삼각형이 클수록 세 각의 크기의 합도 커져요.',ARRAY['M4-1-u2-X15']::text[],true,'{"seq":4,"concept":"M4-1-u2-C8","difficulty":1,"kind":"ox","stem":"삼각형이 클수록 세 각의 크기의 합도 커져요.","answer":"X","reason_options":[{"t":"크기와 상관없이 언제나 180°라서","correct":true},{"t":"변이 길면 각도 커져서","mis":"M4-1-u2-X15"}],"mis":"M4-1-u2-X15","explanation":["세 각을 모으면 언제나 일직선이에요.","큰 삼각형도 180°예요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"뾰족한 삼각형과 납작한 삼각형은 세 각의 크기의 합이 같아요.","answer":"O","reason_options":[{"t":"모양과 상관없이 언제나 180°라서","correct":true},{"t":"뾰족할수록 합이 작아서","mis":"M4-1-u2-X15"}],"explanation":["모양이 달라도 세 각의 합은 180°예요.","두 삼각형 모두 180°예요.","그래서 맞아요."],"asset":null},{"stem":"한 삼각형에 둔각이 두 개 있을 수 있어요.","answer":"X","reason_options":[{"t":"둔각 두 개만 더해도 180°를 넘어서","correct":true},{"t":"각이 세 개라 둘은 둔각일 수 있어서","mis":"M4-1-u2-X15"}],"explanation":["둔각은 90°보다 커요.","둘만 더해도 180°보다 커져요.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
