INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_basic#6','math',4,1,'u2','L07','g4_1_math_u2_L07_basic','lesson_basic','M4-1-u2-C8',2,'mc','auto','삼각형의 두 각이 70°, 50°예요. 나머지 한 각은 몇 도인가요?',ARRAY['M4-1-u2-X15','M4-1-u2-X17']::text[],true,'{"seq":6,"concept":"M4-1-u2-C8","difficulty":2,"kind":"mc","stem":"삼각형의 두 각이 70°, 50°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"60°","correct":true},{"t":"240°","mis":"M4-1-u2-X15"},{"t":"110°","mis":"M4-1-u2-X17"},{"t":"120°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 70 − 50 = 60.","나머지 한 각은 60°예요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 35°, 50°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"95°","correct":true},{"t":"275°","mis":"M4-1-u2-X15"},{"t":"145°","mis":"M4-1-u2-X17"},{"t":"85°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 35 − 50 = 95.","나머지 한 각은 95°예요."],"asset":null},{"stem":"삼각형의 두 각이 20°, 80°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"80°","correct":true},{"t":"260°","mis":"M4-1-u2-X15"},{"t":"160°","mis":"M4-1-u2-X17"},{"t":"100°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 20 − 80 = 80.","나머지 한 각은 80°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_basic#7','math',4,1,'u2','L07','g4_1_math_u2_L07_basic','lesson_basic','M4-1-u2-C8',2,'sa','auto','세 각의 크기가 모두 같은 삼각형이에요. 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u2-C8","difficulty":2,"kind":"sa","stem":"세 각의 크기가 모두 같은 삼각형이에요. 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["세 각의 합은 180°예요.","180 ÷ 3 = 60.","한 각은 60°예요."],"variant_rule":{"alt":[{"stem":"두 각의 크기가 같은 삼각형에서 다른 한 각이 40°예요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["세 각의 합은 180°예요.","(180 − 40) ÷ 2 = 70.","한 각은 70°예요."],"asset":null},{"stem":"두 각의 크기가 같은 삼각형에서 다른 한 각이 100°예요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["세 각의 합은 180°예요.","(180 − 100) ÷ 2 = 40.","한 각은 40°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_basic#8','math',4,1,'u2','L07','g4_1_math_u2_L07_basic','lesson_basic','M4-1-u2-C8',2,'sa','auto','종이 삼각형의 세 각을 오려 한 점에 모았더니 일직선이 되었어요. 가려진 각(?)은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u2-C8","difficulty":2,"kind":"sa","stem":"종이 삼각형의 세 각을 오려 한 점에 모았더니 일직선이 되었어요. 가려진 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["세 각을 모으면 일직선 — 180°.","180 − 50 − 70 = 60.","?는 60°예요."],"asset":{"type":"geo","items":[{"seg":[[[131.0,124.06465139],[246.0,124.06465139]],[[131.0,124.06465139],[204.920575114,35.969540432]],[[131.0,124.06465139],[91.667683518,16.0]],[[131.0,124.06465139],[16.0,124.06465139]]],"arc":[[[246.0,124.06465139],[131.0,124.06465139],[204.920575114,35.969540432]],[[204.920575114,35.969540432],[131.0,124.06465139],[91.667683518,16.0]],[[91.667683518,16.0],[131.0,124.06465139],[16.0,124.06465139]]],"lab":[[[163.167603808,109.06465139],"50°"],[[136.904038041,90.581187788],"?"],[[103.148830494,104.563052554],"70°"]],"w":262,"h":140}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 종이 삼각형의 세 각을 오려 한 점에 모았더니 일직선이 되었어요. 가려진 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["세 각을 모으면 일직선 — 180°.","180 − 40 − 85 = 55.","?는 55°예요."],"asset":{"type":"geo","items":[{"seg":[[[131.0,130.562390281],[246.0,130.562390281]],[[131.0,130.562390281],[219.095110959,56.641815167]],[[131.0,130.562390281],[120.977089584,16.0]],[[131.0,130.562390281],[16.0,130.562390281]]],"arc":[[[246.0,130.562390281],[131.0,130.562390281],[219.095110959,56.641815167]],[[219.095110959,56.641815167],[131.0,130.562390281],[120.977089584,16.0]],[[120.977089584,16.0],[131.0,130.562390281],[16.0,130.562390281]]],"lab":[[[172.212161292,115.562390281],"40°"],[[144.0112367,99.150486175],"?"],[[105.932570548,107.592323222],"85°"]],"w":262,"h":147}],"tag":false}},{"stem":"이번에는 다른 각이에요. 종이 삼각형의 세 각을 오려 한 점에 모았더니 일직선이 되었어요. 가려진 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["세 각을 모으면 일직선 — 180°.","180 − 65 − 35 = 80.","?는 80°예요."],"asset":{"type":"geo","items":[{"seg":[[[131.0,120.225395509],[246.0,120.225395509]],[[131.0,120.225395509],[179.6011001,16.0]],[[131.0,120.225395509],[36.797514907,54.264105329]],[[131.0,120.225395509],[16.0,120.225395509]]],"arc":[[[246.0,120.225395509],[131.0,120.225395509],[179.6011001,16.0]],[[179.6011001,16.0],[131.0,120.225395509],[36.797514907,54.264105329]],[[36.797514907,54.264105329],[131.0,120.225395509],[16.0,120.225395509]]],"lab":[[[159.675309158,101.957208825],"65°"],[[122.200152467,87.383917415],"?"],[[83.426077965,105.225395509],"35°"]],"w":262,"h":136}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_basic#9','math',4,1,'u2','L07','g4_1_math_u2_L07_basic','lesson_basic','M4-1-u2-C8',2,'mc','auto','삼각형의 세 각의 크기가 될 수 있는 것은 어느 것인가요?',ARRAY['M4-1-u2-X15']::text[],true,'{"seq":9,"concept":"M4-1-u2-C8","difficulty":2,"kind":"mc","stem":"삼각형의 세 각의 크기가 될 수 있는 것은 어느 것인가요?","options":[{"t":"50°, 60°, 70°","correct":true},{"t":"100°, 50°, 40°","mis":"M4-1-u2-X15"},{"t":"120°, 30°, 50°","mis":"M4-1-u2-X15"},{"t":"90°, 90°, 30°","mis":"M4-1-u2-X15"}],"explanation":["세 각을 더해 180°가 되는지 봐요.","50 + 60 + 70 = 180.","세 각이 될 수 있는 것은 50°, 60°, 70°."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 삼각형의 세 각의 크기가 될 수 있는 것은 어느 것인가요?","options":[{"t":"90°, 45°, 45°","correct":true},{"t":"90°, 90°, 30°","mis":"M4-1-u2-X15"},{"t":"90°, 60°, 40°","mis":"M4-1-u2-X15"},{"t":"70°, 70°, 70°","mis":"M4-1-u2-X15"}],"explanation":["세 각을 더해 180°가 되는지 봐요.","90 + 45 + 45 = 180.","세 각이 될 수 있는 것은 90°, 45°, 45°."],"asset":null},{"stem":"이번에는 다른 각이에요. 삼각형의 세 각의 크기가 될 수 있는 것은 어느 것인가요?","options":[{"t":"30°, 30°, 120°","correct":true},{"t":"45°, 45°, 45°","mis":"M4-1-u2-X15"},{"t":"120°, 30°, 50°","mis":"M4-1-u2-X15"},{"t":"70°, 70°, 70°","mis":"M4-1-u2-X15"}],"explanation":["세 각을 더해 180°가 되는지 봐요.","30 + 30 + 120 = 180.","세 각이 될 수 있는 것은 30°, 30°, 120°."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_basic#10','math',4,1,'u2','L07','g4_1_math_u2_L07_basic','lesson_basic','M4-1-u2-C8',3,'error','auto','삼각형의 두 각이 55°, 75°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X15','M4-1-u2-X19']::text[],true,'{"seq":10,"concept":"M4-1-u2-C8","difficulty":3,"kind":"error","stem":"삼각형의 두 각이 55°, 75°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「360 − 55 − 75 = 230°예요.」","correct":true,"mis_target":"M4-1-u2-X15"},{"t":"준서 — 「180 − 55 − 75 = 50°예요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「180 − 55 = 125, 125 − 75 = 50°예요.」","mis":"M4-1-u2-X19"}],"explanation":["삼각형의 세 각의 합은 180°예요.","180 − 55 − 75 = 50.","도윤은 360°에서 빼서 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 30°, 95°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「360 − 30 − 95 = 235°예요.」","correct":true,"mis_target":"M4-1-u2-X15"},{"t":"도윤 — 「180 − 30 − 95 = 55°예요.」","mis":"M4-1-u2-X19"},{"t":"하람 — 「180 − 30 = 150, 150 − 95 = 55°예요.」","mis":"M4-1-u2-X19"}],"explanation":["삼각형의 세 각의 합은 180°예요.","180 − 30 − 95 = 55.","예린은 360°에서 빼서 잘못 말했어요."],"asset":null},{"stem":"삼각형의 두 각이 40°, 40°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「360 − 40 − 40 = 280°예요.」","correct":true,"mis_target":"M4-1-u2-X15"},{"t":"예린 — 「180 − 40 − 40 = 100°예요.」","mis":"M4-1-u2-X19"},{"t":"나래 — 「180 − 40 = 140, 140 − 40 = 100°예요.」","mis":"M4-1-u2-X19"}],"explanation":["삼각형의 세 각의 합은 180°예요.","180 − 40 − 40 = 100.","은비는 360°에서 빼서 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
