INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_challenge#3','math',4,1,'u2','L07','g4_1_math_u2_L07_challenge','lesson_challenge','M4-1-u2-C8',3,'sa','auto','삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u2-C8","difficulty":3,"kind":"sa","stem":"삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["삼각형의 나머지 한 각: 180 − 50 − 60 = 70.","그 각과 ?가 일직선을 이루어요: 180 − 70 = 110.","?는 110°예요 (= 50 + 60)."],"asset":{"type":"geo","items":[{"poly":[[[16.0,217.819853783],[216.0,217.819853783],[134.47925309,76.621778265]]],"seg":[[[134.47925309,76.621778265],[99.47925309,16.0]]],"arc":[[[99.47925309,16.0],[134.47925309,76.621778265],[16.0,217.819853783]]],"lab":[[[74.00369837,190.772285032],"50°"],[[170.966679003,191.819853783],"60°"],[[92.639075771,72.96123707],"?"]],"w":232,"h":234}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["삼각형의 나머지 한 각: 180 − 40 − 75 = 65.","그 각과 ?가 일직선을 이루어요: 180 − 65 = 115.","?는 115°예요 (= 40 + 75)."],"asset":{"type":"geo","items":[{"poly":[[[16.0,220.62900145],[216.0,220.62900145],[179.287157471,83.61480784]]],"seg":[[[179.287157471,83.61480784],[161.169824314,16.0]]],"arc":[[[161.169824314,16.0],[179.287157471,83.61480784],[16.0,220.62900145]]],"lab":[[[76.14032773,198.739712277],"40°"],[[174.745626305,188.973407141],"75°"],[[139.231045539,70.985164261],"?"]],"w":232,"h":237}],"tag":false}},{"stem":"이번에는 다른 각이에요. 삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["삼각형의 나머지 한 각: 180 − 30 − 45 = 105.","그 각과 ?가 일직선을 이루어요: 180 − 105 = 75.","?는 75°예요 (= 30 + 45)."],"asset":{"type":"geo","items":[{"poly":[[[16.0,138.70255544],[216.0,138.70255544],[142.794919243,65.497474683]]],"seg":[[[142.794919243,65.497474683],[93.29744456,16.0]]],"arc":[[[93.297444