INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_challenge#5','math',4,1,'u2','L07','g4_1_math_u2_L07_challenge','lesson_challenge','M4-1-u2-C8',3,'error','auto','삼각형의 두 각이 65°, 85°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X15','M4-1-u2-X19']::text[],true,'{"seq":5,"concept":"M4-1-u2-C8","difficulty":3,"kind":"error","stem":"삼각형의 두 각이 65°, 85°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「360 − 65 − 85 = 210°예요.」","correct":true,"mis_target":"M4-1-u2-X15"},{"t":"준서 — 「180 − 65 − 85 = 30°예요.」","mis":"M4-1-u2-X19"},{"t":"예린 — 「180 − 65 = 115, 115 − 85 = 30°예요.」","mis":"M4-1-u2-X19"}],"explanation":["삼각형의 세 각의 합은 180°예요.","180 − 65 − 85 = 30.","지호는 360°에서 빼서 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 110°, 20°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「360 − 110 − 20 = 230°예요.」","correct":true,"mis_target":"M4-1-u2-X15"},{"t":"도윤 — 「180 − 110 − 20 = 50°예요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「180 − 110 = 70, 70 − 20 = 50°예요.」","mis":"M4-1-u2-X19"}],"explanation":["삼각형의 세 각의 합은 180°예요.","180 − 110 − 20 = 50.","준서는 360°에서 빼서 잘못 말했어요."],"asset":null},{"stem":"삼각형의 두 각이 35°, 60°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「360 − 35 − 60 = 265°예요.」","correct":true,"mis_target":"M4-1-u2-X15"},{"t":"나래 — 「180 − 35 − 60 = 85°예요.」","mis":"M4-1-u2-X19"},{"t":"준서 — 「180 − 35 = 145, 145 − 60 = 85°예요.」","mis":"M4-1-u2-X19"}],"explanation":["삼각형의 세 각의 합은 180°예요.","180 − 35 − 60 = 85.","예린은 360°에서 빼서 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_challenge#6','math',4,1,'u2','L07','g4_1_math_u2_L07_challenge','lesson_challenge','M4-1-u2-C8',3,'ox','auto','한 삼각형에 둔각이 두 개 있을 수 있어요.',ARRAY['M4-1-u2-X15']::text[],true,'{"seq":6,"concept":"M4-1-u2-C8","difficulty":3,"kind":"ox","stem":"한 삼각형에 둔각이 두 개 있을 수 있어요.","answer":"X","reason_options":[{"t":"둔각 두 개만 더해도 180°를 넘어서","correct":true},{"t":"각이 세 개라 둘은 둔각일 수 있어서","mis":"M4-1-u2-X15"}],"mis":"M4-1-u2-X15","explanation":["둔각은 90°보다 커요.","둘만 더해도 180°보다 커져요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"삼각형이 클수록 세 각의 크기의 합도 커져요.","answer":"X","reason_options":[{"t":"크기와 상관없이 언제나 180°라서","correct":true},{"t":"변이 길면 각도 커져서","mis":"M4-1-u2-X15"}],"explanation":["세 각을 모으면 언제나 일직선이에요.","큰 삼각형도 180°예요.","그래서 틀렸어요."],"asset":null},{"stem":"뾰족한 삼각형과 납작한 삼각형은 세 각의 크기의 합이 같아요.","answer":"O","reason_options":[{"t":"모양과 상관없이 언제나 180°라서","correct":true},{"t":"뾰족할수록 합이 작아서","mis":"M4-1-u2-X15"}],"explanation":["모양이 달라도 세 각의 합은 180°예요.","두 삼각형 모두 180°예요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_challenge#7','math',4,1,'u2','L07','g4_1_math_u2_L07_challenge','lesson_challenge','M4-1-u2-C8',3,'mc','auto','삼각형의 두 각이 45°, 105°예요. 나머지 한 각은 몇 도인가요?',ARRAY['M4-1-u2-X15','M4-1-u2-X17']::text[],true,'{"seq":7,"concept":"M4-1-u2-C8","difficulty":3,"kind":"mc","stem":"삼각형의 두 각이 45°, 105°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"30°","correct":true},{"t":"210°","mis":"M4-1-u2-X15"},{"t":"135°","mis":"M4-1-u2-X17"},{"t":"150°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 45 − 105 = 30.","나머지 한 각은 30°예요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 25°, 130°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"25°","correct":true},{"t":"205°","mis":"M4-1-u2-X15"},{"t":"155°","mis":"M4-1-u2-X17"},{"t":"35°","mis":"M4-1-u2-X13"}],"explanation":["세 각의 합은 180°예요.","180 − 25 − 130 = 25.","나머지 한 각은 25°예요."],"asset":null},{"stem":"삼각형의 두 각이 85°, 35°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"60°","correct":true},{"t":"240°","mis":"M4-1-u2-X15"},{"t":"95°","mis":"M4-1-u2-X17"},{"t":"120°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 85 − 35 = 60.","나머지 한 각은 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_challenge#8','math',4,1,'u2','L07','g4_1_math_u2_L07_challenge','lesson_challenge','M4-1-u2-C8',4,'essay','teacher','종이로 삼각형을 오려 세 각을 한 점에 모았어요. 어떤 모양이 되는지 쓰고, 이를 보고 삼각형의 세 각의 크기의 합이 몇 도인지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u2-C8","difficulty":4,"kind":"essay","stem":"종이로 삼각형을 오려 세 각을 한 점에 모았어요. 어떤 모양이 되는지 쓰고, 이를 보고 삼각형의 세 각의 크기의 합이 몇 도인지 설명해 보세요.","answer_guide":{"answer":"예: 세 각이 빈틈없이 이어져 일직선이 된다. 일직선은 180°이므로 삼각형의 세 각의 크기의 합은 180°이고, 모양이 다른 삼각형도 똑같다.","scoring_points":["일직선이 된다고 했는가","일직선이 180°라고 했는가","세 각의 합이 180°라고 답했는가"]},"explanation":["세 각을 모으면 일직선.","일직선 = 180°.","세 각의 합 = 180°."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_challenge#9','math',4,1,'u2','L07','g4_1_math_u2_L07_challenge','lesson_challenge','M4-1-u2-C8',4,'essay','teacher','한 삼각형에 둔각이 두 개 있을 수 있는지 쓰고, 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u2-C8","difficulty":4,"kind":"essay","stem":"한 삼각형에 둔각이 두 개 있을 수 있는지 쓰고, 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 있을 수 없다. 둔각은 90°보다 크므로 둔각 두 개만 더해도 180°보다 커진다. 삼각형의 세 각의 합은 180°이므로 둔각은 하나까지만 있을 수 있다.","scoring_points":["있을 수 없다고 답했는가","둔각 두 개의 합이 180°보다 크다고 했는가","세 각의 합이 180°임을 썼는가"]},"explanation":["둔각 > 90°.","둔각 + 둔각 > 180°.","그래서 둔각은 하나까지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L07_challenge#10','math',4,1,'u2','L07','g4_1_math_u2_L07_challenge','lesson_challenge','M4-1-u2-C8',4,'sa','auto','삼각형의 한 각이 60°예요. 나머지 두 각 중 한 각은 다른 한 각의 2배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u2-C8","difficulty":4,"kind":"sa","stem":"삼각형의 한 각이 60°예요. 나머지 두 각 중 한 각은 다른 한 각의 2배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나머지 두 각의 합: 180 − 60 = 120.","작은 각을 3묶음으로 보면 120 ÷ 3 = 40.","더 작은 각은 40°예요 (큰 각 80°)."],"variant_rule":{"alt":[{"stem":"삼각형의 한 각이 20°예요. 나머지 두 각 중 한 각은 다른 한 각의 3배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나머지 두 각의 합: 180 − 20 = 160.","작은 각을 4묶음으로 보면 160 ÷ 4 = 40.","더 작은 각은 40°예요 (큰 각 120°)."],"asset":null},{"stem":"삼각형의 한 각이 90°예요. 나머지 두 각 중 한 각은 다른 한 각의 2배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["나머지 두 각의 합: 180 − 90 = 90.","작은 각을 3묶음으로 보면 90 ÷ 3 = 30.","더 작은 각은 30°예요 (큰 각 60°)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_basic#1','math',4,1,'u2','L08','g4_1_math_u2_L08_basic','lesson_basic','M4-1-u2-C9',1,'sa','auto','사각형의 네 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C9","difficulty":1,"kind":"sa","stem":"사각형의 네 각의 크기의 합은 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["대각선으로 삼각형 2개 — 180 + 180.","어떤 모양이든 같아요.","답은 360°예요."],"variant_rule":{"alt":[{"stem":"사각형의 네 각을 오려 한 점에 모으면 한 바퀴가 돼요. 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["한 바퀴는 360°예요.","어떤 모양이든 같아요.","답은 360°예요."],"asset":null},{"stem":"사각형을 대각선으로 나눈 삼각형 2개의 각의 크기를 모두 더하면 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["180 × 2 = 360.","어떤 모양이든 같아요.","답은 360°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_basic#2','math',4,1,'u2','L08','g4_1_math_u2_L08_basic','lesson_basic','M4-1-u2-C9',1,'sa','auto','사각형에서 ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u2-C9","difficulty":1,"kind":"sa","stem":"사각형에서 ?는 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","360 − 80 − 100 − 80 = 100.","?는 100°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,204.797417015],[207.709921492,204.797417015],[241.0,16.0],[49.290078508,16.0]]],"arc":[[[49.290078508,16.0],[16.0,204.797417015],[207.709921492,204.797417015]],[[16.0,204.797417015],[207.709921492,204.797417015],[241.0,16.0]],[[207.709921492,204.797417015],[241.0,16.0],[49.290078508,16.0]],[[241.0,16.0],[49.290078508,16.0],[16.0,204.797417015]]],"lab":[[[55.834311042,171.372461311],"80°"],[[181.998417105,174.15563929],"100°"],[[201.165688958,49.424955704],"80°"],[[75.001582895,46.641777725],"?"]],"w":257,"h":221}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 사각형에서 ?는 몇 도인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","360 − 70 − 110 − 85 = 95.","?는 95°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,215.484828192],[194.257999622,215.484828192],[241.0,87.062237614],[88.60653965,16.0]]],"arc":[[[88.60653965,16.0],[16.0,215.484828192],[194.257999622,215.484828192]],[[16.0,215.484828192],[194.257999622,215.484828192],[241.0,87.062237614]],[[194.257999622,215.484828192],[241.0,87.062237614],[88.60653965,16.0]],[[241.0,87.062237614],[88.60653965,16.0],[16.0,215.484828192]]],"lab":[[[58.595906303,185.658853502],"70°"],[[171.314942168,182.718746421],"110°"],[[192.958264309,106.961776097],"?"],[[108.506078133,64.041735691],"85°"]],"w":257,"h":231}],"tag":false}},{"stem":"이번에는 다른 각이에요. 사각형에서 ?는 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["사각