INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_basic#3','math',4,1,'u2','L08','g4_1_math_u2_L08_basic','lesson_basic','M4-1-u2-C9',1,'sa','auto','네 각의 크기가 모두 같은 사각형이에요. 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u2-C9","difficulty":1,"kind":"sa","stem":"네 각의 크기가 모두 같은 사각형이에요. 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["네 각의 합은 360°예요.","360 ÷ 4 = 90.","답은 90°예요."],"variant_rule":{"alt":[{"stem":"두 각이 직각인 사각형에서 다른 한 각이 110°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["네 각의 합은 360°예요.","360 − 90 − 90 − 110 = 70.","답은 70°예요."],"asset":null},{"stem":"두 각이 직각인 사각형에서 다른 한 각이 65°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["네 각의 합은 360°예요.","360 − 90 − 90 − 65 = 115.","답은 115°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
