INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_basic#9','math',4,1,'u2','L08','g4_1_math_u2_L08_basic','lesson_basic','M4-1-u2-C9',2,'ox','auto','사각형의 네 각의 크기의 합은 180°예요.',ARRAY['M4-1-u2-X16']::text[],true,'{"seq":9,"concept":"M4-1-u2-C9","difficulty":2,"kind":"ox","stem":"사각형의 네 각의 크기의 합은 180°예요.","answer":"X","reason_options":[{"t":"삼각형 2개로 나뉘어 360°라서","correct":true},{"t":"각이 많아도 일직선이 되어서","mis":"M4-1-u2-X16"}],"mis":"M4-1-u2-X16","explanation":["대각선으로 나누면 삼각형이 2개예요.","180° + 180° = 360°.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"직사각형이 아닌 사각형도 네 각의 크기의 합은 360°예요.","answer":"O","reason_options":[{"t":"어떤 사각형이든 삼각형 2개로 나뉘어서","correct":true},{"t":"직사각형만 직각이 4개라 360°라서","mis":"M4-1-u2-X16"}],"explanation":["모든 사각형은 대각선으로 삼각형 2개.","그래서 언제나 360°.","그래서 맞아요."],"asset":null},{"stem":"사각형의 세 각을 알면 나머지 한 각은 360°에서 세 각을 모두 빼서 구해요.","answer":"O","reason_options":[{"t":"네 각의 합이 360°라서","correct":true},{"t":"세 각 중 한 각만 빼면 되어서","mis":"M4-1-u2-X17"}],"explanation":["360°에서 아는 각을 모두 빼요.","빠뜨리면 틀려요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_basic#10','math',4,1,'u2','L08','g4_1_math_u2_L08_basic','lesson_basic','M4-1-u2-C9',3,'error','auto','사각형의 세 각이 85°, 95°, 70°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X17','M4-1-u2-X19']::text[],true,'{"seq":10,"concept":"M4-1-u2-C9","difficulty":3,"kind":"error","stem":"사각형의 세 각이 85°, 95°, 70°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「85 + 95 + 70 = 250°예요.」","correct":true,"mis_target":"M4-1-u2-X17"},{"t":"준서 — 「360 − 85 − 95 − 70 = 110°예요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「네 각의 합 360°에서 세 각을 모두 빼요.」","mis":"M4-1-u2-X19"}],"explanation":["사각형의 네 각의 합은 360°예요.","360 − 85 − 95 − 70 = 110.","도윤은 세 각의 합을 그대로 답했어요."],"variant_rule":{"alt":[{"stem":"사각형의 세 각이 120°, 60°, 100°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「120 + 60 + 100 = 280°예요.」","correct":true,"mis_target":"M4-1-u2-X17"},{"t":"도윤 — 「360 − 120 − 60 − 100 = 80°예요.」","mis":"M4-1-u2-X19"},{"t":"하람 — 「네 각의 합 360°에서 세 각을 모두 빼요.」","mis":"M4-1-u2-X19"}],"explanation":["사각형의 네 각의 합은 360°예요.","360 − 120 − 60 − 100 = 80.","예린은 세 각의 합을 그대로 답했어요."],"asset":null},{"stem":"사각형의 세 각이 90°, 75°, 105°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「90 + 75 + 105 = 270°예요.」","correct":true,"mis_target":"M4-1-u2-X17"},{"t":"예린 — 「360 − 90 − 75 − 105 = 90°예요.」","mis":"M4-1-u2-X19"},{"t":"나래 — 「네 각의 합 360°에서 세 각을 모두 빼요.」","mis":"M4-1-u2-X19"}],"explanation":["사각형의 네 각의 합은 360°예요.","360 − 90 − 75 − 105 = 90.","은비는 세 각의 합을 그대로 답했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
