INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_challenge#4','math',4,1,'u2','L08','g4_1_math_u2_L08_challenge','lesson_challenge','M4-1-u2-C9',3,'sa','auto','사각형에서 ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u2-C9","difficulty":3,"kind":"sa","stem":"사각형에서 ?는 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","360 − 135 − 110 − 70 = 45.","?는 45°예요."],"asset":{"type":"geo","items":[{"poly":[[[87.694667372,136.44804477],[241.0,136.44804477],[120.55195523,16.0],[16.0,64.753377399]]],"arc":[[[16.0,64.753377399],[87.694667372,136.44804477],[241.0,136.44804477]],[[87.694667372,136.44804477],[241.0,136.44804477],[120.55195523,16.0]],[[241.0,136.44804477],[120.55195523,16.0],[16.0,64.753377399]],[[120.55195523,16.0],[16.0,64.753377399],[87.694667372,136.44804477]]],"lab":[[[103.002004666,99.49286347],"135°"],[[181.871709919,111.956305099],"?"],[[113.606028123,55.39231012],"110°"],[[67.210003157,73.783082637],"70°"]],"w":257,"h":152}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 사각형에서 ?는 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","360 − 140 − 85 − 95 = 40.","?는 40°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,142.51360818],[178.687190771,142.51360818],[241.0,90.226952939],[166.773047061,16.0]]],"arc":[[[166.773047061,16.0],[16.0,142.51360818],[178.687190771,142.51360818]],[[16.0,142.51360818],[178.687190771,142.51360818],[241.0,90.226952939]],[[178.687190771,142.51360818],[241.0,90.226952939],[166.773047061,16.0]],[[241.0,90.226952939],[166.773047061,16.0],[16.0,142.51360818]]],"lab":[[[76.14032773,120.624319007],"?"],[[165.006385038,104.925903349],"140°"],[[189.049492478,87.958744796],"85°"],[[164.504838918,67.950507522],"95°"]],"w":257,"h":159}],"tag":false}},{"stem":"이번에는 다른 각이에요. 사각형에서 ?는 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["사각형의 네 각의 크기의 합은 360°예요.","360 − 125 − 55 − 60 = 120.","?는 120°예요."],"asset":{"type":"geo","items":[{"poly":[[[78.426597689,241.0],[236.892529884,241.0],[79.345833787,16.0],[16.0,151.845578942]]],"arc":[[[16.0,151.845578942],[78.426597689,241.0],[236.892529884,241.0]],[[78.426597689,241.0],[236.892529884,241.0],[79.345833787,16.0]],[[236.892529884,241.0],[79.345833787,16.0],[16.0,151.845578942]],[[79.345833787,16.0],[16.0,151.845578942],[78.426597689,241.0]]],"lab":[[[96.896542219,205.519566673],"125°"],[[180.123836561,211.448088753],"55°"],[[83.87793241,67.802124301],"60°"],[[55.847787924,148.359349232],"?"]],"w":253,"h":257}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_challenge#5','math',4,1,'u2','L08','g4_1_math_u2_L08_challenge','lesson_challenge','M4-1-u2-C9',3,'error','auto','사각형의 세 각이 65°, 125°, 80°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X17','M4-1-u2-X19']::text[],true,'{"seq":5,"concept":"M4-1-u2-C9","difficulty":3,"kind":"error","stem":"사각형의 세 각이 65°, 125°, 80°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「65 + 125 + 80 = 270°예요.」","correct":true,"mis_target":"M4-1-u2-X17"},{"t":"준서 — 「360 − 65 − 125 − 80 = 90°예요.」","mis":"M4-1-u2-X19"},{"t":"예린 — 「네 각의 합 360°에서 세 각을 모두 빼요.」","mis":"M4-1-u2-X19"}],"explanation":["사각형의 네 각의 합은 360°예요.","360 − 65 − 125 − 80 = 90.","지호는 세 각의 합을 그대로 답했어요."],"variant_rule":{"alt":[{"stem":"사각형의 세 각이 110°, 110°, 70°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「110 + 110 + 70 = 290°예요.」","correct":true,"mis_target":"M4-1-u2-X17"},{"t":"도윤 — 「360 − 110 − 110 − 70 = 70°예요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「네 각의 합 360°에서 세 각을 모두 빼요.」","mis":"M4-1-u2-X19"}],"explanation":["사각형의 네 각의 합은 360°예요.","360 − 110 − 110 − 70 = 70.","준서는 세 각의 합을 그대로 답했어요."],"asset":null},{"stem":"사각형의 세 각이 55°, 95°, 130°일 때 나머지 한 각을 구한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「55 + 95 + 130 = 280°예요.」","correct":true,"mis_target":"M4-1-u2-X17"},{"t":"나래 — 「360 − 55 − 95 − 130 = 80°예요.」","mis":"M4-1-u2-X19"},{"t":"준서 — 「네 각의 합 360°에서 세 각을 모두 빼요.」","mis":"M4-1-u2-X19"}],"explanation":["사각형의 네 각의 합은 360°예요.","360 − 55 − 95 − 130 = 80.","예린은 세 각의 합을 그대로 답했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_challenge#6','math',4,1,'u2','L08','g4_1_math_u2_L08_challenge','lesson_challenge','M4-1-u2-C9',3,'sa','auto','마주 보는 각끼리 크기가 같은 사각형에서 한 각이 70°예요. 그 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u2-C9","difficulty":3,"kind":"sa","stem":"마주 보는 각끼리 크기가 같은 사각형에서 한 각이 70°예요. 그 각과 이웃한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["네 각의 합은 360°예요.","두 쌍의 합이 360° — 70 + □ = 180, □ = 110.","답은 110°예요."],"variant_rule":{"alt":[{"stem":"두 각이 직각인 사각형에서 다른 한 각이 110°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["네 각의 합은 360°예요.","360 − 90 − 90 − 110 = 70.","답은 70°예요."],"asset":null},{"stem":"두 각이 직각인 사각형에서 다른 한 각이 65°예요. 나머지 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["네 각의 합은 360°예요.","360 − 90 − 90 − 65 = 115.","답은 115°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_challenge#7','math',4,1,'u2','L08','g4_1_math_u2_L08_challenge','lesson_challenge','M4-1-u2-C9',3,'sa','auto','사각형에 대각선을 하나 그으면 삼각형 몇 개로 나뉘나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u2-C9","difficulty":3,"kind":"sa","stem":"사각형에 대각선을 하나 그으면 삼각형 몇 개로 나뉘나요? 숫자로 쓰세요.","answer":["2"],"explanation":["대각선은 사각형을 둘로 나눠요.","사각형은 삼각형 2개, 네 각의 합 360°.","답은 2."],"variant_rule":{"alt":[{"stem":"사각형의 네 각의 크기의 합은 삼각형의 세 각의 크기의 합의 몇 배인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["360 ÷ 180 = 2.","사각형은 삼각형 2개, 네 각의 합 360°.","답은 2."],"asset":null},{"stem":"사각형의 네 각의 크기의 합은 직각 몇 개를 모은 것과 같나요? 숫자로 쓰세요.","answer":["4"],"explanation":["360 ÷ 90 = 4.","사각형은 삼각형 2개, 네 각의 합 360°.","답은 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_challenge#8','math',4,1,'u2','L08','g4_1_math_u2_L08_challenge','lesson_challenge','M4-1-u2-C9',4,'essay','teacher','사각형의 네 각의 크기의 합이 360°인 까닭을 삼각형을 이용하여 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u2-C9","difficulty":4,"kind":"essay","stem":"사각형의 네 각의 크기의 합이 360°인 까닭을 삼각형을 이용하여 설명해 보세요.","answer_guide":{"answer":"예: 사각형에 대각선을 하나 그으면 삼각형 2개로 나뉜다. 삼각형의 세 각의 합은 180°이므로 두 삼각형의 각을 모두 더하면 180° + 180° = 360°이고, 이것이 사각형의 네 각의 합이다.","scoring_points":["대각선으로 삼각형 2개로 나눈다고 했는가","삼각형의 세 각의 합 180°를 썼는가","180 + 180 = 360을 썼는가"]},"explanation":["대각선 하나 → 삼각형 2개.","180 + 180 = 360.","그래서 네 각의 합은 360°."],"asset":{"type":"geo","items":[{"poly":[[[16.0,221.858811619],[202.404062775,221.858811619],[241.0,77.816812931],[71.159702328,16.0]]],"arc":[[[71.159702328,16.0],[16.0,221.858811619],[202.404062775,221.858811619]],[[16.0,221.858811619],[202.404062775,221.858811619],[241.0,77.816812931]],[[202.404062775,221.858811619],[241.0,77.816812931],[71.159702328,16.0]],[[241.0,77.816812931],[71.159702328,16.0],[16.0,221.858811619]]],"dash":[[[16.0,221.858811619],[241.0,77.816812931]]],"w":257,"h":238}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_challenge#9','math',4,1,'u2','L08','g4_1_math_u2_L08_challenge','lesson_challenge','M4-1-u2-C9',4,'essay','teacher','사각형의 세 각이 85°, 100°, 70°예요. 나머지 한 각을 구하는 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u2-C9","difficulty":4,"kind":"essay","stem":"사각형의 세 각이 85°, 100°, 70°예요. 나머지 한 각을 구하는 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 사각형의 네 각의 합은 360°이므로 360° − 85° − 100° − 70° = 105°이다. 나머지 한 각은 105°이다.","scoring_points":["네 각의 합 360°를 썼는가","세 각을 모두 뺐는가","105°라고 답했는가"]},"explanation":["네 각의 합 360°.","360 − 85 − 100 − 70 = 105.","105°."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L08_challenge#10','math',4,1,'u2','L08','g4_1_math_u2_L08_challenge','lesson_challenge','M4-1-u2-C9',4,'sa','auto','사각형의 두 각이 70°, 120°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u2-C9","difficulty":4,"kind":"sa","stem":"사각형의 두 각이 70°, 120°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["네 각의 합은 360°예요.","360 − 70 − 120 = 170.","170 ÷ 2 = 85 — 한 각은 85°예요."],"variant_rule":{"alt":[{"stem":"사각형의 두 각이 90°, 130°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["네 각의 합은 360°예요.","360 − 90 − 130 = 140.","140 ÷ 2 = 70 — 한 각은 70°예요."],"asset":null},{"stem":"사각형의 두 각이 60°, 100°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["네 각의 합은 360°예요.","360 − 60 − 100 = 200.","200 ÷ 2 = 100 — 한 각은 100°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
