INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_basic#2','math',4,1,'u2','L09','g4_1_math_u2_L09_basic','lesson_basic','M4-1-u2-C10',1,'sa','auto','두 삼각자의 45°와 60°를 꼭짓점에서 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u2-C10","difficulty":1,"kind":"sa","stem":"두 삼각자의 45°와 60°를 꼭짓점에서 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["나란히 붙이면 두 각의 합이에요.","45 + 60 = 105.","만들어진 각은 105°예요."],"asset":{"type":"geo","items":[{"seg":[[[45.764190187,127.081470023],[160.764190187,127.081470023]],[[45.764190187,127.081470023],[127.081470023,45.764190187]],[[45.764190187,127.081470023],[16.0,16.0]]],"arc":[[[160.764190187,127.081470023],[45.764190187,127.081470023],[127.081470023,45.764190187]],[[127.081470023,45.764190187],[45.764190187,127.081470023],[16.0,16.0]]],"lab":[[[81.977393622,112.081470023],"45°"],[[54.56403772,94.239991929],"60°"]],"w":177,"h":143}],"tag":false},"variant_rule":{"alt":[{"stem":"두 삼각자의 30°와 90°를 꼭짓점에서 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["나란히 붙이면 두 각의 합이에요.","30 + 90 = 120.","만들어진 각은 120°예요."],"asset":{"type":"geo","items":[{"seg":[[[73.5,115.592921435],[188.5,115.592921435]],[[73.5,115.592921435],[173.092921435,58.092921435]],[[73.5,115.592921435],[16.0,16.0]]],"arc":[[[188.5,115.592921435],[73.5,115.592921435],[173.092921435,58.092921435]]],"lab":[[[129.480762114,100.592921435],"30°"],[[82.299847533,82.751443341],"90°"]],"right":[[[173.092921435,58.092921435],[73.5,115.592921435],[16.0,16.0]]],"w":204,"h":132}],"tag":false}},{"stem":"두 삼각자의 45°와 30°를 꼭짓점에서 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["나란히 붙이면 두 각의 합이에요.","45 + 30 = 75.","만들어진 각은 75°예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,127.081470023],[131.0,127.081470023]],[[16.0,127.081470023],[97.317279836,45.764190187]]