INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_basic#3','math',4,1,'u2','L09','g4_1_math_u2_L09_basic','lesson_basic','M4-1-u2-C10',1,'sa','auto','삼각자의 90° 위에 다른 삼각자의 45°를 한 변을 맞춰 포개었어요. 남은 각(?)은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u2-C10","difficulty":1,"kind":"sa","stem":"삼각자의 90° 위에 다른 삼각자의 45°를 한 변을 맞춰 포개었어요. 남은 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["포개어 겹치면 두 각의 차예요.","90 − 45 = 45.","남은 각은 45°예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,131.0],[131.0,131.0]],[[16.0,131.0],[16.0,16.0]]],"arc":[[[131.0,131.0],[16.0,131.0],[16.0,16.0]]],"lab":[[[111.45941546,35.54058454],"90°"],[[50.402543264,116.75],"45°"],[[30.25,96.597456736],"?"]],"dash":[[[16.0,131.0],[82.680169466,64.319830534]]],"w":147,"h":147}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각자의 60° 위에 다른 삼각자의 30°를 한 변을 맞춰 포개었어요. 남은 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["포개어 겹치면 두 각의 차예요.","60 − 30 = 30.","남은 각은 30°예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,115.592921435],[131.0,115.592921435]],[[16.0,115.592921435],[73.5,16.0]]],"arc":[[[131.0,115.592921435],[16.0,115.592921435],[73.5,16.0]]],"lab":[[[132.913429511,48.092921435],"60°"],[[69.181724008,101.342921435],"30°"],[[54.931724008,76.661197427],"?"]],"dash":[[[16.0,115.592921435],[97.666195577,68.442921435]]],"w":163,"h":132}],"tag":false}},{"stem":"삼각자의 90° 위에 다른 삼각자의 30°를 한 변을 맞춰 포개었어요. 남은 각(?)은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["포개어 겹치면 두 각의 차예요.","90 − 30 = 60.","남은 각은 60°예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,131.0],[131.0,131.0]],[[16.0,131.0],[16.0,16.0]]],"arc":[[[131.0,131.0],[16.0,131.0],[16.0,16.0]]],"lab":[[[111.45941546,35.54058454],"90°"],[[69.181724008,116.75],"30°"],[[32.15,103.027379458],"?"]],"dash":[[[16.0,131.0],[97.666195577,83.85]]],"w":147,"h":147}],"tag":false}}]