INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_basic#5','math',4,1,'u2','L09','g4_1_math_u2_L09_basic','lesson_basic','M4-1-u2-C10',2,'mc','auto','두 삼각자로 75°를 만들려고 해요. 알맞은 방법은 어느 것인가요?',ARRAY['M4-1-u2-X18']::text[],true,'{"seq":5,"concept":"M4-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 삼각자로 75°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"45°와 30°를 붙여서","correct":true},{"t":"45°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"60°와 60°를 붙여서","mis":"M4-1-u2-X18"},{"t":"60°와 90°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","45°와 30°를 붙여서 → 75°.","답은 「45°와 30°를 붙여서」예요."],"variant_rule":{"alt":[{"stem":"두 삼각자로 105°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"45°와 60°를 붙여서","correct":true},{"t":"30°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"60°와 60°를 붙여서","mis":"M4-1-u2-X18"},{"t":"45°와 45°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","45°와 60°를 붙여서 → 105°.","답은 「45°와 60°를 붙여서」예요."],"asset":null},{"stem":"두 삼각자로 135°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"45°와 90°를 붙여서","correct":true},{"t":"30°와 45°를 붙여서","mis":"M4-1-u2-X18"},{"t":"45°와 60°를 붙여서","mis":"M4-1-u2-X18"},{"t":"60°와 60°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","45°와 90°를 붙여서 → 135°.","답은 「45°와 90°를 붙여서」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
