INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_basic#7','math',4,1,'u2','L09','g4_1_math_u2_L09_basic','lesson_basic','M4-1-u2-C10',2,'ox','auto','두 삼각자를 겹쳐서 만든 각은 두 각의 합이에요.',ARRAY['M4-1-u2-X13']::text[],true,'{"seq":7,"concept":"M4-1-u2-C10","difficulty":2,"kind":"ox","stem":"두 삼각자를 겹쳐서 만든 각은 두 각의 합이에요.","answer":"X","reason_options":[{"t":"겹치면 큰 각에서 작은 각을 뺀 차라서","correct":true},{"t":"두 각을 함께 쓰니 합이라서","mis":"M4-1-u2-X13"}],"mis":"M4-1-u2-X13","explanation":["나란히 붙이면 합, 포개어 겹치면 차예요.","60° 위에 45°를 겹치면 15°.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"두 삼각자로 50°를 만들 수 있어요.","answer":"X","reason_options":[{"t":"만든 각은 모두 15°의 배수인데 50은 아니라서","correct":true},{"t":"45°에 5°만 더하면 되어서","mis":"M4-1-u2-X20"}],"explanation":["삼각자 각은 15의 배수로만 만들어져요.","50은 15의 배수가 아니에요.","그래서 틀렸어요."],"asset":null},{"stem":"두 삼각자로 105°를 만들 수 있어요.","answer":"O","reason_options":[{"t":"45°와 60°를 붙이면 105°라서","correct":true},{"t":"삼각자에는 105°짜리 각이 없어서","mis":"M4-1-u2-X18"}],"explanation":["45 + 60 = 105.","붙이면 만들 수 있어요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_basic#8','math',4,1,'u2','L09','g4_1_math_u2_L09_basic','lesson_basic','M4-1-u2-C10',2,'mc','auto','두 삼각자로 만들 수 없는 각은 어느 것인가요?',ARRAY['M4-1-u2-X20']::text[],true,'{"seq":8,"concept":"M4-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"40°","correct":true},{"t":"105°","mis":"M4-1-u2-X20"},{"t":"135°","mis":"M4-1-u2-X20"},{"t":"15°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","40°는 15의 배수가 아니에요.","만들 수 없는 각은 40°예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"50°","correct":true},{"t":"15°","mis":"M4-1-u2-X20"},{"t":"60°","mis":"M4-1-u2-X20"},{"t":"30°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","50°는 15의 배수가 아니에요.","만들 수 없는 각은 50°예요."],"asset":null},{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"100°","correct":true},{"t":"120°","mis":"M4-1-u2-X20"},{"t":"135°","mis":"M4-1-u2-X20"},{"t":"30°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","100°는 15의 배수가 아니에요.","만들 수 없는 각은 100°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_basic#9','math',4,1,'u2','L09','g4_1_math_u2_L09_basic','lesson_basic','M4-1-u2-C10',2,'mc','auto','두 삼각자로 15°를 만들려고 해요. 알맞은 방법은 어느 것인가요?',ARRAY['M4-1-u2-X18']::text[],true,'{"seq":9,"concept":"M4-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 삼각자로 15°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"45° 위에 30°를 겹쳐서","correct":true},{"t":"60°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"30°와 60°를 붙여서","mis":"M4-1-u2-X18"},{"t":"30°와 30°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","45° 위에 30°를 겹쳐서 → 15°.","답은 「45° 위에 30°를 겹쳐서」예요."],"variant_rule":{"alt":[{"stem":"두 삼각자로 120°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"90°와 30°를 붙여서","correct":true},{"t":"60°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"45°와 45°를 붙여서","mis":"M4-1-u2-X18"},{"t":"30°와 45°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","90°와 30°를 붙여서 → 120°.","답은 「90°와 30°를 붙여서」예요."],"asset":null},{"stem":"두 삼각자로 150°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"90°와 60°를 붙여서","correct":true},{"t":"45°와 60°를 붙여서","mis":"M4-1-u2-X18"},{"t":"90°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"30°와 90°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","90°와 60°를 붙여서 → 150°.","답은 「90°와 60°를 붙여서」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_basic#10','math',4,1,'u2','L09','g4_1_math_u2_L09_basic','lesson_basic','M4-1-u2-C10',3,'error','auto','삼각자의 60° 위에 45°를 한 변을 맞춰 포개었어요. 남은 각을 두고 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X13','M4-1-u2-X19']::text[],true,'{"seq":10,"concept":"M4-1-u2-C10","difficulty":3,"kind":"error","stem":"삼각자의 60° 위에 45°를 한 변을 맞춰 포개었어요. 남은 각을 두고 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「60 + 45 = 105°예요.」","correct":true,"mis_target":"M4-1-u2-X13"},{"t":"준서 — 「60 − 45 = 15°예요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「포개면 두 각의 차예요.」","mis":"M4-1-u2-X19"}],"explanation":["포개어 겹치면 남는 부분은 두 각의 차예요.","60 − 45 = 15.","도윤은 더해서 잘못 말했어요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,115.592921435],[131.0,115.592921435]],[[16.0,115.592921435],[73.5,16.0]]],"arc":[[[131.0,115.592921435],[16.0,115.592921435],[73.5,16.0]]],"lab":[[[132.913429511,48.092921435],"60°"],[[50.402543264,101.342921435],"45°"],[[69.205748895,46.253839494],"?"]],"dash":[[[16.0,115.592921435],[82.680169466,48.912751969]]],"w":163,"h":132}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각자의 90° 위에 30°를 한 변을 맞춰 포개었어요. 남은 각을 두고 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「90 + 30 = 120°예요.」","correct":true,"mis_target":"M4-1-u2-X13"},{"t":"도윤 — 「90 − 30 = 60°예요.」","mis":"M4-1-u2-X19"},{"t":"하람 — 「포개면 두 각의 차예요.」","mis":"M4-1-u2-X19"}],"explanation":["포개어 겹치면 남는 부분은 두 각의 차예요.","90 − 30 = 60.","예린은 더해서 잘못 말했어요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,131.0],[131.0,131.0]],[[16.0,131.0],[16.0,16.0]]],"arc":[[[131.0,131.0],[16.0,131.0],[16.0,16.0]]],"lab":[[[111.45941546,35.54058454],"90°"],[[69.181724008,116.75],"30°"],[[32.15,103.027379458],"?"]],"dash":[[[16.0,131.0],[97.666195577,83.85]]],"w":147,"h":147}],"tag":false}},{"stem":"삼각자의 90° 위에 45°를 한 변을 맞춰 포개었어요. 남은 각을 두고 잘못 말한 친구는 누구인가요?","options":[{"t":"은비 — 「90 + 45 = 135°예요.」","correct":true,"mis_target":"M4-1-u2-X13"},{"t":"예린 — 「90 − 45 = 45°예요.」","mis":"M4-1-u2-X19"},{"t":"나래 — 「포개면 두 각의 차예요.」","mis":"M4-1-u2-X19"}],"explanation":["포개어 겹치면 남는 부분은 두 각의 차예요.","90 − 45 = 45.","은비는 더해서 잘못 말했어요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,131.0],[131.0,131.0]],[[16.0,131.0],[16.0,16.0]]],"arc":[[[131.0,131.0],[16.0,131.0],[16.0,16.0]]],"lab":[[[111.45941546,35.54058454],"90°"],[[50.402543264,116.75],"45°"],[[30.25,96.597456736],"?"]],"dash":[[[16.0,131.0],[82.680169466,64.319830534]]],"w":147,"h":147}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
