INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_challenge#3','math',4,1,'u2','L09','g4_1_math_u2_L09_challenge','lesson_challenge','M4-1-u2-C10',3,'sa','auto','삼각자의 45°, 30°, 90°를 꼭짓점에서 차례로 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u2-C10","difficulty":3,"kind":"sa","stem":"삼각자의 45°, 30°, 90°를 꼭짓점에서 차례로 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.","answer":["165"],"explanation":["나란히 붙이면 모두 더해요.","45 + 30 + 90 = 165.","만들어진 각은 165°예요."],"asset":{"type":"geo","items":[{"seg":[[[127.081470023,127.081470023],[242.081470023,127.081470023]],[[127.081470023,127.081470023],[208.39874986,45.764190187]],[[127.081470023,127.081470023],[156.84566021,16.0]],[[127.081470023,127.081470023],[16.0,97.317279836]]],"arc":[[[242.081470023,127.081470023],[127.081470023,127.081470023],[208.39874986,45.764190187]],[[208.39874986,45.764190187],[127.081470023,127.081470023],[156.84566021,16.0]]],"lab":[[[163.294673459,112.081470023],"45°"],[[156.059244812,76.890491799],"30°"],[[110.081470023,97.636606295],"90°"]],"right":[[[156.84566021,16.0],[127.081470023,127.081470023],[16.0,97.317279836]]],"w":258,"h":143}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각자의 60°, 45°, 30°를 꼭짓점에서 차례로 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["나란히 붙이면 모두 더해요.","60 + 45 + 30 = 135.","만들어진 각은 135°예요."],"asset":{"type":"geo","items":[{"seg":[[[97.317279836,127.081470023],[212.317279836,127.081470023]],[[97.317279836,127.081470023],[154.817279836,27.488548588]],[[97.317279836,127.081470023],[67.55308965,16.0]],[[97.317279836,127.081470023],[16.0,45.764190187]]],"arc":[[[212.317279836,127.081470023],[97.317279836,127.081470023],[154.817279836,27.488548588]],[[154.817279836,27.488548588],[97.317279836,127.081470023],[67.55308965,16.0]],[[67.55308965,16.0],[97.317279836,127.081470023],[16.0,45.764190187]]],"lab":[[[126.762143565,110.081470023],"60°"],[[102.433500497,88.219915896],"45°"],[[68.339505048,76.890491799],"30°"]],"w":228,"h":143}],"tag":false}},{"stem":"삼각자의 90°, 45°, 60°를 꼭짓점에서 차례로 나란히 붙였어요. 만들어진 각은 몇 도인가요? 숫자로 쓰세요.","answer":["195"],"explanation":["나란히 붙이면 모두 더해요.","90 + 45 + 60 = 195.","만들어진 각은 195°예요."],"asset":{"type":"geo","items":[{"seg":[[[127.081470023,131.0],[242.081470023,131.0]],[[127.081470023,131.0],[127.081470023,16.0]],[[127.081470023,131.0],[45.764190187,49.682720164]],[[127.081470023,131.0],[16.0,160.764190187]]],"arc":[[[127.081470023,16.0],[127.081470023,131.0],[45.764190187,49.682720164]],[[45.764190187,49.682720164],[127.081470023,131.0],[16.0,160.764190187]]],"lab":[[[151.123100584,106.95836944],"90°"],[[112.081470023,94.786796564],"45°"],[[94.239991929,122.200152467],"60°"]],"right":[[[242.081470023,131.0],[127.081470023,131.0],[127.081470023,16.0]]],"w":258,"h":177}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_challenge#4','math',4,1,'u2','L09','g4_1_math_u2_L09_challenge','lesson_challenge','M4-1-u2-C10',3,'error','auto','삼각자의 60° 위에 30°를 한 변을 맞춰 포개었어요. 남은 각을 두고 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X13','M4-1-u2-X19']::text[],true,'{"seq":4,"concept":"M4-1-u2-C10","difficulty":3,"kind":"error","stem":"삼각자의 60° 위에 30°를 한 변을 맞춰 포개었어요. 남은 각을 두고 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「60 + 30 = 90°예요.」","correct":true,"mis_target":"M4-1-u2-X13"},{"t":"준서 — 「60 − 30 = 30°예요.」","mis":"M4-1-u2-X19"},{"t":"예린 — 「포개면 두 각의 차예요.」","mis":"M4-1-u2-X19"}],"explanation":["포개어 겹치면 남는 부분은 두 각의 차예요.","60 − 30 = 30.","지호는 더해서 잘못 말했어요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,115.592921435],[131.0,115.592921435]],[[16.0,115.592921435],[73.5,16.0]]],"arc":[[[131.0,115.592921435],[16.0,115.592921435],[73.5,16.0]]],"lab":[[[132.913429511,48.092921435],"60°"],[[69.181724008,101.342921435],"30°"],[[54.931724008,76.661197427],"?"]],"dash":[[[16.0,115.592921435],[97.666195577,68.442921435]]],"w":163,"h":132}],"tag":false},"variant_rule":{"alt":[{"stem":"삼각자의 45° 위에 30°를 한 변을 맞춰 포개었어요. 남은 각을 두고 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「45 + 30 = 75°예요.」","correct":true,"mis_target":"M4-1-u2-X13"},{"t":"도윤 — 「45 − 30 = 15°예요.」","mis":"M4-1-u2-X19"},{"t":"지호 — 「포개면 두 각의 차예요.」","mis":"M4-1-u2-X19"}],"explanation":["포개어 겹치면 남는 부분은 두 각의 차예요.","45 − 30 = 15.","준서는 더해서 잘못 말했어요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,97.317279836],[131.0,97.317279836]],[[16.0,97.317279836],[97.317279836,16.0]]],"arc":[[[131.0,97.317279836],[16.0,97.317279836],[97.317279836,16.0]]],"lab":[[[140.723736889,45.655016467],"45°"],[[69.181724008,83.067279836],"30°"],[[85.339081941,44.111530941],"?"]],"dash":[[[16.0,97.317279836],[97.666195577,50.167279836]]],"w":171,"h":113}],"tag":false}},{"stem":"삼각자의 90° 위에 60°를 한 변을 맞춰 포개었어요. 남은 각을 두고 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「90 + 60 = 150°예요.」","correct":true,"mis_target":"M4-1-u2-X13"},{"t":"나래 — 「90 − 60 = 30°예요.」","mis":"M4-1-u2-X19"},{"t":"준서 — 「포개면 두 각의 차예요.」","mis":"M4-1-u2-X19"}],"explanation":["포개어 겹치면 남는 부분은 두 각의 차예요.","90 − 60 = 30.","예린은 더해서 잘못 말했어요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,131.0],[131.0,131.0]],[[16.0,131.0],[16.0,16.0]]],"arc":[[[131.0,131.0],[16.0,131.0],[16.0,16.0]]],"lab":[[[111.45941546,35.54058454],"90°"],[[43.972620542,114.85],"60°"],[[30.25,77.818275992],"?"]],"dash":[[[16.0,131.0],[63.15,49.333804423]]],"w":147,"h":147}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_challenge#5','math',4,1,'u2','L09','g4_1_math_u2_L09_challenge','lesson_challenge','M4-1-u2-C10',3,'sa','auto','삼각자의 45°와 60°를 나란히 붙인 각 위에 30°를 한 변을 맞춰 포개었어요. 남은 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u2-C10","difficulty":3,"kind":"sa","stem":"삼각자의 45°와 60°를 나란히 붙인 각 위에 30°를 한 변을 맞춰 포개었어요. 남은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["붙이면 합: 45 + 60 = 105.","포개면 차: 105 − 30 = 75.","남은 각은 75°예요."],"variant_rule":{"alt":[{"stem":"삼각자의 90°와 45°를 나란히 붙인 각 위에 60°를 한 변을 맞춰 포개었어요. 남은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["붙이면 합: 90 + 45 = 135.","포개면 차: 135 − 60 = 75.","남은 각은 75°예요."],"asset":null},{"stem":"삼각자의 60°와 90°를 나란히 붙인 각 위에 45°를 한 변을 맞춰 포개었어요. 남은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["붙이면 합: 60 + 90 = 150.","포개면 차: 150 − 45 = 105.","남은 각은 105°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_challenge#6','math',4,1,'u2','L09','g4_1_math_u2_L09_challenge','lesson_challenge','M4-1-u2-C10',3,'mc','auto','두 삼각자로 만들 수 없는 각은 어느 것인가요?',ARRAY['M4-1-u2-X20']::text[],true,'{"seq":6,"concept":"M4-1-u2-C10","difficulty":3,"kind":"mc","stem":"두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"35°","correct":true},{"t":"150°","mis":"M4-1-u2-X20"},{"t":"75°","mis":"M4-1-u2-X20"},{"t":"120°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","35°는 15의 배수가 아니에요.","만들 수 없는 각은 35°예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"55°","correct":true},{"t":"120°","mis":"M4-1-u2-X20"},{"t":"105°","mis":"M4-1-u2-X20"},{"t":"60°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","55°는 15의 배수가 아니에요.","만들 수 없는 각은 55°예요."],"asset":null},{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"170°","correct":true},{"t":"60°","mis":"M4-1-u2-X20"},{"t":"135°","mis":"M4-1-u2-X20"},{"t":"105°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","170°는 15의 배수가 아니에요.","만들 수 없는 각은 170°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_challenge#7','math',4,1,'u2','L09','g4_1_math_u2_L09_challenge','lesson_challenge','M4-1-u2-C10',3,'ox','auto','두 삼각자로 50°를 만들 수 있어요.',ARRAY['M4-1-u2-X20']::text[],true,'{"seq":7,"concept":"M4-1-u2-C10","difficulty":3,"kind":"ox","stem":"두 삼각자로 50°를 만들 수 있어요.","answer":"X","reason_options":[{"t":"만든 각은 모두 15°의 배수인데 50은 아니라서","correct":true},{"t":"45°에 5°만 더하면 되어서","mis":"M4-1-u2-X20"}],"mis":"M4-1-u2-X20","explanation":["삼각자 각은 15의 배수로만 만들어져요.","50은 15의 배수가 아니에요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"두 삼각자로 105°를 만들 수 있어요.","answer":"O","reason_options":[{"t":"45°와 60°를 붙이면 105°라서","correct":true},{"t":"삼각자에는 105°짜리 각이 없어서","mis":"M4-1-u2-X18"}],"explanation":["45 + 60 = 105.","붙이면 만들 수 있어요.","그래서 맞아요."],"asset":null},{"stem":"두 삼각자를 겹쳐서 만든 각은 두 각의 합이에요.","answer":"X","reason_options":[{"t":"겹치면 큰 각에서 작은 각을 뺀 차라서","correct":true},{"t":"두 각을 함께 쓰니 합이라서","mis":"M4-1-u2-X13"}],"explanation":["나란히 붙이면 합, 포개어 겹치면 차예요.","60° 위에 45°를 겹치면 15°.","그래서 틀렸어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_challenge#8','math',4,1,'u2','L09','g4_1_math_u2_L09_challenge','lesson_challenge','M4-1-u2-C10',4,'essay','teacher','두 삼각자를 이용하여 15°를 만드는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u2-C10","difficulty":4,"kind":"essay","stem":"두 삼각자를 이용하여 15°를 만드는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 30°·60°·90° 삼각자의 60° 위에 45°·45°·90° 삼각자의 45°를 한 변을 맞추어 포갠다. 남은 각은 60° − 45° = 15°이다(45° 위에 30°를 포개도 15°).","scoring_points":["겹쳐서(포개어) 만든다고 했는가","쓰는 두 각(60°와 45° 또는 45°와 30°)을 밝혔는가","두 각의 차로 15°를 구했는가"]},"explanation":["포개면 차예요.","60 − 45 = 15 또는 45 − 30 = 15.","15°를 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_challenge#9','math',4,1,'u2','L09','g4_1_math_u2_L09_challenge','lesson_challenge','M4-1-u2-C10',4,'essay','teacher','두 삼각자로 50°를 만들 수 있는지 쓰고, 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M4-1-u2-C10","difficulty":4,"kind":"essay","stem":"두 삼각자로 50°를 만들 수 있는지 쓰고, 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 만들 수 없다. 삼각자의 각은 30°·45°·60°·90°로 모두 15°의 배수이고, 붙이거나 겹쳐 만든 각도 모두 15°의 배수이다. 50은 15의 배수가 아니므로 만들 수 없다.","scoring_points":["만들 수 없다고 답했는가","삼각자 각이 15°의 배수라고 했는가","50이 15의 배수가 아니라고 했는가"]},"explanation":["삼각자 각은 15의 배수.","합·차도 15의 배수.","50은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_L09_challenge#10','math',4,1,'u2','L09','g4_1_math_u2_L09_challenge','lesson_challenge','M4-1-u2-C10',4,'sa','auto','45°·45°·90° 삼각자의 한 각과 30°·60°·90° 삼각자의 한 각을 나란히 붙여 만들 수 있는 서로 다른 각 중 둔각은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u2-C10","difficulty":4,"kind":"sa","stem":"45°·45°·90° 삼각자의 한 각과 30°·60°·90° 삼각자의 한 각을 나란히 붙여 만들 수 있는 서로 다른 각 중 둔각은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["45° 또는 90°에 30°·60°·90°를 하나씩 더해요.","만들 수 있는 각: 75°, 105°, 120°, 135°, 150°, 180°.","둔각은 105°, 120°, 135°, 150° — 4개."],"variant_rule":{"alt":[{"stem":"45°·45°·90° 삼각자의 한 각과 30°·60°·90° 삼각자의 한 각을 나란히 붙여 만들 수 있는 서로 다른 각 중 예각은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["45° 또는 90°에 30°·60°·90°를 하나씩 더해요.","만들 수 있는 각: 75°, 105°, 120°, 135°, 150°, 180°.","예각은 75° — 1개."],"asset":null},{"stem":"45°·45°·90° 삼각자의 한 각과 30°·60°·90° 삼각자의 한 각을 나란히 붙여 만들 수 있는 서로 다른 각 중 120°보다 큰 각은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["45° 또는 90°에 30°·60°·90°를 하나씩 더해요.","만들 수 있는 각: 75°, 105°, 120°, 135°, 150°, 180°.","120°보다 큰 각은 135°, 150°, 180° — 3개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#1','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C3',1,'sa','auto','직각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C3","difficulty":1,"kind":"sa","stem":"직각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["한 바퀴 360°를 똑같이 넷으로 나눈 각이에요.","360 ÷ 4 = 90.","답은 90°예요."],"variant_rule":{"alt":[{"stem":"한 바퀴를 돈 각은 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["1°는 한 바퀴를 360칸으로 나눈 한 칸이에요.","360칸이면 한 바퀴 — 360°.","답은 360°예요."],"asset":null},{"stem":"한 바퀴의 반만큼 돈 각(일직선)은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 바퀴 360°의 반이에요.","360 ÷ 2 = 180.","답은 180°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#2','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C2',1,'mc','auto','두 각 중 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X01']::text[],true,'{"seq":2,"concept":"M4-1-u2-C2","difficulty":1,"kind":"mc","stem":"두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉯가 더 많이 벌어졌어요.","더 큰 각은 ㉯예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,165.429204714],[166.0,165.429204714]],[[16.0,165.429204714],[29.073361412,16.0]]],"arc":[[[166.0,165.429204714],[16.0,165.429204714],[29.073361412,16.0]]],"w":182,"h":181},{"seg":[[[69.623111018,60.995132678],[139.623111018,60.995132678]],[[69.623111018,60.995132678],[16.0,16.0]]],"arc":[[[139.623111018,60.995132678],[69.623111018,60.995132678],[16.0,16.0]]],"w":156,"h":77}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉯가 더 많이 벌어졌어요.","더 큰 각은 ㉯예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,79.392739261],[166.0,79.392739261]],[[16.0,79.392739261],[151.946168055,16.0]]],"arc":[[[166.0,79.392739261],[16.0,79.392739261],[151.946168055,16.0]]],"w":182,"h":95},{"seg":[[[16.0,86.0],[86.0,86.0]],[[16.0,86.0],[16.0,16.0]]],"right":[[[86.0,86.0],[16.0,86.0],[16.0,16.0]]],"w":102,"h":102}]}},{"stem":"이번에는 다른 각이에요. 두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉯가 더 많이 벌어졌어요.","더 큰 각은 ㉯예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,102.036465453],[166.0,102.036465453]],[[16.0,102.036465453],[138.872806643,16.0]]],"arc":[[[166.0,102.036465453],[16.0,102.036465453],[138.872806643,16.0]]],"w":182,"h":118},{"seg":[[[60.995132678,69.623111018],[130.995132678,69.623111018]],[[60.995132678,69.623111018],[16.0,16.0]]],"arc":[[[130.995132678,69.623111018],[60.995132678,69.623111018],[16.0,16.0]]],"w":147,"h":86}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#3','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C4',1,'sa','auto','각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u2-C4","difficulty":1,"kind":"sa","stem":"각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["밑금 위의 변이 오른쪽에 있으니 오른쪽 0에서 시작하는 안쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 20°.","각의 크기는 20°예요 (다른 줄 160°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":20,"from":"right"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["155"],"explanation":["밑금 위의 변이 오른쪽에 있으니 오른쪽 0에서 시작하는 안쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 155°.","각의 크기는 155°예요 (다른 줄 25°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":155,"from":"right"}},{"stem":"이번에는 다른 각이에요. 각도기로 각의 크기를 재었어요. 각의 크기는 몇 도인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["밑금 위의 변이 오른쪽에 있으니 오른쪽 0에서 시작하는 안쪽 눈금을 읽어요.","0에서부터 다른 변이 가리키는 눈금까지 — 15°.","각의 크기는 15°예요 (다른 줄 165°는 잘못 읽은 값)."],"asset":{"type":"prot","deg":15,"from":"right"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#4','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C5',1,'mc','auto','이 각은 어떤 각인가요?',ARRAY['M4-1-u2-X09','M4-1-u2-X02','M4-1-u2-X10']::text[],true,'{"seq":4,"concept":"M4-1-u2-C5","difficulty":1,"kind":"mc","stem":"이 각은 어떤 각인가요?","options":[{"t":"둔각","correct":true},{"t":"예각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 커요.","답은 둔각이에요."],"asset":{"type":"geo","items":[{"seg":[[[79.093407999,106.106724872],[182.459596285,68.484509106]],[[79.093407999,106.106724872],[16.0,16.0]]],"arc":[[[182.459596285,68.484509106],[79.093407999,106.106724872],[16.0,16.0]]],"w":198,"h":122}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 이 각은 어떤 각인가요?","options":[{"t":"직각","correct":true},{"t":"예각","mis":"M4-1-u2-X02"},{"t":"둔각","mis":"M4-1-u2-X10"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 작지도 크지도 않아요.","답은 직각이에요."],"asset":{"type":"geo","items":[{"seg":[[[25.587131702,125.58141679],[135.168548492,115.994285088]],[[25.587131702,125.58141679],[16.0,16.0]]],"right":[[[135.168548492,115.994285088],[25.587131702,125.58141679],[16.0,16.0]]],"w":151,"h":142}],"tag":false}},{"stem":"이번에는 다른 각이에요. 이 각은 어떤 각인가요?","options":[{"t":"둔각","correct":true},{"t":"예각","mis":"M4-1-u2-X09"},{"t":"직각","mis":"M4-1-u2-X02"},{"t":"일직선","mis":"M4-1-u2-X10"}],"explanation":["직각(90°)과 견주어요 — 놓인 방향은 상관없어요.","이 각은 직각보다 커요.","답은 둔각이에요."],"asset":{"type":"geo","items":[{"seg":[[[62.488008791,115.693856574],[172.488008791,115.693856574]],[[62.488008791,115.693856574],[16.0,16.0]]],"arc":[[[172.488008791,115.693856574],[62.488008791,115.693856574],[16.0,16.0]]],"w":188,"h":132}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UP