INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#19','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C8',3,'sa','auto','삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-1-u2-C8","difficulty":3,"kind":"sa","stem":"삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["삼각형의 나머지 한 각: 180 − 85 − 50 = 45.","그 각과 ?가 일직선을 이루어요: 180 − 45 = 135.","?는 135°예요 (= 85 + 50)."],"asset":{"type":"geo","items":[{"poly":[[[51.172069466,285.468704086],[251.172069466,285.468704086],[70.056111931,69.623111018]]],"seg":[[[70.056111931,69.623111018],[25.060979253,16.0]]],"arc":[[[25.060979253,16.0],[70.056111931,69.623111018],[51.172069466,285.468704086]]],"lab":[[[89.51049098,250.33801329],"85°"],[[193.168371096,258.421135335],"50°"],[[30.0,82.252754598],"?"]],"w":267,"h":301}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["삼각형의 나머지 한 각: 180 − 60 − 30 = 90.","그 각과 ?가 일직선을 이루어요: 180 − 90 = 90.","?는 90°예요 (= 60 + 30)."],"asset":{"type":"geo","items":[{"poly":[[[26.621778265,137.602540378],[226.621778265,137.602540378],[76.621778265,51.0]]],"seg":[[[76.621778265,51.0],[16.0,16.0]]],"arc":[[[16.0,16.0],[76.621778265,51.0],[26.621778265,137.602540378]]],"lab":[[[71.655099262,111.602540378],"60°"],[[164.802525382,121.038121492],"30°"],[[36.052893561,61.870399894],"?"]],"w":243,"h":154}],"tag":false}},{"stem":"이번에는 다른 각이에요. 삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["125"],"explanation":["삼각형의 나머지 한 각: 180 − 105 − 20 = 55.","그 각과 ?가 일직선을 이루어요: 180 − 55 = 125.","?는 125°예요 (= 105 + 20)."],"asset":{"type":"geo","items":[{"poly":[[[103.391400744,120.601915455],[303.391400744,120.601915455],[81.778483455,39.941410033]]],"seg":[[[81.778483455,39.941410033],[16.0,16.0]]],"arc":[[[16.0,16.0],[