INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#20','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C9',3,'sa','auto','사각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-1-u2-C9","difficulty":3,"kind":"sa","stem":"사각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["125"],"explanation":["사각형의 나머지 한 각: 360 − 55 − 115 − 135 = 55.","그 각과 ?가 일직선: 180 − 55 = 125.","?는 125°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,222.782353774],[174.159083186,222.782353774],[241.0,79.441545093],[98.813146501,104.512923666]]],"seg":[[[241.0,79.441545093],[270.583278322,16.0]]],"arc":[[[270.583278322,16.0],[241.0,79.441545093],[98.813146501,104.512923666]]],"lab":[[[72.768693323,193.230442527],"55°"],[[152.667098852,189.046695942],"115°"],[[120.305130835,138.248581499],"135°"],[[215.432019982,46.1207048],"?"]],"w":287,"h":239}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 사각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["사각형의 나머지 한 각: 360 − 80 − 55 − 115 = 110.","그 각과 ?가 일직선: 180 − 110 = 70.","?는 70°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,226.931651404],[241.0,226.931651404],[133.454418184,73.3406431],[38.600717044,98.75661572]]],"seg":[[[133.454418184,73.3406431],[93.30406764,16.0]]],"arc":[[[93.30406764,16.0],[133.454418184,73.3406431],[38.600717044,98.75661572]]],"lab":[[[55.834311042,193.506695701],"80°"],[[184.231306677,197.379740157],"55°"],[[68.091810517,125.780224024],"115°"],[[93.987328111,58.975797081],"?"]],"w":257,"h":243}],"tag":false}},{"stem":"이번에는 다른 각이에요. 사각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["사각형의 나머지 한 각: 360 − 55 − 120 − 95 = 90.","그 각과 ?가 일직선: 180 − 90 = 90.","?는 90°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,176.749209571],[185.672131148,176.749209571],[241.0,80.918529644],[128.557808303,16.0]]],"seg":[[[241.0,80.918529644],[276.0,20.29675138]]],"arc":[[[276.0,20.29675138],[241.0,80.918529644],[128.557808303,16.0]]],"lab":[[[72.768693323,147.197298324],"55°"],[[165.672131148,142.10819342],"120°"],[[139.812668228,66.76739237],"95°"],[[230.129600106,40.34964494],"?"]],"w":292,"h":193}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#21','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C6',3,'mc','auto','각도기로 재니 160°인 각을 준서는 약 165°, 나래는 약 130°, 예린는 약 145°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?',ARRAY['M4-1-u2-X12']::text[],true,'{"seq":21,"concept":"M4-1-u2-C6","difficulty":3,"kind":"mc","stem":"각도기로 재니 160°인 각을 준서는 약 165°, 나래는 약 130°, 예린는 약 145°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"준서","correct":true},{"t":"나래","mis":"M4-1-u2-X12"},{"t":"예린","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","준서 5°, 나래 30°, 예린 15° 차이.","차가 가장 작은 준서가 가장 잘 어림했어요."],"variant_rule":{"alt":[{"stem":"각도기로 재니 140°인 각을 준서는 약 125°, 나래는 약 120°, 하람는 약 145°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"하람","correct":true},{"t":"나래","mis":"M4-1-u2-X12"},{"t":"준서","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","준서 15°, 나래 20°, 하람 5° 차이.","차가 가장 작은 하람이 가장 잘 어림했어요."],"asset":null},{"stem":"각도기로 재니 100°인 각을 준서는 약 120°, 예린는 약 90°, 서아는 약 95°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"서아","correct":true},{"t":"준서","mis":"M4-1-u2-X12"},{"t":"예린","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","준서 20°, 예린 10°, 서아 5° 차이.","차가 가장 작은 서아가 가장 잘 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#22','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C10',3,'mc','auto','두 삼각자로 만들 수 없는 각은 어느 것인가요?',ARRAY['M4-1-u2-X20']::text[],true,'{"seq":22,"concept":"M4-1-u2-C10","difficulty":3,"kind":"mc","stem":"두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"10°","correct":true},{"t":"75°","mis":"M4-1-u2-X20"},{"t":"105°","mis":"M4-1-u2-X20"},{"t":"135°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","10°는 15의 배수가 아니에요.","만들 수 없는 각은 10°예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"95°","correct":true},{"t":"75°","mis":"M4-1-u2-X20"},{"t":"60°","mis":"M4-1-u2-X20"},{"t":"30°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","95°는 15의 배수가 아니에요.","만들 수 없는 각은 95°예요."],"asset":null},{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"55°","correct":true},{"t":"30°","mis":"M4-1-u2-X20"},{"t":"60°","mis":"M4-1-u2-X20"},{"t":"15°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","55°는 15의 배수가 아니에요.","만들 수 없는 각은 55°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#23','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C9',4,'sa','auto','사각형의 두 각이 150°, 120°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u2-C9","difficulty":4,"kind":"sa","stem":"사각형의 두 각이 150°, 120°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["네 각의 합은 360°예요.","360 − 150 − 120 = 90.","90 ÷ 2 = 45 — 한 각은 45°예요."],"variant_rule":{"alt":[{"stem":"사각형의 두 각이 145°, 65°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["네 각의 합은 360°예요.","360 − 145 − 65 = 150.","150 ÷ 2 = 75 — 한 각은 75°예요."],"asset":null},{"stem":"사각형의 두 각이 145°, 135°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["네 각의 합은 360°예요.","360 − 145 − 135 = 80.","80 ÷ 2 = 40 — 한 각은 40°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#24','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C8',4,'sa','auto','삼각형의 한 각이 80°예요. 나머지 두 각 중 한 각은 다른 한 각의 3배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u2-C8","difficulty":4,"kind":"sa","stem":"삼각형의 한 각이 80°예요. 나머지 두 각 중 한 각은 다른 한 각의 3배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["나머지 두 각의 합: 180 − 80 = 100.","작은 각을 4묶음으로 보면 100 ÷ 4 = 25.","더 작은 각은 25°예요 (큰 각 75°)."],"variant_rule":{"alt":[{"stem":"삼각형의 한 각이 20°예요. 나머지 두 각 중 한 각은 다른 한 각의 3배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["나머지 두 각의 합: 180 − 20 = 160.","작은 각을 4묶음으로 보면 160 ÷ 4 = 40.","더 작은 각은 40°예요 (큰 각 120°)."],"asset":null},{"stem":"삼각형의 한 각이 125°예요. 나머지 두 각 중 한 각은 다른 한 각의 4배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["나머지 두 각의 합: 180 − 125 = 55.","작은 각을 5묶음으로 보면 55 ÷ 5 = 11.","더 작은 각은 11°예요 (큰 각 44°)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_a#25','math',4,1,'u2','','g4_1_math_u2_review_a','unit_review','M4-1-u2-C4',4,'essay','teacher','각도기로 각을 잴 때 꼭 지켜야 할 것 두 가지와, 안쪽·바깥쪽 두 줄 눈금 중 어느 것을 읽어야 하는지 정하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u2-C4","difficulty":4,"kind":"essay","stem":"각도기로 각을 잴 때 꼭 지켜야 할 것 두 가지와, 안쪽·바깥쪽 두 줄 눈금 중 어느 것을 읽어야 하는지 정하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 중심을 꼭짓점에, 밑금을 한 변에 맞춘다. 밑금 위의 변이 놓인 쪽에서 0으로 시작하는 줄 눈금을 따라 읽는다.","scoring_points":["중심 → 꼭짓점을 썼는가","밑금 → 한 변을 썼는가","0에서 시작하는 줄을 읽는다고 했는가"]},"explanation":["중심과 밑금을 맞춰요.","변이 놓인 쪽 0을 찾아요.","그 줄 눈금을 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#1','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C3',1,'sa','auto','직각 2개를 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C3","difficulty":1,"kind":"sa","stem":"직각 2개를 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["직각은 90°예요.","90 + 90 = 180 — 일직선이에요.","답은 180°예요."],"variant_rule":{"alt":[{"stem":"직각 4개를 한 점에 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["직각은 90°예요.","90 × 4 = 360 — 한 바퀴예요.","답은 360°예요."],"asset":null},{"stem":"1°짜리 각이 몇 개 모이면 직각이 되나요? 숫자로 쓰세요.","answer":["90"],"explanation":["직각은 90°예요.","1°가 90개면 90°.","답은 90°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
