INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#12','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C8',2,'mc','auto','삼각형의 두 각이 70°, 45°예요. 나머지 한 각은 몇 도인가요?',ARRAY['M4-1-u2-X15','M4-1-u2-X17']::text[],true,'{"seq":12,"concept":"M4-1-u2-C8","difficulty":2,"kind":"mc","stem":"삼각형의 두 각이 70°, 45°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"65°","correct":true},{"t":"245°","mis":"M4-1-u2-X15"},{"t":"110°","mis":"M4-1-u2-X17"},{"t":"115°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 70 − 45 = 65.","나머지 한 각은 65°예요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 60°, 30°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"90°","correct":true},{"t":"270°","mis":"M4-1-u2-X15"},{"t":"120°","mis":"M4-1-u2-X17"},{"t":"100°","mis":"M4-1-u2-X13"}],"explanation":["세 각의 합은 180°예요.","180 − 60 − 30 = 90.","나머지 한 각은 90°예요."],"asset":null},{"stem":"삼각형의 두 각이 45°, 65°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"70°","correct":true},{"t":"250°","mis":"M4-1-u2-X15"},{"t":"135°","mis":"M4-1-u2-X17"},{"t":"110°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 45 − 65 = 70.","나머지 한 각은 70°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#13','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C9',2,'mc','auto','사각형의 세 각이 95°, 120°, 75°예요. 나머지 한 각은 몇 도인가요?',ARRAY['M4-1-u2-X17','M4-1-u2-X13']::text[],true,'{"seq":13,"concept":"M4-1-u2-C9","difficulty":2,"kind":"mc","stem":"사각형의 세 각이 95°, 120°, 75°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"70°","correct":true},{"t":"290°","mis":"M4-1-u2-X17"},{"t":"145°","mis":"M4-1-u2-X17"},{"t":"80°","mis":"M4-1-u2-X13"}],"explanation":["네 각의 합은 360°예요.","360 − 95 − 120 − 75 = 70.","나머지 한 각은 70°예요."],"variant_rule":{"alt":[{"stem":"사각형의 세 각이 100°, 120°, 65°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"75°","correct":true},{"t":"285°","mis":"M4-1-u2-X17"},{"t":"140°","mis":"M4-1-u2-X17"},{"t":"85°","mis":"M4-1-u2-X13"}],"explanation":["네 각의 합은 360°예요.","360 − 100 − 120 − 65 = 75.","나머지 한 각은 75°예요."],"asset":null},{"stem":"사각형의 세 각이 140°, 70°, 90°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"60°","correct":true},{"t":"300°","mis":"M4-1-u2-X17"},{"t":"150°","mis":"M4-1-u2-X17"},{"t":"70°","mis":"M4-1-u2-X13"}],"explanation":["네 각의 합은 360°예요.","360 − 140 − 70 − 90 = 60.","나머지 한 각은 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#14','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C10',2,'mc','auto','두 삼각자로 75°를 만들려고 해요. 알맞은 방법은 어느 것인가요?',ARRAY['M4-1-u2-X18']::text[],true,'{"seq":14,"concept":"M4-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 삼각자로 75°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"45°와 30°를 붙여서","correct":true},{"t":"90°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"30°와 30°를 붙여서","mis":"M4-1-u2-X18"},{"t":"45°와 60°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","45°와 30°를 붙여서 → 75°.","답은 「45°와 30°를 붙여서」예요."],"variant_rule":{"alt":[{"stem":"두 삼각자로 30°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"90° 위에 60°를 겹쳐서","correct":true},{"t":"45°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"45°와 45°를 붙여서","mis":"M4-1-u2-X18"},{"t":"30°와 30°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","90° 위에 60°를 겹쳐서 → 30°.","답은 「90° 위에 60°를 겹쳐서」예요."],"asset":null},{"stem":"두 삼각자로 60°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"90° 위에 30°를 겹쳐서","correct":true},{"t":"60°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"90°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"30°와 60°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","90° 위에 30°를 겹쳐서 → 60°.","답은 「90° 위에 30°를 겹쳐서」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#15','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C2',2,'mc','auto','같은 크기의 단위 각으로 재었더니 ㉮에는 5칸, ㉯에는 12칸 들어갔어요. 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X19','M4-1-u2-X04']::text[],true,'{"seq":15,"concept":"M4-1-u2-C2","difficulty":2,"kind":"mc","stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 5칸, ㉯에는 12칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","5칸과 12칸 — ㉯에 더 많이 들어갔어요.","더 큰 각은 ㉯예요."],"variant_rule":{"alt":[{"stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 6칸, ㉯에는 4칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","6칸과 4칸 — ㉮에 더 많이 들어갔어요.","더 큰 각은 ㉮예요."],"asset":null},{"stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 9칸, ㉯에는 11칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","9칸과 11칸 — ㉯에 더 많이 들어갔어요.","더 큰 각은 ㉯예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#16','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C5',2,'sa','auto','25°, 55°, 91°, 100°, 160° 가운데 둔각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u2-C5","difficulty":2,"kind":"sa","stem":"25°, 55°, 91°, 100°, 160° 가운데 둔각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["둔각은 90°보다 크고 180°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","둔각은 91°, 100°, 160°. — 3개."],"variant_rule":{"alt":[{"stem":"89°, 115°, 130°, 160°, 180° 가운데 예각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["예각은 0°보다 크고 90°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","예각은 89°. — 1개."],"asset":null},{"stem":"25°, 85°, 91°, 115°, 180° 가운데 둔각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["둔각은 90°보다 크고 180°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","둔각은 91°, 115°. — 2개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#17','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C4',3,'error','auto','같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X06','M4-1-u2-X19']::text[],true,'{"seq":17,"concept":"M4-1-u2-C4","difficulty":3,"kind":"error","stem":"같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「이 각은 50°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"나래 — 「이 각은 130°예요」","mis":"M4-1-u2-X19"},{"t":"서아 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 왼쪽에 있어요.","그쪽 0에서 시작하는 눈금은 130°.","도윤은 다른 줄 눈금(50°)을 읽었어요."],"asset":{"type":"prot","deg":130,"from":"left"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지호 — 「이 각은 85°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"하람 — 「이 각은 95°예요」","mis":"M4-1-u2-X19"},{"t":"준서 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 왼쪽에 있어요.","그쪽 0에서 시작하는 눈금은 95°.","지호는 다른 줄 눈금(85°)을 읽었어요."],"asset":{"type":"prot","deg":95,"from":"left"}},{"stem":"이번에는 다른 각이에요. 같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「이 각은 155°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"예린 — 「이 각은 25°예요」","mis":"M4-1-u2-X19"},{"t":"서아 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 오른쪽에 있어요.","그쪽 0에서 시작하는 눈금은 25°.","하람은 다른 줄 눈금(155°)을 읽었어요."],"asset":{"type":"prot","deg":25,"from":"right"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
