INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#21','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C6',3,'mc','auto','각도기로 재니 135°인 각을 준서는 약 130°, 나래는 약 165°, 서아는 약 155°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?',ARRAY['M4-1-u2-X12']::text[],true,'{"seq":21,"concept":"M4-1-u2-C6","difficulty":3,"kind":"mc","stem":"각도기로 재니 135°인 각을 준서는 약 130°, 나래는 약 165°, 서아는 약 155°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"준서","correct":true},{"t":"나래","mis":"M4-1-u2-X12"},{"t":"서아","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","준서 5°, 나래 30°, 서아 20° 차이.","차가 가장 작은 준서가 가장 잘 어림했어요."],"variant_rule":{"alt":[{"stem":"각도기로 재니 75°인 각을 서아는 약 105°, 예린는 약 95°, 도윤는 약 60°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"도윤","correct":true},{"t":"서아","mis":"M4-1-u2-X12"},{"t":"예린","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","서아 30°, 예린 20°, 도윤 15° 차이.","차가 가장 작은 도윤이 가장 잘 어림했어요."],"asset":null},{"stem":"각도기로 재니 40°인 각을 서아는 약 25°, 예린는 약 45°, 도윤는 약 60°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"예린","correct":true},{"t":"도윤","mis":"M4-1-u2-X12"},{"t":"서아","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","서아 15°, 예린 5°, 도윤 20° 차이.","차가 가장 작은 예린이 가장 잘 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#22','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C10',3,'mc','auto','두 삼각자로 만들 수 없는 각은 어느 것인가요?',ARRAY['M4-1-u2-X20']::text[],true,'{"seq":22,"concept":"M4-1-u2-C10","difficulty":3,"kind":"mc","stem":"두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"155°","correct":true},{"t":"105°","mis":"M4-1-u2-X20"},{"t":"135°","mis":"M4-1-u2-X20"},{"t":"15°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","155°는 15의 배수가 아니에요.","만들 수 없는 각은 155°예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"20°","correct":true},{"t":"30°","mis":"M4-1-u2-X20"},{"t":"105°","mis":"M4-1-u2-X20"},{"t":"75°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","20°는 15의 배수가 아니에요.","만들 수 없는 각은 20°예요."],"asset":null},{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"95°","correct":true},{"t":"15°","mis":"M4-1-u2-X20"},{"t":"120°","mis":"M4-1-u2-X20"},{"t":"60°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","95°는 15의 배수가 아니에요.","만들 수 없는 각은 95°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#23','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C9',4,'sa','auto','사각형의 두 각이 140°, 90°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u2-C9","difficulty":4,"kind":"sa","stem":"사각형의 두 각이 140°, 90°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["네 각의 합은 360°예요.","360 − 140 − 90 = 130.","130 ÷ 2 = 65 — 한 각은 65°예요."],"variant_rule":{"alt":[{"stem":"사각형의 두 각이 105°, 115°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["네 각의 합은 360°예요.","360 − 105 − 115 = 140.","140 ÷ 2 = 70 — 한 각은 70°예요."],"asset":null},{"stem":"사각형의 두 각이 120°, 90°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["네 각의 합은 360°예요.","360 − 120 − 90 = 150.","150 ÷ 2 = 75 — 한 각은 75°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#24','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C8',4,'sa','auto','삼각형의 한 각이 75°예요. 나머지 두 각 중 한 각은 다른 한 각의 4배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u2-C8","difficulty":4,"kind":"sa","stem":"삼각형의 한 각이 75°예요. 나머지 두 각 중 한 각은 다른 한 각의 4배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["나머지 두 각의 합: 180 − 75 = 105.","작은 각을 5묶음으로 보면 105 ÷ 5 = 21.","더 작은 각은 21°예요 (큰 각 84°)."],"variant_rule":{"alt":[{"stem":"삼각형의 한 각이 35°예요. 나머지 두 각 중 한 각은 다른 한 각의 4배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["나머지 두 각의 합: 180 − 35 = 145.","작은 각을 5묶음으로 보면 145 ÷ 5 = 29.","더 작은 각은 29°예요 (큰 각 116°)."],"asset":null},{"stem":"삼각형의 한 각이 70°예요. 나머지 두 각 중 한 각은 다른 한 각의 4배예요. 더 작은 각은 몇 도인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["나머지 두 각의 합: 180 − 70 = 110.","작은 각을 5묶음으로 보면 110 ÷ 5 = 22.","더 작은 각은 22°예요 (큰 각 88°)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_b#25','math',4,1,'u2','','g4_1_math_u2_review_b','unit_review','M4-1-u2-C8',4,'essay','teacher','삼각형의 두 각이 45°, 75°예요. 나머지 한 각을 구하고, 이 삼각형의 세 각 중 예각과 둔각이 각각 몇 개인지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u2-C8","difficulty":4,"kind":"essay","stem":"삼각형의 두 각이 45°, 75°예요. 나머지 한 각을 구하고, 이 삼각형의 세 각 중 예각과 둔각이 각각 몇 개인지 설명해 보세요.","answer_guide":{"answer":"예: 180° − 45° − 75° = 60°이다. 세 각 45°·75°·60°는 모두 90°보다 작으므로 예각이 3개, 둔각은 0개이다.","scoring_points":["60°를 구했는가","세 각을 직각과 견주었는가","예각 3개·둔각 0개라고 했는가"]},"explanation":["180 − 45 − 75 = 60.","세 각 모두 90°보다 작아요.","예각 3개, 둔각 0개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_c#1','math',4,1,'u2','','g4_1_math_u2_review_c','unit_review','M4-1-u2-C3',1,'sa','auto','직각 3개를 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C3","difficulty":1,"kind":"sa","stem":"직각 3개를 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.","answer":["270"],"explanation":["직각은 90°예요.","90 × 3 = 270.","답은 270°예요."],"variant_rule":{"alt":[{"stem":"직각은 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["한 바퀴 360°를 똑같이 넷으로 나눈 각이에요.","360 ÷ 4 = 90.","답은 90°예요."],"asset":null},{"stem":"직각 4개를 한 점에 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.","answer":["360"],"explanation":["직각은 90°예요.","90 × 4 = 360 — 한 바퀴예요.","답은 360°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_c#2','math',4,1,'u2','','g4_1_math_u2_review_c','unit_review','M4-1-u2-C2',1,'mc','auto','두 각 중 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X01']::text[],true,'{"seq":2,"concept":"M4-1-u2-C2","difficulty":1,"kind":"mc","stem":"두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉯가 더 많이 벌어졌어요.","더 큰 각은 ㉯예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,122.066017178],[166.0,122.066017178]],[[16.0,122.066017178],[122.066017178,16.0]]],"arc":[[[166.0,122.066017178],[16.0,122.066017178],[122.066017178,16.0]]],"w":182,"h":138},{"seg":[[[65.497474683,65.497474683],[135.497474683,65.497474683]],[[65.497474683,65.497474683],[16.0,16.0]]],"arc":[[[135.497474683,65.497474683],[65.497474683,65.497474683],[16.0,16.0]]],"w":151,"h":81}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉯가 더 많이 벌어졌어요.","더 큰 각은 ㉯예요."],"asset":{"type":"geo","items":[{"seg":[[[79.392739261,151.946168055],[229.392739261,151.946168055]],[[79.392739261,151.946168055],[16.0,16.0]]],"arc":[[[229.392739261,151.946168055],[79.392739261,151.946168055],[16.0,16.0]]],"w":245,"h":168},{"seg":[[[73.3406431,56.150350545],[143.3406431,56.150350545]],[[73.3406431,56.150350545],[16.0,16.0]]],"arc":[[[143.3406431,56.150350545],[73.3406431,56.150350545],[16.0,16.0]]],"w":159,"h":72}]}},{"stem":"이번에는 다른 각이에요. 두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크