INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_c#9','math',4,1,'u2','','g4_1_math_u2_review_c','unit_review','M4-1-u2-C4',2,'mc','auto','각도기로 잰 각의 크기는 몇 도인가요?',ARRAY['M4-1-u2-X06','M4-1-u2-X08']::text[],true,'{"seq":9,"concept":"M4-1-u2-C4","difficulty":2,"kind":"mc","stem":"각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"32°","correct":true},{"t":"148°","mis":"M4-1-u2-X06"},{"t":"42°","mis":"M4-1-u2-X08"},{"t":"22°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 오른쪽에 있어요 — 오른쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 32°.","148°는 다른 줄을 읽은 값이에요. 답은 32°예요."],"asset":{"type":"prot","deg":32,"from":"right"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"62°","correct":true},{"t":"118°","mis":"M4-1-u2-X06"},{"t":"72°","mis":"M4-1-u2-X08"},{"t":"52°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 왼쪽에 있어요 — 왼쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 62°.","118°는 다른 줄을 읽은 값이에요. 답은 62°예요."],"asset":{"type":"prot","deg":62,"from":"left"}},{"stem":"이번에는 다른 각이에요. 각도기로 잰 각의 크기는 몇 도인가요?","options":[{"t":"143°","correct":true},{"t":"37°","mis":"M4-1-u2-X06"},{"t":"153°","mis":"M4-1-u2-X08"},{"t":"133°","mis":"M4-1-u2-X08"}],"explanation":["밑금 위 변이 오른쪽에 있어요 — 오른쪽이 0인 눈금을 따라가요.","다른 변이 가리키는 눈금은 143°.","37°는 다른 줄을 읽은 값이에요. 답은 143°예요."],"asset":{"type":"prot","deg":143,"from":"right"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
