INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_c#21','math',4,1,'u2','','g4_1_math_u2_review_c','unit_review','M4-1-u2-C6',3,'mc','auto','각도기로 재니 80°인 각을 서아는 약 50°, 예린는 약 90°, 도윤는 약 95°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?',ARRAY['M4-1-u2-X12']::text[],true,'{"seq":21,"concept":"M4-1-u2-C6","difficulty":3,"kind":"mc","stem":"각도기로 재니 80°인 각을 서아는 약 50°, 예린는 약 90°, 도윤는 약 95°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"예린","correct":true},{"t":"서아","mis":"M4-1-u2-X12"},{"t":"도윤","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","서아 30°, 예린 10°, 도윤 15° 차이.","차가 가장 작은 예린이 가장 잘 어림했어요."],"variant_rule":{"alt":[{"stem":"각도기로 재니 115°인 각을 준서는 약 120°, 예린는 약 145°, 서아는 약 130°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"준서","correct":true},{"t":"예린","mis":"M4-1-u2-X12"},{"t":"서아","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","준서 5°, 예린 30°, 서아 15° 차이.","차가 가장 작은 준서가 가장 잘 어림했어요."],"asset":null},{"stem":"각도기로 재니 55°인 각을 도윤는 약 75°, 지호는 약 65°, 은비는 약 60°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"은비","correct":true},{"t":"도윤","mis":"M4-1-u2-X12"},{"t":"지호","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","도윤 20°, 지호 10°, 은비 5° 차이.","차가 가장 작은 은비가 가장 잘 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_c#22','math',4,1,'u2','','g4_1_math_u2_review_c','unit_review','M4-1-u2-C10',3,'mc','auto','두 삼각자로 만들 수 없는 각은 어느 것인가요?',ARRAY['M4-1-u2-X20']::text[],true,'{"seq":22,"concept":"M4-1-u2-C10","difficulty":3,"kind":"mc","stem":"두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"25°","correct":true},{"t":"75°","mis":"M4-1-u2-X20"},{"t":"120°","mis":"M4-1-u2-X20"},{"t":"105°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","25°는 15의 배수가 아니에요.","만들 수 없는 각은 25°예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"140°","correct":true},{"t":"150°","mis":"M4-1-u2-X20"},{"t":"30°","mis":"M4-1-u2-X20"},{"t":"75°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","140°는 15의 배수가 아니에요.","만들 수 없는 각은 140°예요."],"asset":null},{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"10°","correct":true},{"t":"75°","mis":"M4-1-u2-X20"},{"t":"135°","mis":"M4-1-u2-X20"},{"t":"150°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","10°는 15의 배수가 아니에요.","만들 수 없는 각은 10°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_c#23','math',4,1,'u2','','g4_1_math_u2_review_c','unit_review','M4-1-u2-C9',4,'sa','auto','사각형의 두 각이 85°, 75°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u2-C9","difficulty":4,"kind":"sa","stem":"사각형의 두 각이 85°, 75°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["네 각의 합은 360°예요.","360 − 85 − 75 = 200.","200 ÷ 2 = 100 — 한 각은 100°예요."],"variant_rule":{"alt":[{"stem":"사각형의 두 각이 100°, 50°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["네 각의 합은 360°예요.","360 − 100 − 50 = 210.","210 ÷ 2 = 105 — 한 각은 105°예요."],"asset":null},{"stem":"사각형의 두 각이 100°, 120°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["네 각의 합은 360°예요.","360 − 100 − 120 = 140.","140 ÷ 2 = 70 — 한 각은 70°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_c#24','math',4,1,'u2','','g4_1_math_u2_review_c','unit_review','M4-1-u2-C7',4,'sa','auto','한 점을 둘러싼 네 각 중 두 각이 90°, 130°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u2-C7","difficulty":4,"kind":"sa","stem":"한 점을 둘러싼 네 각 중 두 각이 90°, 130°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 90 − 130 = 140, 140 ÷ 2 = 70.","한 각은 70°예요."],"variant_rule":{"alt":[{"stem":"한 점을 둘러싼 네 각 중 두 각이 60°, 80°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["110"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 60 − 80 = 220, 220 ÷ 2 = 110.","한 각은 110°예요."],"asset":null},{"stem":"한 점을 둘러싼 네 각 중 두 각이 145°, 105°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 145 − 105 = 110, 110 ÷ 2 = 55.","한 각은 55°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_c#25','math',4,1,'u2','','g4_1_math_u2_review_c','unit_review','M4-1-u2-C9',4,'essay','teacher','사각형의 네 각 중 두 각이 직각이고, 나머지 두 각 중 한 각이 115°예요. 남은 한 각을 구하는 풀이 과정을 쓰고 그 각이 예각인지 둔각인지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u2-C9","difficulty":4,"kind":"essay","stem":"사각형의 네 각 중 두 각이 직각이고, 나머지 두 각 중 한 각이 115°예요. 남은 한 각을 구하는 풀이 과정을 쓰고 그 각이 예각인지 둔각인지 써 보세요.","answer_guide":{"answer":"예: 360° − 90° − 90° − 115° = 65°이다. 65°는 90°보다 작으므로 예각이다.","scoring_points":["네 각의 합 360°를 썼는가","65°를 구했는가","예각이라고 답했는가"]},"explanation":["360 − 90 − 90 − 115 = 65.","65° < 90°.","예각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#1','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C3',1,'sa','auto','1°짜리 각이 몇 개 모이면 직각이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u2-C3","difficulty":1,"kind":"sa","stem":"1°짜리 각이 몇 개 모이면 직각이 되나요? 숫자로 쓰세요.","answer":["90"],"explanation":["직각은 90°예요.","1°가 90개면 90°.","답은 90°예요."],"variant_rule":{"alt":[{"stem":"한 바퀴의 반만큼 돈 각(일직선)은 몇 도인가요? 숫자로 쓰세요.","answer":["180"],"explanation":["한 바퀴 360°의 반이에요.","360 ÷ 2 = 180.","답은 180°예요."],"asset":null},{"stem":"직각 3개를 이어 붙인 각은 몇 도인가요? 숫자로 쓰세요.","answer":["270"],"explanation":["직각은 90°예요.","90 × 3 = 270.","답은 270°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#2','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C2',1,'mc','auto','두 각 중 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X01']::text[],true,'{"seq":2,"concept":"M4-1-u2-C2","difficulty":1,"kind":"mc","stem":"두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉯가 더 많이 벌어졌어요.","더 큰 각은 ㉯예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,130.906666468],[166.0,130.906666468]],[[16.0,130.906666468],[112.418141453,16.0]]],"arc":[[[166.0,130.906666468],[16.0,130.906666468],[112.418141453,16.0]]],"w":182,"h":147},{"seg":[[[16.0,85.733628866],[86.0,85.733628866]],[[16.0,85.733628866],[22.100901992,16.0]]],"arc":[[[86.0,85.733628866],[16.0,85.733628866],[22.100901992,16.0]]],"w":102,"h":102}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수 있어요","mis":"M4-1-u2-X01"}],"explanation":["각의 크기는 두 변이 벌어진 정도예요 — 변의 길이와는 상관없어요.","㉯가 더 많이 벌어졌어요.","더 큰 각은 ㉯예요."],"asset":{"type":"geo","items":[{"seg":[[[16.0,163.721162952],[166.0,163.721162952]],[[16.0,163.721162952],[42.04722665,16.0]]],"arc":[[[166.0,163.721162952],[16.0,163.721162952],[42.04722665,16.0]]],"w":182,"h":180},{"seg":[[[73.3406431,56.150350545],[143.3406431,56.150350545]],[[73.3406431,56.150350545],[16.0,16.0]]],"arc":[[[143.3406431,56.150350545],[73.3406431,56.150350545],[16.0,16.0]]],"w":159,"h":72}]}},{"stem":"이번에는 다른 각이에요. 두 각 중 더 큰 각은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u2-X01"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X01"},{"t":"변의 길이를 재어 봐야 알 수