INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#11','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C7',2,'sa','auto','일직선 위에 한 각이 30°예요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M4-1-u2-C7","difficulty":2,"kind":"sa","stem":"일직선 위에 한 각이 30°예요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["150"],"explanation":["일직선은 180°예요.","180 − 30 = 150.","?는 150°예요."],"asset":{"type":"geo","items":[{"seg":[[[131.0,73.5],[246.0,73.5]],[[131.0,73.5],[230.592921435,16.0]],[[131.0,73.5],[16.0,73.5]]],"arc":[[[246.0,73.5],[131.0,73.5],[230.592921435,16.0]],[[230.592921435,16.0],[131.0,73.5],[16.0,73.5]]],"lab":[[[186.980762114,58.5],"30°"],[[122.200152467,40.658521906],"?"]],"w":262,"h":90}],"tag":false},"variant_rule":{"alt":[{"stem":"일직선 위에 한 각이 90°예요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["일직선은 180°예요.","180 − 90 = 90.","?는 90°예요."],"asset":{"type":"geo","items":[{"seg":[[[131.0,131.0],[246.0,131.0]],[[131.0,131.0],[131.0,16.0]],[[131.0,131.0],[16.0,131.0]]],"arc":[[[131.0,16.0],[131.0,131.0],[16.0,131.0]]],"lab":[[[155.04163056,106.95836944],"90°"],[[106.95836944,106.95836944],"?"]],"right":[[[246.0,131.0],[131.0,131.0],[131.0,16.0]]],"w":262,"h":147}],"tag":false}},{"stem":"일직선 위에 한 각이 130°예요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["일직선은 180°예요.","180 − 130 = 50.","?는 50°예요."],"asset":{"type":"geo","items":[{"seg":[[[131.0,104.095110959],[246.0,104.095110959]],[[131.0,104.095110959],[57.079424886,16.0]],[[131.0,104.095110959],[16.0,104.095110959]]],"arc":[[[246.0,104.095110959],[131.0,104.095110959],[57.079424886,16.0]],[[57.079424886,16.0],[131.0,104.095110959],[16.0,104.095110959]]],"lab":[[[145.369020899,73.280646199],"130°"],[[98.832396192,89.095110959],"?"]],"w":262,"h":120}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.c