INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#12','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C8',2,'mc','auto','삼각형의 두 각이 60°, 90°예요. 나머지 한 각은 몇 도인가요?',ARRAY['M4-1-u2-X15','M4-1-u2-X17']::text[],true,'{"seq":12,"concept":"M4-1-u2-C8","difficulty":2,"kind":"mc","stem":"삼각형의 두 각이 60°, 90°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"30°","correct":true},{"t":"210°","mis":"M4-1-u2-X15"},{"t":"120°","mis":"M4-1-u2-X17"},{"t":"150°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 60 − 90 = 30.","나머지 한 각은 30°예요."],"variant_rule":{"alt":[{"stem":"삼각형의 두 각이 50°, 50°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"80°","correct":true},{"t":"260°","mis":"M4-1-u2-X15"},{"t":"130°","mis":"M4-1-u2-X17"},{"t":"100°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 50 − 50 = 80.","나머지 한 각은 80°예요."],"asset":null},{"stem":"삼각형의 두 각이 25°, 55°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"100°","correct":true},{"t":"280°","mis":"M4-1-u2-X15"},{"t":"155°","mis":"M4-1-u2-X17"},{"t":"80°","mis":"M4-1-u2-X17"}],"explanation":["세 각의 합은 180°예요.","180 − 25 − 55 = 100.","나머지 한 각은 100°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#13','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C9',2,'mc','auto','사각형의 세 각이 70°, 65°, 140°예요. 나머지 한 각은 몇 도인가요?',ARRAY['M4-1-u2-X17','M4-1-u2-X13']::text[],true,'{"seq":13,"concept":"M4-1-u2-C9","difficulty":2,"kind":"mc","stem":"사각형의 세 각이 70°, 65°, 140°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"85°","correct":true},{"t":"275°","mis":"M4-1-u2-X17"},{"t":"225°","mis":"M4-1-u2-X17"},{"t":"95°","mis":"M4-1-u2-X13"}],"explanation":["네 각의 합은 360°예요.","360 − 70 − 65 − 140 = 85.","나머지 한 각은 85°예요."],"variant_rule":{"alt":[{"stem":"사각형의 세 각이 80°, 110°, 115°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"55°","correct":true},{"t":"305°","mis":"M4-1-u2-X17"},{"t":"170°","mis":"M4-1-u2-X17"},{"t":"65°","mis":"M4-1-u2-X13"}],"explanation":["네 각의 합은 360°예요.","360 − 80 − 110 − 115 = 55.","나머지 한 각은 55°예요."],"asset":null},{"stem":"사각형의 세 각이 95°, 130°, 75°예요. 나머지 한 각은 몇 도인가요?","options":[{"t":"60°","correct":true},{"t":"300°","mis":"M4-1-u2-X17"},{"t":"135°","mis":"M4-1-u2-X17"},{"t":"70°","mis":"M4-1-u2-X13"}],"explanation":["네 각의 합은 360°예요.","360 − 95 − 130 − 75 = 60.","나머지 한 각은 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#14','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C10',2,'mc','auto','두 삼각자로 150°를 만들려고 해요. 알맞은 방법은 어느 것인가요?',ARRAY['M4-1-u2-X18']::text[],true,'{"seq":14,"concept":"M4-1-u2-C10","difficulty":2,"kind":"mc","stem":"두 삼각자로 150°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"90°와 60°를 붙여서","correct":true},{"t":"90°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"30°와 30°를 붙여서","mis":"M4-1-u2-X18"},{"t":"45°와 45°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","90°와 60°를 붙여서 → 150°.","답은 「90°와 60°를 붙여서」예요."],"variant_rule":{"alt":[{"stem":"두 삼각자로 60°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"90° 위에 30°를 겹쳐서","correct":true},{"t":"60°와 60°를 붙여서","mis":"M4-1-u2-X18"},{"t":"90°와 90°를 붙여서","mis":"M4-1-u2-X18"},{"t":"60°와 90°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","90° 위에 30°를 겹쳐서 → 60°.","답은 「90° 위에 30°를 겹쳐서」예요."],"asset":null},{"stem":"두 삼각자로 75°를 만들려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"45°와 30°를 붙여서","correct":true},{"t":"45°와 45°를 붙여서","mis":"M4-1-u2-X18"},{"t":"60°와 60°를 붙여서","mis":"M4-1-u2-X18"},{"t":"45°와 60°를 붙여서","mis":"M4-1-u2-X18"}],"explanation":["삼각자 ㉮는 45°·45°·90°, ㉯는 30°·60°·90°예요.","45°와 30°를 붙여서 → 75°.","답은 「45°와 30°를 붙여서」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#15','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C2',2,'mc','auto','같은 크기의 단위 각으로 재었더니 ㉮에는 10칸, ㉯에는 7칸 들어갔어요. 더 큰 각은 어느 것인가요?',ARRAY['M4-1-u2-X19','M4-1-u2-X04']::text[],true,'{"seq":15,"concept":"M4-1-u2-C2","difficulty":2,"kind":"mc","stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 10칸, ㉯에는 7칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","10칸과 7칸 — ㉮에 더 많이 들어갔어요.","더 큰 각은 ㉮예요."],"variant_rule":{"alt":[{"stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 8칸, ㉯에는 10칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","8칸과 10칸 — ㉯에 더 많이 들어갔어요.","더 큰 각은 ㉯예요."],"asset":null},{"stem":"같은 크기의 단위 각으로 재었더니 ㉮에는 7칸, ㉯에는 5칸 들어갔어요. 더 큰 각은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M4-1-u2-X19"},{"t":"두 각의 크기가 같아요","mis":"M4-1-u2-X04"},{"t":"단위 각으로는 견줄 수 없어요","mis":"M4-1-u2-X04"}],"explanation":["단위 각의 크기가 같으면 칸이 많이 들어간 각이 커요.","7칸과 5칸 — ㉮에 더 많이 들어갔어요.","더 큰 각은 ㉮예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#16','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C5',2,'sa','auto','70°, 85°, 115°, 160°, 180° 가운데 예각은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u2-C5","difficulty":2,"kind":"sa","stem":"70°, 85°, 115°, 160°, 180° 가운데 예각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["예각은 0°보다 크고 90°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","예각은 70°, 85°. — 2개."],"variant_rule":{"alt":[{"stem":"10°, 85°, 89°, 115°, 130° 가운데 둔각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["둔각은 90°보다 크고 180°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","둔각은 115°, 130°. — 2개."],"asset":null},{"stem":"10°, 25°, 40°, 130°, 145° 가운데 예각은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["예각은 0°보다 크고 90°보다 작은 각.","90°는 직각, 180°는 일직선이라 넣지 않아요.","예각은 10°, 25°, 40°. — 3개."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#17','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C4',3,'error','auto','같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M4-1-u2-X06','M4-1-u2-X19']::text[],true,'{"seq":17,"concept":"M4-1-u2-C4","difficulty":3,"kind":"error","stem":"같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「이 각은 100°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"도윤 — 「이 각은 80°예요」","mis":"M4-1-u2-X19"},{"t":"지호 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 왼쪽에 있어요.","그쪽 0에서 시작하는 눈금은 80°.","준서는 다른 줄 눈금(100°)을 읽었어요."],"asset":{"type":"prot","deg":80,"from":"left"},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"예린 — 「이 각은 110°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"서아 — 「이 각은 70°예요」","mis":"M4-1-u2-X19"},{"t":"도윤 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 왼쪽에 있어요.","그쪽 0에서 시작하는 눈금은 70°.","예린은 다른 줄 눈금(110°)을 읽었어요."],"asset":{"type":"prot","deg":70,"from":"left"}},{"stem":"이번에는 다른 각이에요. 같은 각을 각도기로 재고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나래 — 「이 각은 50°예요」","correct":true,"mis_target":"M4-1-u2-X06"},{"t":"도윤 — 「이 각은 130°예요」","mis":"M4-1-u2-X19"},{"t":"지호 — 「밑금 위 변 쪽 0에서부터 읽었어요.」","mis":"M4-1-u2-X19"}],"explanation":["밑금 위 변이 오른쪽에 있어요.","그쪽 0에서 시작하는 눈금은 130°.","나래는 다른 줄 눈금(50°)을 읽었어요."],"asset":{"type":"prot","deg":130,"from":"right"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
