INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#19','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C8',3,'sa','auto','삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M4-1-u2-C8","difficulty":3,"kind":"sa","stem":"삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["삼각형의 나머지 한 각: 180 − 60 − 40 = 80.","그 각과 ?가 일직선을 이루어요: 180 − 80 = 100.","?는 100°예요 (= 60 + 40)."],"asset":{"type":"geo","items":[{"poly":[[[16.0,174.046720163],[216.0,174.046720163],[81.270364467,60.995132678]]],"seg":[[[81.270364467,60.995132678],[27.647253448,16.0]]],"arc":[[[27.647253448,16.0],[81.270364467,60.995132678],[16.0,174.046720163]]],"lab":[[[61.033320997,148.046720163],"60°"],[[155.85967227,152.15743099],"40°"],[[39.90843884,68.28835614],"?"]],"w":232,"h":190}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["135"],"explanation":["삼각형의 나머지 한 각: 180 − 75 − 60 = 45.","그 각과 ?가 일직선을 이루어요: 180 − 45 = 135.","?는 135°예요 (= 75 + 60)."],"asset":{"type":"geo","items":[{"poly":[[[16.0,313.224318643],[216.0,313.224318643],[79.397459622,76.621778265]]],"seg":[[[79.397459622,76.621778265],[44.397459622,16.0]]],"arc":[[[44.397459622,16.0],[79.397459622,76.621778265],[16.0,313.224318643]]],"lab":[[[57.254373695,281.568724335],"75°"],[[170.966679003,287.224318643],"60°"],[[37.756775444,82.103878338],"?"]],"w":232,"h":329}],"tag":false}},{"stem":"이번에는 다른 각이에요. 삼각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["150"],"explanation":["삼각형의 나머지 한 각: 180 − 100 − 50 = 30.","그 각과 ?가 일직선을 이루어요: 180 − 30 = 150.","?는 150°예요 (= 100 + 50)."],"asset":{"type":"geo","items":[{"poly":[[[121.273815679,371.385713713],[321.273815679,371.385713713],[68.064927056,69.623111018]]],"seg":[[[68.064927056,69.623111018],[23.069794377,16.0]]],"arc":[[[23.