INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#20','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C9',3,'sa','auto','사각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M4-1-u2-C9","difficulty":3,"kind":"sa","stem":"사각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["사각형의 나머지 한 각: 360 − 85 − 70 − 120 = 85.","그 각과 ?가 일직선: 180 − 85 = 95.","?는 95°예요."],"asset":{"type":"geo","items":[{"poly":[[[16.0,293.209323132],[241.0,293.209323132],[164.045467752,81.778483455],[28.987907775,144.756857964]]],"seg":[[[164.045467752,81.778483455],[140.104057719,16.0]]],"arc":[[[140.104057719,16.0],[164.045467752,81.778483455],[28.987907775,144.756857964]]],"lab":[[[54.338421514,258.078632336],"85°"],[[198.404093697,263.383348442],"70°"],[[61.753989546,167.699915418],"120°"],[[125.242527386,65.705779296],"?"]],"w":257,"h":309}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 사각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["사각형의 나머지 한 각: 360 − 130 − 55 − 95 = 80.","그 각과 ?가 일직선: 180 − 80 = 100.","?는 100°예요."],"asset":{"type":"geo","items":[{"poly":[[[77.075063885,248.487747268],[241.0,248.487747268],[118.360677366,73.3406431],[16.0,175.701320466]]],"seg":[[[118.360677366,73.3406431],[78.210326821,16.0]]],"arc":[[[78.210326821,16.0],[118.360677366,73.3406431],[16.0,175.701320466]]],"lab":[[[93.979794354,212.235435787],"130°"],[[184.231306677,218.935836021],"55°"],[[67.950507522,177.969528609],"95°"],[[76.520500046,69.680101905],"?"]],"w":257,"h":264}],"tag":false}},{"stem":"이번에는 다른 각이에요. 사각형의 한 변을 늘였어요. ?는 몇 도인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["사각형의 나머지 한 각: 360 − 115 − 115 − 70 = 60.","그 각과 ?가 일직선: 180 − 60 = 120.","?는 120°예요."],"asset":{"type":"geo","items":[{"poly":[[[76.410994958,228.678291148],[171.409762436,228.678