INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#21','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C6',3,'mc','auto','각도기로 재니 65°인 각을 준서는 약 70°, 은비는 약 85°, 하람는 약 75°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?',ARRAY['M4-1-u2-X12']::text[],true,'{"seq":21,"concept":"M4-1-u2-C6","difficulty":3,"kind":"mc","stem":"각도기로 재니 65°인 각을 준서는 약 70°, 은비는 약 85°, 하람는 약 75°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"준서","correct":true},{"t":"은비","mis":"M4-1-u2-X12"},{"t":"하람","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","준서 5°, 은비 20°, 하람 10° 차이.","차가 가장 작은 준서가 가장 잘 어림했어요."],"variant_rule":{"alt":[{"stem":"각도기로 재니 155°인 각을 서아는 약 150°, 예린는 약 125°, 도윤는 약 145°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"서아","correct":true},{"t":"예린","mis":"M4-1-u2-X12"},{"t":"도윤","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","서아 5°, 예린 30°, 도윤 10° 차이.","차가 가장 작은 서아가 가장 잘 어림했어요."],"asset":null},{"stem":"각도기로 재니 100°인 각을 준서는 약 130°, 예린는 약 105°, 서아는 약 90°로 어림했어요. 가장 잘 어림한 친구는 누구인가요?","options":[{"t":"예린","correct":true},{"t":"준서","mis":"M4-1-u2-X12"},{"t":"서아","mis":"M4-1-u2-X12"},{"t":"세 친구 모두 똑같이 잘했어요","mis":"M4-1-u2-X12"}],"explanation":["잰 값과의 차를 구해요.","준서 30°, 예린 5°, 서아 10° 차이.","차가 가장 작은 예린이 가장 잘 어림했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#22','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C10',3,'mc','auto','두 삼각자로 만들 수 없는 각은 어느 것인가요?',ARRAY['M4-1-u2-X20']::text[],true,'{"seq":22,"concept":"M4-1-u2-C10","difficulty":3,"kind":"mc","stem":"두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"20°","correct":true},{"t":"75°","mis":"M4-1-u2-X20"},{"t":"60°","mis":"M4-1-u2-X20"},{"t":"30°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","20°는 15의 배수가 아니에요.","만들 수 없는 각은 20°예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"115°","correct":true},{"t":"15°","mis":"M4-1-u2-X20"},{"t":"120°","mis":"M4-1-u2-X20"},{"t":"60°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","115°는 15의 배수가 아니에요.","만들 수 없는 각은 115°예요."],"asset":null},{"stem":"이번에는 다른 각이에요. 두 삼각자로 만들 수 없는 각은 어느 것인가요?","options":[{"t":"70°","correct":true},{"t":"105°","mis":"M4-1-u2-X20"},{"t":"150°","mis":"M4-1-u2-X20"},{"t":"75°","mis":"M4-1-u2-X20"}],"explanation":["삼각자 두 개로 만든 각은 모두 15°의 배수예요.","70°는 15의 배수가 아니에요.","만들 수 없는 각은 70°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#23','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C9',4,'sa','auto','사각형의 두 각이 100°, 130°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M4-1-u2-C9","difficulty":4,"kind":"sa","stem":"사각형의 두 각이 100°, 130°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["네 각의 합은 360°예요.","360 − 100 − 130 = 130.","130 ÷ 2 = 65 — 한 각은 65°예요."],"variant_rule":{"alt":[{"stem":"사각형의 두 각이 50°, 80°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["115"],"explanation":["네 각의 합은 360°예요.","360 − 50 − 80 = 230.","230 ÷ 2 = 115 — 한 각은 115°예요."],"asset":null},{"stem":"사각형의 두 각이 100°, 140°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["네 각의 합은 360°예요.","360 − 100 − 140 = 120.","120 ÷ 2 = 60 — 한 각은 60°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#24','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C7',4,'sa','auto','한 점을 둘러싼 네 각 중 두 각이 50°, 100°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u2-C7","difficulty":4,"kind":"sa","stem":"한 점을 둘러싼 네 각 중 두 각이 50°, 100°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["105"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 50 − 100 = 210, 210 ÷ 2 = 105.","한 각은 105°예요."],"variant_rule":{"alt":[{"stem":"한 점을 둘러싼 네 각 중 두 각이 95°, 75°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 95 − 75 = 190, 190 ÷ 2 = 95.","한 각은 95°예요."],"asset":null},{"stem":"한 점을 둘러싼 네 각 중 두 각이 60°, 130°이고 나머지 두 각은 크기가 같아요. 크기가 같은 한 각은 몇 도인가요? 숫자로 쓰세요.","answer":["85"],"explanation":["네 각의 합은 한 바퀴 360°예요.","360 − 60 − 130 = 170, 170 ÷ 2 = 85.","한 각은 85°예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u2_review_d#25','math',4,1,'u2','','g4_1_math_u2_review_d','unit_review','M4-1-u2-C10',4,'essay','teacher','두 삼각자로 105°와 15°를 각각 만드는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u2-C10","difficulty":4,"kind":"essay","stem":"두 삼각자로 105°와 15°를 각각 만드는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 105°는 45°와 60°를 나란히 붙여 만든다(45 + 60 = 105). 15°는 60° 위에 45°를 포개어 만든다(60 − 45 = 15).","scoring_points":["105° = 45° + 60°(붙이기)를 썼는가","15° = 60° − 45° 또는 45° − 30°(겹치기)를 썼는가","붙이면 합, 겹치면 차라고 했는가"]},"explanation":["붙이면 합.","겹치면 차.","105° = 45° + 60°, 15° = 60° − 45°."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
